ROBOFIBO_SCORE_EDGE = max(0.3, min(3.0, float(os.getenv("ROBOFIBO_SCORE_EDGE", "0.8"))))

# MEGA IA 3.95.0 — RSI TRIPLO 7/14/28.
# O sinal oficial é avaliado perto de 10 s antes do fechamento da vela atual
# para entrada na abertura da próxima. Depois de liberado, o snapshot fica travado.
TRIPRSI_FAST = max(3, min(14, int(os.getenv("TRIPRSI_FAST", "7"))))
TRIPRSI_MID = max(7, min(28, int(os.getenv("TRIPRSI_MID", "14"))))
TRIPRSI_SLOW = max(14, min(60, int(os.getenv("TRIPRSI_SLOW", "28"))))
TRIPRSI_CALL_FAST = max(50.0, min(70.0, float(os.getenv("TRIPRSI_CALL_FAST", "55"))))
TRIPRSI_CALL_MID = max(50.0, min(70.0, float(os.getenv("TRIPRSI_CALL_MID", "53"))))
TRIPRSI_CALL_SLOW = max(50.0, min(70.0, float(os.getenv("TRIPRSI_CALL_SLOW", "52"))))
TRIPRSI_PUT_FAST = max(30.0, min(50.0, float(os.getenv("TRIPRSI_PUT_FAST", "45"))))
TRIPRSI_PUT_MID = max(30.0, min(50.0, float(os.getenv("TRIPRSI_PUT_MID", "47"))))
TRIPRSI_PUT_SLOW = max(30.0, min(50.0, float(os.getenv("TRIPRSI_PUT_SLOW", "48"))))
TRIPRSI_EARLY_SIGNAL_SECONDS = 10
# O frontend normalmente consulta a cada ~5 s; 5..12 s captura o ponto de 10 s sem sinal tardio.
TRIPRSI_EARLY_MIN_REMAINING = max(3, min(8, int(os.getenv("TRIPRSI_EARLY_MIN_REMAINING", "5"))))
TRIPRSI_EARLY_WINDOW_BEFORE = max(10, min(15, int(os.getenv("TRIPRSI_EARLY_WINDOW_BEFORE", "12"))))
TRIPRSI_HISTORY_BARS = max(60, min(220, int(os.getenv("TRIPRSI_HISTORY_BARS", "120"))))


def triple_rsi_strategy(cs, timeframe="1min", market="OPEN", early_signal=False):
    """RSI Triplo 7/14/28 para a próxima vela.

    CALL: RSI rápido >55, médio >53, lento >52 e os três subindo.
    PUT: RSI rápido <45, médio <47, lento <48 e os três caindo.
    A faixa neutra do RSI lento (48..52) bloqueia entradas laterais.
    """
    rows=list(cs or [])
    tf_label={"1min":"M1","5min":"M5","15min":"M15","30min":"M30","1h":"H1"}.get(timeframe,timeframe)
    name=f"RSI TRIPLO 7/14/28 {tf_label}"
    need=max(40,TRIPRSI_SLOW+8)
    if len(rows)<need:
        return {"available":True,"direction":"NEUTRO","confidence":0.0,"confirmed":False,"risk":"HIGH",
                "strategy":name,"engine":"TRIPRSI","provider":"LOCAL_TRIPLE_RSI",
                "reason":f"RSI Triplo coletando candles ({len(rows)}/{need}).",
                "next_candle_entry":True,"gale_signal":False,"non_repaint_after_release":True}
    rows=rows[-TRIPRSI_HISTORY_BARS:]
    closes=[float(x.get("close",0) or 0) for x in rows]
    vals={}
    for label,period in (("r7",TRIPRSI_FAST),("r14",TRIPRSI_MID),("r28",TRIPRSI_SLOW)):
        cur=rsi(closes,period)
        prev=rsi(closes[:-1],period) if len(closes)>period+1 else None
        vals[label]=(cur,prev)
    if any(v is None for pair in vals.values() for v in pair):
        return {"available":True,"direction":"NEUTRO","confidence":0.0,"confirmed":False,"risk":"HIGH",
                "strategy":name,"engine":"TRIPRSI","provider":"LOCAL_TRIPLE_RSI",
                "reason":"RSI Triplo aguardando histórico suficiente.","next_candle_entry":True,"gale_signal":False}
    r7,p7=map(float,vals["r7"]); r14,p14=map(float,vals["r14"]); r28,p28=map(float,vals["r28"])
    d7=r7-p7; d14=r14-p14; d28=r28-p28
    # RSI7 precisa liderar; RSI14/28 podem ficar praticamente estáveis por causa
    # da janela mais longa, mas não podem divergir materialmente do movimento.
    up=(d7>0.0 and d14>=-0.10 and d28>=-0.10 and (d7+d14+d28)>0.15)
    down=(d7<0.0 and d14<=0.10 and d28<=0.10 and (d7+d14+d28)<-0.15)
    neutral_slow=(TRIPRSI_PUT_SLOW <= r28 <= TRIPRSI_CALL_SLOW)
    call=(not neutral_slow and r7>TRIPRSI_CALL_FAST and r14>TRIPRSI_CALL_MID and r28>TRIPRSI_CALL_SLOW and up)
    put=(not neutral_slow and r7<TRIPRSI_PUT_FAST and r14<TRIPRSI_PUT_MID and r28<TRIPRSI_PUT_SLOW and down)
    direction="CALL" if call and not put else ("PUT" if put and not call else "NEUTRO")
    if direction=="CALL":
        strength=min(r7-TRIPRSI_CALL_FAST,r14-TRIPRSI_CALL_MID,r28-TRIPRSI_CALL_SLOW)
        confidence=clamp(70.0+max(0.0,strength)*2.0+min(8.0,(r7-p7)+(r14-p14)+(r28-p28)),70.0,94.0)
        reason=f"CALL RSI TRIPLO: RSI7 {r7:.1f}↑ + RSI14 {r14:.1f}↑ + RSI28 {r28:.1f}↑ alinhados. Entrada na próxima vela."
    elif direction=="PUT":
        strength=min(TRIPRSI_PUT_FAST-r7,TRIPRSI_PUT_MID-r14,TRIPRSI_PUT_SLOW-r28)
        confidence=clamp(70.0+max(0.0,strength)*2.0+min(8.0,(p7-r7)+(p14-r14)+(p28-r28)),70.0,94.0)
        reason=f"PUT RSI TRIPLO: RSI7 {r7:.1f}↓ + RSI14 {r14:.1f}↓ + RSI28 {r28:.1f}↓ alinhados. Entrada na próxima vela."
    else:
        confidence=0.0
        reason=(f"RSI Triplo monitorando • RSI7 {r7:.1f} • RSI14 {r14:.1f} • RSI28 {r28:.1f} • "
                + ("RSI28 em zona neutra 48–52." if neutral_slow else "aguardando alinhamento dos 3 RSIs."))
    return {
        "available":True,"direction":direction,"confidence":round(float(confidence),1),
        "confirmed":direction in ("CALL","PUT"),"risk":(("LOW" if confidence>=84 else "MEDIUM") if direction!="NEUTRO" else "HIGH"),
        "strategy":name,"engine":"TRIPRSI","provider":"LOCAL_TRIPLE_RSI","reason":reason[:440],
        "next_candle_entry":True,"direct_win_only":True,"gale_signal":False,
        "closed_candles_only":not bool(early_signal),"forming_candle_snapshot":bool(early_signal),
        "non_repaint_after_release":True,
        "diagnostics":{"rsi7":round(r7,2),"rsi14":round(r14,2),"rsi28":round(r28,2),
                       "prev7":round(p7,2),"prev14":round(p14,2),"prev28":round(p28,2),
                       "all_rising":up,"all_falling":down,"slow_neutral":neutral_slow}
    }


def combiner_flow_rsi_strategy(cs, timeframe="1min", market="OPEN"):
    """COMBINER FLOW + RSI — suporte/resistência causal + reação + RSI 14.

    Somente candles fechados. Os pivôs exigem candles à direita já encerrados,
    portanto nenhum sinal liberado é alterado depois. A entrada é na próxima vela.
    """
    rows = list(cs or [])
    tf_label = {"1min":"M1","5min":"M5","15min":"M15","30min":"M30","1h":"H1"}.get(timeframe, timeframe)
    name = f"COMBINER FLOW + RSI {tf_label}"
    need = max(45, COMBINER_EMA_PERIOD + 15, COMBINER_ATR_PERIOD + 15)
    if len(rows) < need:
        return {
            "available": True, "direction": "NEUTRO", "confidence": 0.0, "confirmed": False,
            "risk": "HIGH", "strategy": name, "engine": "COMBINER_FLOW_RSI",
            "provider": "LOCAL_COMBINER_FLOW_RSI",
            "reason": f"COMBINER FLOW + RSI coletando candles fechados ({len(rows)}/{need}).",
            "non_repaint": True, "closed_candles_only": True, "next_candle_entry": True, "gale_signal": False,
        }

    rows = rows[-180:]
    closes = [float(x.get("close", 0) or 0) for x in rows]
    r_now = rsi(closes, COMBINER_RSI_PERIOD)
    r_prev = rsi(closes[:-1], COMBINER_RSI_PERIOD) if len(closes) > COMBINER_RSI_PERIOD + 1 else None
    e21 = ema(closes, COMBINER_EMA_PERIOD)
    a = atr(rows, COMBINER_ATR_PERIOD)
    if None in (r_now, r_prev, e21, a) or not a:
        return {
            "available": True, "direction": "NEUTRO", "confidence": 0.0, "confirmed": False,
            "risk": "HIGH", "strategy": name, "engine": "COMBINER_FLOW_RSI",
            "provider": "LOCAL_COMBINER_FLOW_RSI", "reason": "COMBINER FLOW + RSI aguardando indicadores suficientes.",
            "non_repaint": True, "closed_candles_only": True, "next_candle_entry": True, "gale_signal": False,
        }

    side = COMBINER_PIVOT_SIDE
    # O último pivô possível termina em len(rows)-side-1; os candles à direita já estão fechados.
    pivot_lows, pivot_highs = [], []
    for i in range(side, len(rows) - side):
        lo = float(rows[i].get("low", 0) or 0)
        hi = float(rows[i].get("high", 0) or 0)
        if all(lo <= float(rows[j].get("low", 0) or 0) for j in range(i-side, i+side+1) if j != i):
            pivot_lows.append((i, lo))
        if all(hi >= float(rows[j].get("high", 0) or 0) for j in range(i-side, i+side+1) if j != i):
            pivot_highs.append((i, hi))

    last = rows[-1]
    o = float(last.get("open", 0) or 0); h = float(last.get("high", 0) or 0)
    l = float(last.get("low", 0) or 0); c = float(last.get("close", 0) or 0)
    eps = max(abs(c) * 1e-9, 1e-12)
    cr = max(h-l, eps)
    lower_wick = max(0.0, min(o,c)-l); upper_wick = max(0.0, h-max(o,c))
    lower_wr = lower_wick/cr; upper_wr = upper_wick/cr
    close_pos = (c-l)/cr
    zone = max(float(a) * COMBINER_ZONE_ATR, abs(c) * 0.00015, eps)

    recent_lows = [(i,p) for i,p in pivot_lows if i >= len(rows)-90 and p <= c + zone*1.5]
    recent_highs = [(i,p) for i,p in pivot_highs if i >= len(rows)-90 and p >= c - zone*1.5]
    support = max((p for _,p in recent_lows), default=min(float(x.get("low",0) or 0) for x in rows[-24:-1]))
    resistance = min((p for _,p in recent_highs), default=max(float(x.get("high",0) or 0) for x in rows[-24:-1]))

    near_support = l <= support + zone and c >= support - zone*0.65
    near_resistance = h >= resistance - zone and c <= resistance + zone*0.65
    bull_reaction = (c > o and close_pos >= 0.52) or lower_wr >= 0.24
    bear_reaction = (c < o and close_pos <= 0.48) or upper_wr >= 0.24
    rsi_call = float(r_now) <= COMBINER_RSI_CALL_MAX and (float(r_now) >= float(r_prev)-1.5 or lower_wr >= 0.24)
    rsi_put = float(r_now) >= COMBINER_RSI_PUT_MIN and (float(r_now) <= float(r_prev)+1.5 or upper_wr >= 0.24)

    call = put = 0.0
    call_reasons=[]; put_reasons=[]
    if near_support: call += 3.0; call_reasons.append("suporte confirmado")
    if near_resistance: put += 3.0; put_reasons.append("resistência confirmada")
    if bull_reaction: call += 2.0; call_reasons.append("reação compradora")
    if bear_reaction: put += 2.0; put_reasons.append("reação vendedora")
    if rsi_call: call += 2.0; call_reasons.append(f"RSI {float(r_now):.1f}")
    if rsi_put: put += 2.0; put_reasons.append(f"RSI {float(r_now):.1f}")
    if c >= float(e21): call += 0.8; call_reasons.append("EMA21 favorável")
    if c <= float(e21): put += 0.8; put_reasons.append("EMA21 favorável")
    if c > o: call += 0.5
    elif c < o: put += 0.5

    call_ok = near_support and bull_reaction and rsi_call and call >= COMBINER_MIN_SCORE and (call-put) >= COMBINER_SCORE_EDGE
    put_ok = near_resistance and bear_reaction and rsi_put and put >= COMBINER_MIN_SCORE and (put-call) >= COMBINER_SCORE_EDGE
    direction = "CALL" if call_ok and not put_ok else ("PUT" if put_ok and not call_ok else "NEUTRO")
    score = call if direction == "CALL" else (put if direction == "PUT" else max(call,put))
    confidence = 0.0
    if direction != "NEUTRO":
        confidence = clamp(61.0 + max(0.0, score-COMBINER_MIN_SCORE)*8.0 + min(8.0, abs(call-put)*2.5), 61.0, 92.0)
        reason_list = call_reasons if direction == "CALL" else put_reasons
        reason = f"{direction} COMBINER FLOW + RSI: " + ", ".join(reason_list[:5]) + ". Entrada na próxima vela."
    else:
        dom = "CALL" if call >= put else "PUT"
        reason = (f"COMBINER FLOW + RSI monitorando • {dom} {max(call,put):.1f} pts • "
                  f"RSI {float(r_now):.1f} • suporte {support:.8g} • resistência {resistance:.8g}.")

    return {
        "available": True, "direction": direction, "confidence": round(float(confidence),1),
        "confirmed": direction in ("CALL","PUT"),
        "risk": ("LOW" if confidence >= 82 else "MEDIUM") if direction != "NEUTRO" else "HIGH",
        "strategy": name, "engine": "COMBINER_FLOW_RSI", "provider": "LOCAL_COMBINER_FLOW_RSI",
        "reason": reason[:440], "non_repaint": True, "non_repaint_after_release": True,
        "closed_candles_only": True, "next_candle_entry": True, "direct_win_only": True, "gale_signal": False,
        "diagnostics": {
            "call_score": round(call,2), "put_score": round(put,2), "min_score": COMBINER_MIN_SCORE,
            "rsi": round(float(r_now),2), "rsi_prev": round(float(r_prev),2), "ema21": round(float(e21),10),
            "atr": round(float(a),10), "support": round(float(support),10), "resistance": round(float(resistance),10),
            "zone": round(float(zone),10), "near_support": near_support, "near_resistance": near_resistance,
            "lower_wick_ratio": round(lower_wr,4), "upper_wick_ratio": round(upper_wr,4),
        },
    }


def rsi_divergence_bollinger_strategy(cs, timeframe="1min", market="OPEN"):
    """RSI Divergence + Bollinger 20/2 — causal, candle fechado e próxima vela.

    CALL: preço faz fundo mais baixo entre dois pivôs confirmados, RSI 14 faz fundo
    mais alto e o segundo pivô toca/rompe (ou fica na pequena tolerância) da banda inferior.
    PUT: preço faz topo mais alto, RSI 14 faz topo mais baixo e o segundo pivô fica
    na zona da banda superior. Nenhum pivô usa candle futuro ainda aberto.
    """
    rows=list(cs or [])
    tf_label={"1min":"M1","5min":"M5","15min":"M15","30min":"M30","1h":"H1"}.get(timeframe,timeframe)
    name=f"RSI DIVERGENCE + BOLLINGER {tf_label}"
    need=max(55, RSIDIVBB_RSI_PERIOD+RSIDIVBB_BB_PERIOD+12, RSIDIVBB_LOOKBACK+12)
    if len(rows)<need:
        return {
            "available":True,"direction":"NEUTRO","confidence":0.0,"confirmed":False,
            "risk":"HIGH","strategy":name,"engine":"RSIDIVBB","provider":"LOCAL_RSI_DIVERGENCE_BOLLINGER",
            "reason":f"RSI Divergence + Bollinger coletando candles fechados ({len(rows)}/{need}).",
            "non_repaint":True,"closed_candles_only":True,"next_candle_entry":True,"direct_win_only":True,"gale_signal":False,
        }

    rows=rows[-RSIDIVBB_HISTORY_BARS:]
    closes=[float(x.get("close",0) or 0) for x in rows]
    n=len(rows)
    rvals=[None]*n
    for i in range(RSIDIVBB_RSI_PERIOD,n):
        rvals[i]=rsi(closes[:i+1],RSIDIVBB_RSI_PERIOD)

    side=RSIDIVBB_PIVOT_SIDE
    start=max(side, n-RSIDIVBB_LOOKBACK-8, RSIDIVBB_RSI_PERIOD)
    lows=[]; highs=[]
    # O limite n-side garante que todos os candles à direita do pivô já fecharam.
    for i in range(start,n-side):
        rv=rvals[i]
        if rv is None: continue
        lo=float(rows[i].get("low",0) or 0); hi=float(rows[i].get("high",0) or 0)
        low_ok=all(lo <= float(rows[j].get("low",0) or 0) for j in range(i-side,i+side+1) if j!=i)
        high_ok=all(hi >= float(rows[j].get("high",0) or 0) for j in range(i-side,i+side+1) if j!=i)
        if low_ok: lows.append((i,lo,float(rv)))
        if high_ok: highs.append((i,hi,float(rv)))

    def bb_at(i):
        if i+1<RSIDIVBB_BB_PERIOD: return None
        return bollinger(closes[:i+1],RSIDIVBB_BB_PERIOD,RSIDIVBB_BB_DEVIATION)

    candidates=[]
    if len(lows)>=2:
        a,b=lows[-2],lows[-1]
        age=(n-1)-b[0]
        bb=bb_at(b[0])
        if bb:
            width=max(float(bb["upper"])-float(bb["lower"]),1e-12)
            tol=width*RSIDIVBB_BAND_TOLERANCE
            rdelta=b[2]-a[2]
            divergence=b[1] < a[1] and rdelta>=RSIDIVBB_MIN_RSI_DELTA
            near_band=b[1] <= float(bb["lower"])+tol
            if divergence and near_band and age<=RSIDIVBB_MAX_PIVOT_AGE:
                pierced=b[1]<=float(bb["lower"])
                pstrength=max(0.0,(a[1]-b[1])/width)
                conf=clamp(72.0+min(11.0,rdelta*1.5)+min(7.0,pstrength*120.0)+(3.0 if pierced else 1.0),72.0,94.0)
                candidates.append({"direction":"CALL","confidence":conf,"a":a,"b":b,"bb":bb,"age":age,"pierced":pierced,"rdelta":rdelta})

    if len(highs)>=2:
        a,b=highs[-2],highs[-1]
        age=(n-1)-b[0]
        bb=bb_at(b[0])
        if bb:
            width=max(float(bb["upper"])-float(bb["lower"]),1e-12)
            tol=width*RSIDIVBB_BAND_TOLERANCE
            rdelta=a[2]-b[2]
            divergence=b[1] > a[1] and rdelta>=RSIDIVBB_MIN_RSI_DELTA
            near_band=b[1] >= float(bb["upper"])-tol
            if divergence and near_band and age<=RSIDIVBB_MAX_PIVOT_AGE:
                pierced=b[1]>=float(bb["upper"])
                pstrength=max(0.0,(b[1]-a[1])/width)
                conf=clamp(72.0+min(11.0,rdelta*1.5)+min(7.0,pstrength*120.0)+(3.0 if pierced else 1.0),72.0,94.0)
                candidates.append({"direction":"PUT","confidence":conf,"a":a,"b":b,"bb":bb,"age":age,"pierced":pierced,"rdelta":rdelta})

    if not candidates:
        rr=rvals[-1]
        return {
            "available":True,"direction":"NEUTRO","confidence":0.0,"confirmed":False,
            "risk":"HIGH","strategy":name,"engine":"RSIDIVBB","provider":"LOCAL_RSI_DIVERGENCE_BOLLINGER",
            "reason":f"RSI Divergence + Bollinger monitorando • RSI14 {float(rr):.1f} • aguardando divergência confirmada em banda extrema." if rr is not None else "RSI Divergence + Bollinger aguardando estrutura.",
            "non_repaint":True,"closed_candles_only":True,"next_candle_entry":True,"direct_win_only":True,"gale_signal":False,
        }

    chosen=max(candidates,key=lambda x:(x["b"][0],x["confidence"]))
    direction=chosen["direction"]; a=chosen["a"]; b=chosen["b"]; bb=chosen["bb"]
    evt=str(rows[b[0]].get("datetime") or rows[b[0]].get("timestamp") or b[0])
    if direction=="CALL":
        reason=(f"CALL divergência altista: preço {a[1]:.8g} → {b[1]:.8g} (fundo mais baixo), "
                f"RSI14 {a[2]:.1f} → {b[2]:.1f} (fundo mais alto) + banda inferior BB20/2. Próxima vela.")
    else:
        reason=(f"PUT divergência baixista: preço {a[1]:.8g} → {b[1]:.8g} (topo mais alto), "
                f"RSI14 {a[2]:.1f} → {b[2]:.1f} (topo mais baixo) + banda superior BB20/2. Próxima vela.")
    return {
        "available":True,"direction":direction,"confidence":round(float(chosen["confidence"]),1),"confirmed":True,
        "risk":"MEDIUM","strategy":name,"engine":"RSIDIVBB","provider":"LOCAL_RSI_DIVERGENCE_BOLLINGER",
        "reason":reason[:460],"non_repaint":True,"non_repaint_after_release":True,"closed_candles_only":True,
        "next_candle_entry":True,"direct_win_only":True,"gale_signal":False,"martingale":False,
        "event_key":f"RSIDIVBB:{direction}:{evt}","pivot_age_bars":int(chosen["age"]),
        "rsi":round(float(b[2]),2),"rsi_previous_pivot":round(float(a[2]),2),"rsi_delta":round(float(chosen["rdelta"]),2),
        "bollinger":{"period":RSIDIVBB_BB_PERIOD,"deviation":RSIDIVBB_BB_DEVIATION,"upper":float(bb["upper"]),"middle":float(bb["middle"]),"lower":float(bb["lower"]),"tolerance_ratio":RSIDIVBB_BAND_TOLERANCE},
    }



def _causal_extreme_tma_endpoint(values, period=17):
    """Endpoint causal equivalente à metade disponível do TMA centralizado.

    Para period=17 usa os últimos 18 fechamentos com pesos 1..18 (mais peso no
    candle mais recente). Não lê candle futuro e, depois do fechamento, não repinta.
    """
    vals=[]
    for v in list(values or []):
        try:
            x=float(v)
        except Exception:
            continue
        if x>0:
            vals.append(x)
    need=max(2,int(period)+1)
    if len(vals)<need:
        return None
    window=vals[-need:]
    weights=list(range(1,need+1))
    denom=float(sum(weights))
    return sum(v*w for v,w in zip(window,weights))/denom if denom>0 else None


def extreme_tma_rsi_trend_strategy(cs, timeframe="1min", market="OPEN"):
    """Extreme TMA + RSI 7 + Trend Filter — candle fechado, próxima vela.

    CALL = toque/penetração da banda inferior + RSI <=35 iniciando giro para cima
    + Trend Filter VERDE/CALL. PUT é o inverso na banda superior com RSI >=65
    girando para baixo + Trend Filter VERMELHO/PUT.
    """
    rows=list(cs or [])
    tf_label={"1min":"M1","5min":"M5","15min":"M15","30min":"M30","1h":"H1"}.get(timeframe,timeframe)
    name=f"EXTREME TMA + RSI + TREND FILTER {tf_label}"
    need=max(TMARSI_HISTORY_BARS if TMARSI_HISTORY_BARS < 150 else 125, TMARSI_ATR_PERIOD+3, TMARSI_TMA_PERIOD+4, TMARSI_RSI_PERIOD+4, 30)
    if len(rows)<need:
        return {
            "available":True,"direction":"NEUTRO","confidence":0.0,"confirmed":False,
            "risk":"HIGH","strategy":name,"engine":"TMARSI","provider":"LOCAL_EXTREME_TMA_RSI_TREND",
            "reason":f"Extreme TMA + RSI + Trend Filter coletando candles fechados ({len(rows)}/{need}).",
            "non_repaint":True,"closed_candles_only":True,"next_candle_entry":True,
            "direct_win_only":True,"gale_signal":False,
        }

    rows=rows[-TMARSI_HISTORY_BARS:]
    closes=[float(x.get("close",0) or 0) for x in rows]
    tma_val=_causal_extreme_tma_endpoint(closes,TMARSI_TMA_PERIOD)
    atr_val=atr(rows,TMARSI_ATR_PERIOD)
    r_now=rsi(closes,TMARSI_RSI_PERIOD)
    r_prev=rsi(closes[:-1],TMARSI_RSI_PERIOD) if len(closes)>TMARSI_RSI_PERIOD+1 else None
    trend_filter=_smart_trend_filter(rows)

    if tma_val is None or atr_val is None or r_now is None or r_prev is None:
        return {
            "available":True,"direction":"NEUTRO","confidence":0.0,"confirmed":False,
            "risk":"HIGH","strategy":name,"engine":"TMARSI","provider":"LOCAL_EXTREME_TMA_RSI_TREND",
            "reason":"Extreme TMA + RSI aguardando TMA/ATR/RSI suficientes.",
            "trend_filter":trend_filter,"non_repaint":True,"closed_candles_only":True,
            "next_candle_entry":True,"direct_win_only":True,"gale_signal":False,
        }

    band_range=max(float(atr_val)*TMARSI_ATR_MULTIPLIER,1e-12)
    upper=float(tma_val)+band_range
    lower=float(tma_val)-band_range
    last=rows[-1]
    lo=float(last.get("low",0) or 0); hi=float(last.get("high",0) or 0)
    close=float(last.get("close",0) or 0)

    touch_lower=lo<=lower
    touch_upper=hi>=upper
    rsi_call=float(r_now)<=TMARSI_RSI_CALL_MAX
    rsi_put=float(r_now)>=TMARSI_RSI_PUT_MIN
    if TMARSI_REQUIRE_RSI_TURN:
        rsi_call=rsi_call and float(r_now)>float(r_prev)
        rsi_put=rsi_put and float(r_now)<float(r_prev)

    candidate="CALL" if (touch_lower and rsi_call) else ("PUT" if (touch_upper and rsi_put) else "NEUTRO")
    trend_ready=bool(trend_filter.get("ready"))
    trend_dir=str(trend_filter.get("direction") or "NEUTRO").upper()
    trend_color=str(trend_filter.get("color") or "NEUTRO").upper()
    aligned=bool(candidate in ("CALL","PUT") and trend_ready and trend_dir==candidate)

    if candidate=="NEUTRO":
        reason=(f"Extreme TMA + RSI monitorando • banda {lower:.8g} / {upper:.8g} • RSI7 {float(r_now):.1f} "
                f"(anterior {float(r_prev):.1f}) • Trend Filter {trend_color} → {trend_dir}.")
        return {
            "available":True,"direction":"NEUTRO","confidence":0.0,"confirmed":False,
            "risk":"HIGH","strategy":name,"engine":"TMARSI","provider":"LOCAL_EXTREME_TMA_RSI_TREND",
            "reason":reason[:460],"trend_filter":trend_filter,"candidate_direction":"NEUTRO",
            "non_repaint":True,"closed_candles_only":True,"next_candle_entry":True,
            "direct_win_only":True,"gale_signal":False,
            "tma":{"period":TMARSI_TMA_PERIOD,"value":round(float(tma_val),10),"upper":round(upper,10),"lower":round(lower,10),"atr_period":TMARSI_ATR_PERIOD,"atr_multiplier":TMARSI_ATR_MULTIPLIER},
            "rsi":{"period":TMARSI_RSI_PERIOD,"value":round(float(r_now),2),"previous":round(float(r_prev),2),"call_max":TMARSI_RSI_CALL_MAX,"put_min":TMARSI_RSI_PUT_MIN},
        }

    if not aligned:
        if not trend_ready:
            why=f"{candidate} candidato no TMA + RSI, mas o Trend Filter ainda não está pronto. Entrada bloqueada."
        elif trend_dir=="NEUTRO":
            why=f"{candidate} candidato no TMA + RSI, mas o Trend Filter está NEUTRO. Entrada bloqueada."
        else:
            why=f"{candidate} candidato no TMA + RSI, porém Trend Filter {trend_color} autoriza somente {trend_dir}. Entrada bloqueada."
        return {
            "available":True,"direction":"NEUTRO","confidence":0.0,"confirmed":False,
            "risk":"HIGH","strategy":name,"engine":"TMARSI","provider":"LOCAL_EXTREME_TMA_RSI_TREND",
            "reason":why,"trend_filter":trend_filter,"candidate_direction":candidate,
            "non_repaint":True,"closed_candles_only":True,"next_candle_entry":True,
            "direct_win_only":True,"gale_signal":False,
            "tma":{"period":TMARSI_TMA_PERIOD,"value":round(float(tma_val),10),"upper":round(upper,10),"lower":round(lower,10),"atr_period":TMARSI_ATR_PERIOD,"atr_multiplier":TMARSI_ATR_MULTIPLIER},
            "rsi":{"period":TMARSI_RSI_PERIOD,"value":round(float(r_now),2),"previous":round(float(r_prev),2),"call_max":TMARSI_RSI_CALL_MAX,"put_min":TMARSI_RSI_PUT_MIN},
        }

    penetration=((lower-lo)/band_range if candidate=="CALL" else (hi-upper)/band_range)
    turn_strength=((float(r_now)-float(r_prev)) if candidate=="CALL" else (float(r_prev)-float(r_now)))
    ema_gap=abs(float(trend_filter.get("ema9") or close)-float(trend_filter.get("ema21") or close))/max(abs(close),1e-12)
    confidence=clamp(74.0+min(8.0,max(0.0,penetration)*35.0)+min(6.0,max(0.0,turn_strength)*1.5)+min(5.0,ema_gap*12000.0),74.0,93.0)
    evt=str(last.get("datetime") or last.get("timestamp") or len(rows)-1)
    reason=(f"{candidate} LIBERADO: TMA17 banda {'inferior' if candidate=='CALL' else 'superior'} tocada + "
            f"RSI7 {float(r_now):.1f} girando {'para cima' if candidate=='CALL' else 'para baixo'} + "
            f"Trend Filter {trend_color} ({trend_dir}) alinhado. Entrada na próxima vela.")
    return {
        "available":True,"direction":candidate,"confidence":round(float(confidence),1),"confirmed":True,
        "risk":"MEDIUM","strategy":name,"engine":"TMARSI","provider":"LOCAL_EXTREME_TMA_RSI_TREND",
        "reason":reason[:460],"trend_filter":trend_filter,"candidate_direction":candidate,
        "non_repaint":True,"non_repaint_after_release":True,"closed_candles_only":True,
        "next_candle_entry":True,"direct_win_only":True,"gale_signal":False,"martingale":False,
        "event_key":f"TMARSI:{candidate}:{evt}",
        "tma":{"period":TMARSI_TMA_PERIOD,"value":round(float(tma_val),10),"upper":round(upper,10),"lower":round(lower,10),"atr_period":TMARSI_ATR_PERIOD,"atr_multiplier":TMARSI_ATR_MULTIPLIER,"causal_endpoint":True},
        "rsi":{"period":TMARSI_RSI_PERIOD,"value":round(float(r_now),2),"previous":round(float(r_prev),2),"call_max":TMARSI_RSI_CALL_MAX,"put_min":TMARSI_RSI_PUT_MIN,"turn_required":TMARSI_REQUIRE_RSI_TURN},
    }

def _three_line_break_profile(closes, lb=3):
    """Reconstrói os blocos do 3 Line Break usando somente fechamentos passados.

    A lógica espelha a ideia do MQ4 original: um novo bloco só nasce quando o
    fechamento sai do envelope dos últimos LB blocos. Retorna os níveis ativos
    de suporte/resistência e o lado do último bloco.
    """
    vals = []
    for v in list(closes or []):
        try:
            x = float(v)
        except Exception:
            continue
        if x > 0:
            vals.append(x)
    if len(vals) < max(12, lb + 5):
        return None

    # Primeiro bloco: primeiro par consecutivo com fechamentos diferentes.
    start = None
    for i in range(1, len(vals)):
        if vals[i] != vals[i - 1]:
            start = i
            break
    if start is None:
        return None

    a, b = vals[start - 1], vals[start]
    blocks = [{"max": max(a, b), "min": min(a, b), "close": b}]

    for c in vals[start + 1:]:
        window = blocks[-min(lb, len(blocks)):]
        hi = max(x["max"] for x in window)
        lo = min(x["min"] for x in window)
        prev = blocks[-1]
        if c > hi:
            blocks.append({"max": c, "min": prev["max"], "close": c})
        elif c < lo:
            blocks.append({"max": prev["min"], "min": c, "close": c})

    if len(blocks) < 2:
        return None

    support = resistance = current_support = current_resistance = 0.0
    bull_count = bear_count = 0
    trend = "NEUTRO"
    for i in range(1, len(blocks)):
        cur, prev = blocks[i], blocks[i - 1]
        if cur["max"] > prev["max"]:
            if bull_count >= lb and i - lb >= 0:
                support = blocks[i - lb]["max"]
            else:
                j = max(0, i - bull_count - 1)
                support = blocks[j]["min"]
            current_resistance = cur["max"]
            current_support = 0.0
            resistance = 0.0
            bull_count += 1
            bear_count = 0
            trend = "BULL"
        elif cur["max"] < prev["max"]:
            if bear_count >= lb and i - lb >= 0:
                resistance = blocks[i - lb]["min"]
            else:
                j = max(0, i - bear_count - 1)
                resistance = blocks[j]["max"]
            current_support = cur["min"]
            support = 0.0
            current_resistance = 0.0
            bear_count += 1
            bull_count = 0
            trend = "BEAR"

    # Mantém também a borda do bloco mais recente como nível utilizável.
    if trend == "BULL" and not current_resistance:
        current_resistance = blocks[-1]["max"]
    if trend == "BEAR" and not current_support:
        current_support = blocks[-1]["min"]

    return {
        "trend": trend,
        "support": float(support or 0.0),
        "resistance": float(resistance or 0.0),
        "current_support": float(current_support or 0.0),
        "current_resistance": float(current_resistance or 0.0),
        "brick_count": len(blocks),
        "last_block": blocks[-1],
    }


def three_line_break_rsi_strategy(cs, timeframe="1min", market="OPEN"):
    """3 Line Break LB3 + RSI 14, causal e preparado para a próxima vela.

    O perfil 3LB é montado com rows[:-1]. A última vela fechada é usada apenas
    para confirmar reação na zona e o comportamento do RSI. Assim o nível não
    é criado pela própria vela que libera o sinal.
    """
    rows = list(cs or [])
    tf_label = {"1min":"M1","5min":"M5","15min":"M15","30min":"M30","1h":"H1"}.get(timeframe, timeframe)
    name = f"3 LINE BREAK + RSI {tf_label}"
    need = max(60, TLBRSI_RSI_PERIOD + 20, TLBRSI_ATR_PERIOD + 20)
    if len(rows) < need:
        return {
            "available": True, "direction": "NEUTRO", "confidence": 0.0, "confirmed": False,
            "risk": "HIGH", "strategy": name, "engine": "TLBRSI", "provider": "LOCAL_3_LINE_BREAK_RSI",
            "reason": f"3 Line Break + RSI coletando candles fechados ({len(rows)}/{need}).",
            "non_repaint": True, "closed_candles_only": True, "next_candle_entry": True,
            "direct_win_only": True, "gale_signal": False,
        }

    rows = rows[-TLBRSI_HISTORY_BARS:]
    closes = [float(x.get("close", 0) or 0) for x in rows]
    reference = rows[:-1]
    ref_closes = closes[:-1]
    profile = _three_line_break_profile(ref_closes, TLBRSI_LB)
    r_now = rsi(closes, TLBRSI_RSI_PERIOD)
    r_prev = rsi(closes[:-1], TLBRSI_RSI_PERIOD) if len(closes) > TLBRSI_RSI_PERIOD + 1 else None
    a = atr(reference, TLBRSI_ATR_PERIOD)
    if not profile or r_now is None or r_prev is None or not a:
        return {
            "available": True, "direction": "NEUTRO", "confidence": 0.0, "confirmed": False,
            "risk": "HIGH", "strategy": name, "engine": "TLBRSI", "provider": "LOCAL_3_LINE_BREAK_RSI",
            "reason": "3 Line Break + RSI aguardando estrutura LB3/RSI suficiente.",
            "non_repaint": True, "closed_candles_only": True, "next_candle_entry": True,
            "direct_win_only": True, "gale_signal": False,
        }

    last = rows[-1]
    o = float(last.get("open", 0) or 0); h = float(last.get("high", 0) or 0)
    l = float(last.get("low", 0) or 0); c = float(last.get("close", 0) or 0)
    eps = max(abs(c) * 1e-9, 1e-12)
    cr = max(h - l, eps)
    body = abs(c - o)
    lower_wick = max(0.0, min(o, c) - l)
    upper_wick = max(0.0, h - max(o, c))
    lower_wr = lower_wick / cr
    upper_wr = upper_wick / cr
    close_pos = (c - l) / cr
    zone = max(float(a) * TLBRSI_ZONE_ATR, abs(c) * 0.00012, eps)

    support_levels = [x for x in (profile.get("support"), profile.get("current_support")) if x and x > 0]
    resistance_levels = [x for x in (profile.get("resistance"), profile.get("current_resistance")) if x and x > 0]
    support = min(support_levels, key=lambda x: abs(c - x)) if support_levels else 0.0
    resistance = min(resistance_levels, key=lambda x: abs(c - x)) if resistance_levels else 0.0

    near_support = bool(support and l <= support + zone and c >= support - zone * 0.65)
    near_resistance = bool(resistance and h >= resistance - zone and c <= resistance + zone * 0.65)
    bull_reaction = (c > o and close_pos >= 0.52) or lower_wr >= 0.22 or (lower_wick >= max(body * 0.55, eps) and close_pos >= 0.48)
    bear_reaction = (c < o and close_pos <= 0.48) or upper_wr >= 0.22 or (upper_wick >= max(body * 0.55, eps) and close_pos <= 0.52)

    # RSI solto para não prender demais o motor: zona 3LB continua obrigatória.
    r_now_f = float(r_now); r_prev_f = float(r_prev)
    rsi_call = r_now_f <= TLBRSI_RSI_CALL_MAX and (r_now_f >= r_prev_f - 1.2 or r_now_f <= 35.0)
    rsi_put = r_now_f >= TLBRSI_RSI_PUT_MIN and (r_now_f <= r_prev_f + 1.2 or r_now_f >= 65.0)

    call = put = 0.0
    call_reasons = []; put_reasons = []
    if near_support: call += 3.0; call_reasons.append("suporte 3LB")
    if near_resistance: put += 3.0; put_reasons.append("resistência 3LB")
    if bull_reaction: call += 1.6; call_reasons.append("rejeição compradora")
    if bear_reaction: put += 1.6; put_reasons.append("rejeição vendedora")
    if rsi_call: call += 2.0; call_reasons.append(f"RSI14 {r_now_f:.1f}")
    if rsi_put: put += 2.0; put_reasons.append(f"RSI14 {r_now_f:.1f}")
    if profile.get("trend") == "BULL": call += 0.8; call_reasons.append("3LB comprador")
    elif profile.get("trend") == "BEAR": put += 0.8; put_reasons.append("3LB vendedor")
    if r_now_f <= 32.0: call += 0.7; call_reasons.append("RSI extremo")
    if r_now_f >= 68.0: put += 0.7; put_reasons.append("RSI extremo")

    call_ok = near_support and rsi_call and (bull_reaction or profile.get("trend") == "BULL") and call >= TLBRSI_MIN_SCORE
    put_ok = near_resistance and rsi_put and (bear_reaction or profile.get("trend") == "BEAR") and put >= TLBRSI_MIN_SCORE
    direction = "NEUTRO"
    if call_ok and not put_ok and (call - put) >= TLBRSI_SCORE_EDGE:
        direction = "CALL"
    elif put_ok and not call_ok and (put - call) >= TLBRSI_SCORE_EDGE:
        direction = "PUT"
    elif call_ok and put_ok:
        if call - put >= TLBRSI_SCORE_EDGE:
            direction = "CALL"
        elif put - call >= TLBRSI_SCORE_EDGE:
            direction = "PUT"

    score = call if direction == "CALL" else (put if direction == "PUT" else max(call, put))
    confidence = 0.0
    if direction != "NEUTRO":
        confidence = clamp(64.0 + max(0.0, score - TLBRSI_MIN_SCORE) * 8.0 + min(8.0, abs(call - put) * 2.2), 64.0, 93.0)
        reasons = call_reasons if direction == "CALL" else put_reasons
        reason = f"{direction} 3 Line Break + RSI: " + ", ".join(reasons[:5]) + ". Entrada na próxima vela."
    else:
        reason = (f"3 Line Break + RSI monitorando • 3LB {profile.get('trend')} • RSI14 {r_now_f:.1f} • "
                  f"suporte {support:.8g} • resistência {resistance:.8g}.")

    evt = str(last.get("datetime") or last.get("timestamp") or len(rows))
    return {
        "available": True, "direction": direction, "confidence": round(float(confidence), 1),
        "confirmed": direction in ("CALL", "PUT"),
        "risk": ("LOW" if confidence >= 83 else "MEDIUM") if direction != "NEUTRO" else "HIGH",
        "strategy": name, "engine": "TLBRSI", "provider": "LOCAL_3_LINE_BREAK_RSI",
        "reason": reason[:460], "non_repaint": True, "non_repaint_after_release": True,
        "closed_candles_only": True, "next_candle_entry": True, "direct_win_only": True,
        "gale_signal": False, "martingale": False,
        "event_key": f"TLBRSI:{direction}:{evt}",
        "three_line_break": {
            "lb": TLBRSI_LB, "trend": profile.get("trend"), "brick_count": profile.get("brick_count"),
            "support": float(support or 0.0), "resistance": float(resistance or 0.0),
            "current_support": float(profile.get("current_support") or 0.0),
            "current_resistance": float(profile.get("current_resistance") or 0.0),
            "zone": float(zone),
        },
        "rsi": round(r_now_f, 2), "rsi_previous": round(r_prev_f, 2),
        "diagnostics": {
            "call_score": round(call, 2), "put_score": round(put, 2), "min_score": TLBRSI_MIN_SCORE,
            "near_support": near_support, "near_resistance": near_resistance,
            "bull_reaction": bull_reaction, "bear_reaction": bear_reaction,
            "lower_wick_ratio": round(lower_wr, 4), "upper_wick_ratio": round(upper_wr, 4),
        },
    }


def robo_fibo_strategy(cs, timeframe="1min", market="OPEN", use_poc=False):
    """ROBO FIBO — Fibonacci 23.6/76.4 + RSI14 + EMA60, sem repaint.

    O range Fibonacci usa apenas candles ANTERIORES ao candle de confirmação.
    O último candle fechado precisa tocar/rejeitar uma das zonas; o sinal, quando
    confirmado, é exclusivamente para a abertura da próxima vela.
    """
    rows = list(cs or [])
    tf_label = {"1min":"M1","5min":"M5","15min":"M15","30min":"M30","1h":"H1"}.get(timeframe, timeframe)
    use_poc = bool(use_poc)
    name = f"ROBO FIBO + RSI + EMA{' + POC' if use_poc else ''} {tf_label}"
    need = max(ROBOFIBO_EMA_PERIOD + 8, ROBOFIBO_BARS_BACK + 8, ROBOFIBO_RSI_PERIOD + 8, ROBOFIBO_ATR_PERIOD + 8)
    if len(rows) < need:
        return {
            "available": True, "direction": "NEUTRO", "confidence": 0.0, "confirmed": False,
            "risk": "HIGH", "strategy": name, "engine": "FIBORSI", "provider": "LOCAL_ROBO_FIBO",
            "reason": f"RoboFibo coletando candles fechados ({len(rows)}/{need}).",
            "non_repaint": True, "closed_candles_only": True, "next_candle_entry": True,
            "direct_win_only": True, "gale_signal": False, "martingale": False,
        }

    rows = rows[-ROBOFIBO_HISTORY_BARS:]
    reference = rows[:-1]
    last = rows[-1]
    fib_ref = reference[-ROBOFIBO_BARS_BACK:]
    closes = [float(x.get("close", 0) or 0) for x in rows]
    ref_closes = closes[:-1]

    lows = [float(x.get("low", 0) or 0) for x in fib_ref]
    highs = [float(x.get("high", 0) or 0) for x in fib_ref]
    if not lows or not highs:
        return {
            "available": True, "direction": "NEUTRO", "confidence": 0.0, "confirmed": False,
            "risk": "HIGH", "strategy": name, "engine": "FIBORSI", "provider": "LOCAL_ROBO_FIBO",
            "reason": "RoboFibo aguardando range Fibonacci válido.",
            "non_repaint": True, "closed_candles_only": True, "next_candle_entry": True,
            "direct_win_only": True, "gale_signal": False, "martingale": False,
        }

    low_value = min(lows)
    high_value = max(highs)
    fib_range = high_value - low_value
    eps = max(abs(float(last.get("close", 0) or 0)) * 1e-9, 1e-12)
    if fib_range <= eps:
        return {
            "available": True, "direction": "NEUTRO", "confidence": 0.0, "confirmed": False,
            "risk": "HIGH", "strategy": name, "engine": "FIBORSI", "provider": "LOCAL_ROBO_FIBO",
            "reason": "RoboFibo aguardando amplitude suficiente para calcular Fibonacci.",
            "non_repaint": True, "closed_candles_only": True, "next_candle_entry": True,
            "direct_win_only": True, "gale_signal": False, "martingale": False,
        }

    fib236 = low_value + fib_range * 0.236
    fib382 = low_value + fib_range * 0.382
    fib500 = low_value + fib_range * 0.500
    fib618 = low_value + fib_range * 0.618
    fib764 = low_value + fib_range * 0.764

    r_now = rsi(closes, ROBOFIBO_RSI_PERIOD)
    r_prev = rsi(closes[:-1], ROBOFIBO_RSI_PERIOD) if len(closes) > ROBOFIBO_RSI_PERIOD + 1 else None
    ema_now = ema(closes, ROBOFIBO_EMA_PERIOD)
    ema_prev = ema(closes[:-1], ROBOFIBO_EMA_PERIOD) if len(closes) > ROBOFIBO_EMA_PERIOD else None
    a = atr(reference, ROBOFIBO_ATR_PERIOD)
    if r_now is None or r_prev is None or ema_now is None or ema_prev is None or not a:
        return {
            "available": True, "direction": "NEUTRO", "confidence": 0.0, "confirmed": False,
            "risk": "HIGH", "strategy": name, "engine": "FIBORSI", "provider": "LOCAL_ROBO_FIBO",
            "reason": "RoboFibo aguardando RSI/EMA/ATR suficientes.",
            "non_repaint": True, "closed_candles_only": True, "next_candle_entry": True,
            "direct_win_only": True, "gale_signal": False, "martingale": False,
        }

    o = float(last.get("open", 0) or 0); h = float(last.get("high", 0) or 0)
    l = float(last.get("low", 0) or 0); c = float(last.get("close", 0) or 0)
    cr = max(h - l, eps)
    body = abs(c - o)
    lower_wick = max(0.0, min(o, c) - l)
    upper_wick = max(0.0, h - max(o, c))
    lower_wr = lower_wick / cr
    upper_wr = upper_wick / cr
    close_pos = (c - l) / cr
    zone = max(float(a) * ROBOFIBO_ZONE_ATR, fib_range * 0.012, abs(c) * 0.00008, eps)

    # Zona baixa: 0 -> 23.6%. Zona alta: 76.4% -> 100%.
    near_low_zone = l <= fib236 + zone and c >= low_value - zone
    near_high_zone = h >= fib764 - zone and c <= high_value + zone

    bull_reaction = (
        (c > o and close_pos >= 0.56)
        or lower_wr >= 0.24
        or (lower_wick >= max(body * 0.65, eps) and close_pos >= 0.50)
    )
    bear_reaction = (
        (c < o and close_pos <= 0.44)
        or upper_wr >= 0.24
        or (upper_wick >= max(body * 0.65, eps) and close_pos <= 0.50)
    )

    r_now_f = float(r_now); r_prev_f = float(r_prev)
    rsi_call = r_now_f <= ROBOFIBO_RSI_CALL_MAX and (r_now_f >= r_prev_f - 1.0 or r_now_f <= 35.0)
    rsi_put = r_now_f >= ROBOFIBO_RSI_PUT_MIN and (r_now_f <= r_prev_f + 1.0 or r_now_f >= 65.0)
    ema_call = c >= float(ema_now) or float(ema_now) >= float(ema_prev)
    ema_put = c <= float(ema_now) or float(ema_now) <= float(ema_prev)

    call = put = 0.0
    call_reasons = []; put_reasons = []
    if near_low_zone: call += 3.0; call_reasons.append("zona Fibonacci 0-23.6%")
    if near_high_zone: put += 3.0; put_reasons.append("zona Fibonacci 76.4-100%")
    if bull_reaction: call += 2.0; call_reasons.append("rejeição compradora")
    if bear_reaction: put += 2.0; put_reasons.append("rejeição vendedora")
    if rsi_call: call += 1.8; call_reasons.append(f"RSI14 {r_now_f:.1f}")
    if rsi_put: put += 1.8; put_reasons.append(f"RSI14 {r_now_f:.1f}")
    if ema_call: call += 0.9; call_reasons.append("EMA60 favorece CALL")
    if ema_put: put += 0.9; put_reasons.append("EMA60 favorece PUT")
    if r_now_f <= 30.0: call += 0.6; call_reasons.append("RSI sobrevendido")
    if r_now_f >= 70.0: put += 0.6; put_reasons.append("RSI sobrecomprado")

    call_ok = near_low_zone and bull_reaction and rsi_call and call >= ROBOFIBO_MIN_SCORE
    put_ok = near_high_zone and bear_reaction and rsi_put and put >= ROBOFIBO_MIN_SCORE
    direction = "NEUTRO"
    if call_ok and not put_ok and (call - put) >= ROBOFIBO_SCORE_EDGE:
        direction = "CALL"
    elif put_ok and not call_ok and (put - call) >= ROBOFIBO_SCORE_EDGE:
        direction = "PUT"
    elif call_ok and put_ok:
        if call - put >= ROBOFIBO_SCORE_EDGE:
            direction = "CALL"
        elif put - call >= ROBOFIBO_SCORE_EDGE:
            direction = "PUT"

    # Confluência opcional do Volume POC. O botão do painel não cria outro motor:
    # apenas filtra o candidato do RoboFibo. OFF = lógica Fibo original;
    # ON = o POC precisa confirmar a MESMA direção no mesmo candle fechado.
    fibo_candidate = direction
    poc_snapshot = None
    poc_direction = "NEUTRO"
    poc_confluence = not use_poc
    poc_reason = "POC OFF" if not use_poc else "POC aguardando confirmação"
    if use_poc:
        try:
            poc_snapshot = _volume_poc_snapshot(rows, early_signal=False, use_ai=False, mtf=None)
        except Exception:
            poc_snapshot = None
        if isinstance(poc_snapshot, dict):
            poc_direction = str(poc_snapshot.get("direction") or "NEUTRO").upper()
            coverage_ok = bool(poc_snapshot.get("coverage_ok"))
            poc_call = bool(poc_snapshot.get("poc_call"))
            poc_put = bool(poc_snapshot.get("poc_put"))
            if fibo_candidate == "CALL":
                poc_confluence = coverage_ok and (poc_direction == "CALL" or poc_call)
            elif fibo_candidate == "PUT":
                poc_confluence = coverage_ok and (poc_direction == "PUT" or poc_put)
            else:
                poc_confluence = False
            poc_reason = (
                f"POC {poc_direction} • cobertura {float(poc_snapshot.get('volume_coverage') or 0.0)*100:.0f}%"
                + (" • CONFIRMOU" if poc_confluence else " • NÃO CONFIRMOU")
            )
        if fibo_candidate in ("CALL", "PUT") and not poc_confluence:
            direction = "NEUTRO"

    score = call if direction == "CALL" else (put if direction == "PUT" else max(call, put))
    confidence = 0.0
    if direction != "NEUTRO":
        confidence = clamp(64.0 + max(0.0, score - ROBOFIBO_MIN_SCORE) * 7.0 + min(8.0, abs(call - put) * 1.8), 64.0, 93.0)
        reasons = call_reasons if direction == "CALL" else put_reasons
        reason = f"{direction} ROBO FIBO: " + ", ".join(reasons[:5])
        if use_poc:
            reason += f" • {poc_reason}"
        reason += ". Entrada na próxima vela."
    else:
        reason = (f"ROBO FIBO monitorando • RSI14 {r_now_f:.1f} • EMA60 {float(ema_now):.8g} • "
                  f"Fibo23.6 {fib236:.8g} • Fibo76.4 {fib764:.8g}")
        if use_poc:
            if fibo_candidate in ("CALL", "PUT"):
                reason += f" • candidato {fibo_candidate} bloqueado: {poc_reason}"
            else:
                reason += f" • {poc_reason}"
        reason += "."

    evt = str(last.get("datetime") or last.get("timestamp") or len(rows))
    return {
        "available": True, "direction": direction, "confidence": round(float(confidence), 1),
        "confirmed": direction in ("CALL", "PUT"),
        "risk": ("LOW" if confidence >= 83 else "MEDIUM") if direction != "NEUTRO" else "HIGH",
        "strategy": name, "engine": "FIBORSI", "provider": "LOCAL_ROBO_FIBO",
        "reason": reason[:460], "non_repaint": True, "non_repaint_after_release": True,
        "closed_candles_only": True, "next_candle_entry": True, "direct_win_only": True,
        "gale_signal": False, "martingale": False,
        "event_key": f"FIBORSI:{direction}:{evt}",
        "fibonacci": {
            "bars_back": ROBOFIBO_BARS_BACK, "low": float(low_value), "high": float(high_value),
            "level_23_6": float(fib236), "level_38_2": float(fib382), "level_50_0": float(fib500),
            "level_61_8": float(fib618), "level_76_4": float(fib764), "zone_tolerance": float(zone),
        },
        "rsi": round(r_now_f, 2), "rsi_previous": round(r_prev_f, 2),
        "ema60": float(ema_now), "ema60_previous": float(ema_prev),
        "poc_filter_enabled": bool(use_poc),
        "poc_confluence": bool(poc_confluence),
        "poc_direction": poc_direction,
        "poc_candidate_direction": fibo_candidate,
        "volume_poc": ({
            "direction": poc_direction,
            "confidence": round(float((poc_snapshot or {}).get("confidence") or 0.0), 1),
            "poc": float((poc_snapshot or {}).get("poc") or 0.0),
            "volume_coverage": round(float((poc_snapshot or {}).get("volume_coverage") or 0.0), 4),
            "poc_call": bool((poc_snapshot or {}).get("poc_call")),
            "poc_put": bool((poc_snapshot or {}).get("poc_put")),
        } if use_poc and isinstance(poc_snapshot, dict) else None),
        "diagnostics": {
            "call_score": round(call, 2), "put_score": round(put, 2), "min_score": ROBOFIBO_MIN_SCORE,
            "near_low_zone": near_low_zone, "near_high_zone": near_high_zone,
            "bull_reaction": bull_reaction, "bear_reaction": bear_reaction,
            "ema_call": ema_call, "ema_put": ema_put,
            "lower_wick_ratio": round(lower_wr, 4), "upper_wick_ratio": round(upper_wr, 4),
        },
    }


# AlphaX RELAY — padrão de vela é o gatilho principal; basta 1 confirmação
# do contexto AlphaX para liberar CALL/PUT na próxima vela fechada.
# O objetivo é manter o motor mais solto sem aceitar padrão isolado em mercado ruim.
ALPHAX_ATR_PERIOD = max(7, min(30, int(os.getenv("ALPHAX_ATR_PERIOD", "14"))))
ALPHAX_PIVOT_LEN = max(2, min(12, int(os.getenv("ALPHAX_PIVOT_LEN", "5"))))
ALPHAX_EMA_FAST = max(8, min(50, int(os.getenv("ALPHAX_EMA_FAST", "21"))))
ALPHAX_EMA_SLOW = max(ALPHAX_EMA_FAST + 5, min(120, int(os.getenv("ALPHAX_EMA_SLOW", "55"))))
ALPHAX_CHOP_LEN = max(7, min(30, int(os.getenv("ALPHAX_CHOP_LEN", "14"))))
ALPHAX_CHOP_MAX = max(50.0, min(75.0, float(os.getenv("ALPHAX_CHOP_MAX", "62"))))
ALPHAX_VOL_LEN = max(8, min(50, int(os.getenv("ALPHAX_VOL_LEN", "20"))))
ALPHAX_VOL_FACTOR = max(0.60, min(1.80, float(os.getenv("ALPHAX_VOL_FACTOR", "0.95"))))
ALPHAX_BODY_ATR_MIN = max(0.15, min(1.20, float(os.getenv("ALPHAX_BODY_ATR_MIN", "0.35"))))
ALPHAX_MIN_CONFIRMATIONS = max(1, min(3, int(os.getenv("ALPHAX_MIN_CONFIRMATIONS", "1"))))
ALPHAX_COOLDOWN_BARS = max(1, min(10, int(os.getenv("ALPHAX_COOLDOWN_BARS", "2"))))
# 3.73 — AlphaX antecipa o sinal oficial para aproximadamente 30 s antes
# da próxima vela. A leitura usa um snapshot da vela em formação nessa janela
# e, depois de liberado, o sinal fica travado até a expiração (não repinta).
ALPHAX_EARLY_SIGNAL_SECONDS = max(20, min(45, int(os.getenv("ALPHAX_EARLY_SIGNAL_SECONDS", "30"))))
ALPHAX_EARLY_WINDOW_BEFORE = max(ALPHAX_EARLY_SIGNAL_SECONDS, min(50, int(os.getenv("ALPHAX_EARLY_WINDOW_BEFORE", "35"))))
ALPHAX_EARLY_MIN_REMAINING = max(12, min(ALPHAX_EARLY_SIGNAL_SECONDS, int(os.getenv("ALPHAX_EARLY_MIN_REMAINING", "18"))))
# RELAY original usa FORMING -> ARMED -> FIRED. Para o app, a zona ARMED é
# deliberadamente um pouco mais larga e o breakout um pouco mais curto para
# não atrasar demais a entrada em opções binárias.
ALPHAX_MIN_FORM_PCT = max(45.0, min(80.0, float(os.getenv("ALPHAX_MIN_FORM_PCT", "52"))))
ALPHAX_ARMED_ATR = max(0.15, min(1.00, float(os.getenv("ALPHAX_ARMED_ATR", "0.50"))))
ALPHAX_BREAK_ATR = max(0.10, min(1.20, float(os.getenv("ALPHAX_BREAK_ATR", "0.35"))))

# 3.77 — Núcleo Rápido mantém os filtros 3.76 e inverte somente o sinal final (CALL↔PUT). AlphaX intacto.
# O novo motor só libera quando zona + microimpulso + Scalper + CRIPTOBOT concordam.
RAPID_EARLY_SIGNAL_SECONDS = max(20, min(45, int(os.getenv("RAPID_EARLY_SIGNAL_SECONDS", "30"))))
RAPID_EARLY_WINDOW_BEFORE = max(RAPID_EARLY_SIGNAL_SECONDS, min(50, int(os.getenv("RAPID_EARLY_WINDOW_BEFORE", "35"))))
RAPID_EARLY_MIN_REMAINING = max(12, min(RAPID_EARLY_SIGNAL_SECONDS, int(os.getenv("RAPID_EARLY_MIN_REMAINING", "18"))))
RAPID_COOLDOWN_BARS = max(2, min(10, int(os.getenv("RAPID_COOLDOWN_BARS", "3"))))
RAPID_MIN_CONFIDENCE = max(75.0, min(95.0, float(os.getenv("RAPID_MIN_CONFIDENCE", "82"))))
RAPID_RB_CONFIRM_SCORE = max(60.0, min(90.0, float(os.getenv("RAPID_RB_CONFIRM_SCORE", "65"))))
RAPID_MAX_STRETCH_ATR = max(0.70, min(2.50, float(os.getenv("RAPID_MAX_STRETCH_ATR", "1.30"))))
RAPID_MAX_ENTRY_RANGE_RATIO = max(1.20, min(3.50, float(os.getenv("RAPID_MAX_ENTRY_RANGE_RATIO", "1.90"))))
RAPID_AI_GEN_QUALITY_MIN = max(35.0, min(80.0, float(os.getenv("RAPID_AI_GEN_QUALITY_MIN", "55"))))
RAPID_AI_GEN_HARD_BLOCK = max(20.0, min(RAPID_AI_GEN_QUALITY_MIN, float(os.getenv("RAPID_AI_GEN_HARD_BLOCK", "38"))))
RAPID_AI_GEN_MAX_RANGE_RATIO = max(1.50, min(6.00, float(os.getenv("RAPID_AI_GEN_MAX_RANGE_RATIO", "2.80"))))
RAPID_AI_GEN_MIN_RANGE_RATIO = max(0.05, min(0.60, float(os.getenv("RAPID_AI_GEN_MIN_RANGE_RATIO", "0.18"))))
RAPID_AI_GEN_MAX_WICK_RATIO = max(0.55, min(0.95, float(os.getenv("RAPID_AI_GEN_MAX_WICK_RATIO", "0.78"))))

# 3.80 — Volume POC rápido: snapshot nos 20s finais para a PRÓXIMA vela.
# O delta continua sendo estimado por OHLCV quando a fonte não entrega agressor bid/ask real.
# Os filtros foram levemente afrouxados para aumentar a frequência sem liberar um lado
# sem vantagem mínima sobre o lado oposto. Depois da liberação, active_signal congela o sinal.
VOLUME_POC_LOOKBACK = max(20, min(90, int(os.getenv("VOLUME_POC_LOOKBACK", "28"))))
VOLUME_POC_BINS = max(12, min(40, int(os.getenv("VOLUME_POC_BINS", "20"))))
VOLUME_POC_DELTA_LOOKBACK = max(4, min(25, int(os.getenv("VOLUME_POC_DELTA_LOOKBACK", "6"))))
VOLUME_POC_IMBALANCE_THRESHOLD = max(0.12, min(0.80, float(os.getenv("VOLUME_POC_IMBALANCE_THRESHOLD", "0.18"))))
VOLUME_POC_STACKED_ROWS = max(2, min(5, int(os.getenv("VOLUME_POC_STACKED_ROWS", "2"))))
VOLUME_POC_ABSORPTION_VOL = max(0.65, min(3.00, float(os.getenv("VOLUME_POC_ABSORPTION_VOL", "0.78"))))
VOLUME_POC_EXHAUSTION_VOL = max(0.80, min(4.00, float(os.getenv("VOLUME_POC_EXHAUSTION_VOL", "1.00"))))
VOLUME_POC_EXHAUSTION_DELTA = max(0.03, min(0.35, float(os.getenv("VOLUME_POC_EXHAUSTION_DELTA", "0.10"))))
VOLUME_POC_MIN_SCORE = max(2, min(3, int(os.getenv("VOLUME_POC_MIN_SCORE", "2"))))
VOLUME_POC_SCORE_EDGE = max(1, min(5, int(os.getenv("VOLUME_POC_SCORE_EDGE", "1"))))
VOLUME_POC_COOLDOWN_BARS = max(1, min(10, int(os.getenv("VOLUME_POC_COOLDOWN_BARS", "1"))))
VOLUME_POC_MIN_VOLUME_COVERAGE = max(0.15, min(0.30, float(os.getenv("VOLUME_POC_MIN_VOLUME_COVERAGE", "0.20"))))
VOLUME_POC_EARLY_SIGNAL_SECONDS = 55
VOLUME_POC_EARLY_WINDOW_BEFORE = max(30, min(58, int(os.getenv("VOLUME_POC_EARLY_WINDOW_BEFORE", "55"))))
VOLUME_POC_EARLY_MIN_REMAINING = max(3, min(12, int(os.getenv("VOLUME_POC_EARLY_MIN_REMAINING", "5"))))
# S/R multi-timeframe do Volume POC. Timeframes maiores têm mais peso, mas nenhum
# deles é obrigatório isoladamente. M30 é agregado do M15 e H4 é agregado do H1.
VOLUME_POC_MTF_WEIGHTS = {"M15": 1, "M30": 1, "H1": 2, "H4": 3}
VOLUME_POC_MTF_CACHE_TTL = max(30.0, min(300.0, float(os.getenv("VOLUME_POC_MTF_CACHE_TTL", "90"))))
volume_poc_mtf_cache: Dict[str, Any] = {}
# MEGA IA 3.80.6 — IA contextual leve do Volume POC.
# Ela NÃO é confirmação obrigatória: melhora setups marginais quando concorda e
# só protege contra o caso mais fraco (POC exatamente no mínimo + IA fortemente contrária).
VOLUME_POC_AI_ENABLED = False  # removido: Volume POC agora é estrutural e independente de IA/EA
VOLUME_POC_AI_SCORE_BONUS = max(0, min(2, int(os.getenv("VOLUME_POC_AI_SCORE_BONUS", "1"))))
