def _symbol_allowed(symbol: str, market: str = "OPEN") -> bool:
    """Aceita a lista nativa e, em OPEN, os símbolos dinâmicos da cTrader.

    A disponibilidade real de um símbolo dinâmico é sempre validada contra a
    conta cTrader autorizada antes de buscar candles. Em OTC mantemos somente
    os ativos conhecidos da IQ Option.
    """
    sym = str(symbol or "").strip().upper()
    market = str(market or "OPEN").strip().upper()
    if sym in SYMBOLS:
        return True
    if market != "OPEN":
        return False
    if not (1 <= len(sym) <= 64):
        return False
    return bool(re.fullmatch(r"[A-Z0-9][A-Z0-9 ._/#&+():-]{0,63}", sym))


def _rtm_symbol_allowed(symbol: str) -> bool:
    """RTM: somente BTC/USD e qualquer par que contenha JPY."""
    compact = re.sub(r"[^A-Z0-9]", "", str(symbol or "").upper())
    return compact == "BTCUSD" or "JPY" in compact


def _rtm_scan_symbols(market: str = "OPEN", configured=None) -> list[str]:
    """Lista automática da RTM, respeitando mercado e seleção opcional."""
    market = str(market or "OPEN").upper()
    source = list(configured or RTM_DEFAULT_SCAN_SYMBOLS)
    out = []
    seen = set()
    for raw in source:
        sym = str(raw or "").strip().upper()
        if not sym or sym in seen:
            continue
        if not _rtm_symbol_allowed(sym):
            continue
        if not _symbol_allowed(sym, market):
            continue
        seen.add(sym)
        out.append(sym)
    return out


def _ctrader_canonical_symbol_name(raw_name: str) -> str:
    raw = str(raw_name or "").strip()
    upper = raw.upper()
    compact = re.sub(r"[^A-Z0-9]", "", upper)
    for known in SYMBOLS:
        if known == BINOMO_CRYPTO_IDX_SYMBOL:
            continue
        if re.sub(r"[^A-Z0-9]", "", known.upper()) == compact:
            return known
    return upper

