def _td_ws_dt_string(bucket_ts: int) -> str:
    return datetime.fromtimestamp(int(bucket_ts), tz=UTC).strftime("%Y-%m-%d %H:%M:%S")


def _td_ws_recent_ticks(symbol: str, window_seconds: float = 35.0):
    """Retorna ticks reais recebidos do Twelve Data WS no intervalo solicitado."""
    cutoff = time.time() - max(0.5, float(window_seconds or 35.0))
    with td_ws_lock:
        tape = list(td_ws_tick_tape.get(str(symbol or "").upper(), []) or [])
    return [(float(ts), float(px)) for ts, px in tape if float(ts) >= cutoff and float(px) > 0]


def _td_ws_update_price(event: Dict[str, Any]):
    """Converte um tick de preço do WS em candles OHLCV para todos os timeframes."""
    global td_ws_last_message_at
    try:
        symbol = str(event.get("symbol", "")).strip().upper()
        if symbol not in SYMBOLS:
            return
        price = float(event.get("price"))
        ts = int(float(event.get("timestamp") or time.time()))
        if price <= 0 or ts <= 0:
            return
    except Exception:
        return

    # day_volume é cumulativo quando existe. Convertemos apenas o incremento do
    # tick em volume do candle; para Forex normalmente será 0/indisponível.
    vol_delta = 0.0
    try:
        dv = event.get("day_volume")
        if dv is not None:
            dv = float(dv)
            prev = td_ws_prev_day_volume.get(symbol)
            if prev:
                prev_ts, prev_dv = prev
                same_day = datetime.fromtimestamp(prev_ts, tz=UTC).date() == datetime.fromtimestamp(ts, tz=UTC).date()
                if same_day and dv >= prev_dv:
                    vol_delta = max(0.0, dv - prev_dv)
            td_ws_prev_day_volume[symbol] = (ts, dv)
    except Exception:
        vol_delta = 0.0

    with td_ws_lock:
        received_at = time.time()
        td_ws_last_message_at = received_at
        td_ws_last_tick_at[symbol] = received_at
        tape = td_ws_tick_tape.setdefault(symbol, [])
        tape.append((received_at, price))
        cutoff = received_at - 75.0
        if len(tape) > 4:
            tape[:] = [(t, p) for t, p in tape if t >= cutoff][-1200:]
        for interval, seconds in INTERVALS.items():
            seconds = int(seconds)
            bucket = (ts // seconds) * seconds
            key = f"{symbol}|{interval}"
            rows = td_ws_bars.setdefault(key, [])
            dt_str = _td_ws_dt_string(bucket)

            if rows:
                last = rows[-1]
                last_bucket = int(last.get("_bucket", 0) or 0)
                if bucket < last_bucket:
                    continue
                if bucket == last_bucket:
                    last["high"] = max(float(last["high"]), price)
                    last["low"] = min(float(last["low"]), price)
                    last["close"] = price
                    last["volume"] = float(last.get("volume", 0) or 0) + vol_delta
                    continue

            rows.append({
                "datetime": dt_str,
                "open": price,
                "high": price,
                "low": price,
                "close": price,
                "volume": vol_delta,
                "_bucket": bucket,
                "source": "TWELVE_DATA_WS",
            })
            if len(rows) > 220:
                del rows[:-220]


def _td_ws_on_open(ws):
    global td_ws_connected, td_ws_last_error
    with td_ws_lock:
        td_ws_connected = True
        td_ws_last_error = ""
    symbols = ",".join(TD_WS_REQUESTED_SYMBOLS)
    if not symbols:
        return
    try:
        ws.send(json.dumps({"action": "subscribe", "params": {"symbols": symbols}}))
        print(f"[TD WS] conectado; solicitando {len(TD_WS_REQUESTED_SYMBOLS)} símbolos", flush=True)
    except Exception as exc:
        with td_ws_lock:
            td_ws_last_error = str(exc)[:180]


def _td_ws_on_message(ws, message):
    global td_ws_last_message_at, td_ws_last_error
    td_ws_last_message_at = time.time()
    try:
        data = json.loads(message)
    except Exception:
        return
    event = str(data.get("event", "")).lower()
    if event == "price":
        _td_ws_update_price(data)
        return
    if event == "subscribe-status":
        success = data.get("success") or []
        fails = data.get("fails") or []
        ok_symbols = []
        fail_map = {}
        for item in success:
            if isinstance(item, dict):
                s = str(item.get("symbol", "")).strip().upper()
            else:
                s = str(item).strip().upper()
            if s:
                ok_symbols.append(s)
        for item in fails:
            if isinstance(item, dict):
                s = str(item.get("symbol") or item.get("code") or item).strip().upper()
                reason = str(item.get("message") or item.get("reason") or item)[:160]
            else:
                s = str(item).strip().upper()
                reason = str(item)[:160]
            if s:
                fail_map[s] = reason
        with td_ws_lock:
            td_ws_subscribed.clear()
            td_ws_subscribed.update(ok_symbols)
            td_ws_failed.clear()
            td_ws_failed.update(fail_map)
            if str(data.get("status", "")).lower() not in ("ok", "success") and not ok_symbols:
                td_ws_last_error = str(data)[:220]
        print(f"[TD WS] inscritos={len(ok_symbols)} falhas={len(fails)}", flush=True)
        return
    if event == "heartbeat":
        return
    # Algumas falhas chegam fora de subscribe-status.
    if str(data.get("status", "")).lower() in ("error", "failed"):
        with td_ws_lock:
            td_ws_last_error = str(data.get("message") or data)[:220]


def _td_ws_on_error(ws, error):
    global td_ws_last_error
    with td_ws_lock:
        td_ws_last_error = str(error or "erro websocket")[:220]
    print(f"[TD WS] erro: {td_ws_last_error}", flush=True)


def _td_ws_on_close(ws, status_code, message):
    global td_ws_connected
    with td_ws_lock:
        td_ws_connected = False
    print(f"[TD WS] desconectado status={status_code} msg={str(message or '')[:120]}", flush=True)


def _td_ws_runner():
    global td_ws_app, td_ws_connected
    backoff = 2.0
    while not td_ws_stop.is_set():
        if not TD_WS_ENABLED or not TD_KEY or websocket is None or not TD_WS_REQUESTED_SYMBOLS:
            return
        try:
            url = f"{TD_WS_URL}?apikey={TD_KEY}"
            app_ws = websocket.WebSocketApp(
                url,
                on_open=_td_ws_on_open,
                on_message=_td_ws_on_message,
                on_error=_td_ws_on_error,
                on_close=_td_ws_on_close,
            )
            with td_ws_lock:
                td_ws_app = app_ws
            app_ws.run_forever(ping_interval=25, ping_timeout=10)
        except Exception as exc:
            _td_ws_on_error(None, exc)
        finally:
            with td_ws_lock:
                td_ws_connected = False
                td_ws_app = None
        if td_ws_stop.wait(backoff):
            break
        backoff = min(TD_WS_RECONNECT_MAX, max(2.0, backoff * 1.7))


def ensure_td_ws_started() -> bool:
    global td_ws_thread
    if not TD_WS_ENABLED or not TD_KEY or websocket is None or not TD_WS_REQUESTED_SYMBOLS:
        return False
    with td_ws_lock:
        if td_ws_thread and td_ws_thread.is_alive():
            return True
        td_ws_stop.clear()
        td_ws_thread = threading.Thread(target=_td_ws_runner, name="twelve-data-ws", daemon=True)
        td_ws_thread.start()
    return True


def _td_ws_stop_now():
    td_ws_stop.set()
    app_ws = None
    with td_ws_lock:
        app_ws = td_ws_app
    try:
        if app_ws is not None:
            app_ws.close()
    except Exception:
        pass


def _td_ws_snapshot(symbol: str, interval: str):
    key = f"{symbol}|{interval}"
    with td_ws_lock:
        rows = td_ws_bars.get(key, [])
        return [dict(r) for r in rows]


def _td_ws_active_symbols():
    with td_ws_lock:
        return set(td_ws_subscribed)


def _td_ws_is_fresh(symbol: str, max_age: float | None = None) -> bool:
    age_limit = float(max_age if max_age is not None else TD_WS_FRESH_SECONDS)
    with td_ws_lock:
        ts = float(td_ws_last_tick_at.get(symbol, 0.0) or 0.0)
        return ts > 0 and (time.time() - ts) <= age_limit


def _td_row_epoch(row: Dict[str, Any], interval: str) -> int | None:
    raw = str(row.get("datetime", "")).strip()
    if not raw:
        return None
    try:
        d = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except Exception:
        return None
    if d.tzinfo is None:
        d = d.replace(tzinfo=UTC)
    else:
        d = d.astimezone(UTC)
    sec = int(INTERVALS.get(interval, 60))
    return (int(d.timestamp()) // sec) * sec


def _td_merge_rest_ws(rest_rows, ws_rows, interval: str):
    """Mescla histórico REST (UTC) com candles formados por ticks WS."""
    merged = {}
    order = []
    for row in list(rest_rows or []):
        bucket = _td_row_epoch(row, interval)
        if bucket is None:
            continue
        clean = dict(row)
        clean.pop("_bucket", None)
        merged[bucket] = clean
        order.append(bucket)

    for row in list(ws_rows or []):
        bucket = int(row.get("_bucket") or (_td_row_epoch(row, interval) or 0))
        if not bucket:
            continue
        live = dict(row)
        live.pop("_bucket", None)
        old = merged.get(bucket)
        if old:
            try:
                merged[bucket] = {
                    **old,
                    "datetime": _td_ws_dt_string(bucket),
                    "open": float(old.get("open", live["open"])),
                    "high": max(float(old.get("high", live["high"])), float(live["high"])),
                    "low": min(float(old.get("low", live["low"])), float(live["low"])),
                    "close": float(live["close"]),
                    "volume": max(float(old.get("volume", 0) or 0), float(live.get("volume", 0) or 0)),
                    "source": "TWELVE_DATA_WS",
                }
            except Exception:
                merged[bucket] = live
        else:
            merged[bucket] = live
            order.append(bucket)

    return [merged[b] for b in sorted(set(order)) if b in merged][-220:]


def _binomo_quote_ws_update(price: float, when_utc: datetime):
    """Agrega um tick real do Z-CRY/IDX em candles do app."""
    global binomo_quote_ws_last_message_at, binomo_quote_ws_last_tick_at
    try:
        px = float(price)
        if px <= 0:
            return
        ts = int(when_utc.astimezone(UTC).timestamp())
    except Exception:
        return

    with binomo_quote_ws_lock:
        binomo_quote_ws_last_message_at = time.time()
        binomo_quote_ws_last_tick_at = time.time()
        for interval_name, seconds in INTERVALS.items():
            bucket = int(ts // int(seconds) * int(seconds))
            key = f"{BINOMO_CRYPTO_IDX_SYMBOL}|{interval_name}"
            rows = list(binomo_quote_ws_bars.get(key) or [])
            dt_text = datetime.fromtimestamp(bucket, tz=UTC).isoformat()
            if rows and int(rows[-1].get("_bucket", -1)) == bucket:
                row = dict(rows[-1])
                row["high"] = max(float(row.get("high", px)), px)
                row["low"] = min(float(row.get("low", px)), px)
                row["close"] = px
                row["datetime"] = dt_text
                row["feed_source"] = "BINOMO_CRYPTO_IDX_WS"
                row["source_symbol"] = BINOMO_CRYPTO_IDX_RIC
                rows[-1] = row
            else:
                rows.append({
                    "datetime": dt_text,
                    "open": px,
                    "high": px,
                    "low": px,
                    "close": px,
                    "volume": 0.0,
                    "feed_source": "BINOMO_CRYPTO_IDX_WS",
                    "source_symbol": BINOMO_CRYPTO_IDX_RIC,
                    "_bucket": bucket,
                })
            binomo_quote_ws_bars[key] = rows[-240:]


def _binomo_quote_ws_rows(interval: str, n: int = 80):
    key = f"{BINOMO_CRYPTO_IDX_SYMBOL}|{interval}"
    with binomo_quote_ws_lock:
        rows = [dict(x) for x in (binomo_quote_ws_bars.get(key) or [])]
        last_tick = float(binomo_quote_ws_last_tick_at or 0)
        connected = bool(binomo_quote_ws_connected) or _binomo_any_authenticated_ws_connected()
    if not rows:
        return []
    # Não entrega stream abandonado como se ainda estivesse online.
    if not connected and (not last_tick or time.time() - last_tick > max(60.0, BINOMO_QUOTE_WS_FRESH_SECONDS * 3)):
        return []
    out = []
    for row in rows[-max(1, int(n)):]:
        row.pop("_bucket", None)
        out.append(row)
    return out


def _binomo_quote_ws_extract(message):
    """Extrai ticks do Z-CRY/IDX do stream público sem assumir um único envelope JSON.

    O formato histórico observado em as.binomo.com é data -> assets -> {ric, rate,
    created_at}. Como o endpoint não é documentado, o parser também aceita níveis
    extras de data/items/result, mas só transforma em tick quando o RIC é o Crypto IDX.
    """
    try:
        payload = json.loads(message) if isinstance(message, str) else message
    except Exception:
        return []

    target = str(BINOMO_CRYPTO_IDX_RIC or "").strip().upper()
    found = []

    def walk(node, inherited_ric="", depth=0):
        if depth > 7:
            return
        if isinstance(node, list):
            for item in node[:300]:
                walk(item, inherited_ric, depth + 1)
            return
        if not isinstance(node, dict):
            return

        raw_ric = _binomo_pick(node, "ric", "asset_ric", "symbol", "asset", "ticker")
        ric = str(raw_ric or inherited_ric or "").strip().upper()
        raw_price = _binomo_pick(node, "rate", "price", "quote", "last", "close")
        raw_time = _binomo_pick(node, "created_at", "createdAt", "timestamp", "time", "datetime", "ts")

        # Não mistura outro ativo no Crypto IDX. O feed público pode entregar mais
        # de um ativo no mesmo envelope.
        if raw_price is not None and raw_time is not None and ric == target:
            try:
                px = float(raw_price)
                dt = _binomo_parse_timestamp(raw_time).astimezone(UTC)
                if px > 0:
                    found.append((px, dt))
            except Exception:
                pass

        next_ric = ric or inherited_ric
        for key in ("data", "assets", "items", "result", "values", "quotes", "ticks", "payload"):
            child = node.get(key)
            if isinstance(child, (dict, list)):
                walk(child, next_ric, depth + 1)

    walk(payload)

    # Remove duplicatas do mesmo tick sem alterar a ordem recebida.
    uniq = []
    seen = set()
    for px, dt in found:
        key = (round(float(px), 12), int(dt.timestamp() * 1000))
        if key in seen:
            continue
        seen.add(key)
        uniq.append((px, dt))
    return uniq

def _binomo_quote_ws_run():
    global binomo_quote_ws_app, binomo_quote_ws_connected
    global binomo_quote_ws_last_message_at, binomo_quote_ws_last_error
    global binomo_quote_ws_message_count, binomo_quote_ws_last_payload_preview
    if websocket is None:
        binomo_quote_ws_last_error = "websocket-client não instalado"
        return

    while not binomo_quote_ws_stop.is_set():
        try:
            def on_open(ws):
                global binomo_quote_ws_connected, binomo_quote_ws_last_error
                binomo_quote_ws_connected = True
                binomo_quote_ws_last_error = ""
                # Protocolo de cotação observado no endpoint público histórico.
                # É somente leitura: não envia login, ordem, carteira ou credencial.
                ws.send(f"subscribe:{BINOMO_CRYPTO_IDX_RIC}")
                print(f"[BINOMO IDX PUBLIC WS] conectado • subscribe:{BINOMO_CRYPTO_IDX_RIC}", flush=True)

            def on_message(ws, message):
                global binomo_quote_ws_last_message_at, binomo_quote_ws_last_error
                global binomo_quote_ws_message_count, binomo_quote_ws_last_payload_preview
                binomo_quote_ws_last_message_at = time.time()
                binomo_quote_ws_message_count += 1
                try:
                    preview = message.decode("utf-8", "ignore") if isinstance(message, (bytes, bytearray)) else str(message)
                    binomo_quote_ws_last_payload_preview = preview[:220]
                    low = preview.lower()
                    if "blocked_country" in low or "platform_not_available" in low:
                        binomo_quote_ws_last_error = "feed público recusado por restrição regional"
                except Exception:
                    pass

                ticks = _binomo_quote_ws_extract(message)
                for px, dt in ticks:
                    _binomo_quote_ws_update(px, dt)
                if ticks:
                    binomo_quote_ws_last_error = ""

            def on_error(ws, error):
                global binomo_quote_ws_last_error
                binomo_quote_ws_last_error = str(error)[:220]

            def on_close(ws, status_code, close_msg):
                global binomo_quote_ws_connected, binomo_quote_ws_last_error
                binomo_quote_ws_connected = False
                if close_msg:
                    binomo_quote_ws_last_error = f"close {status_code}: {close_msg}"[:220]
                elif status_code:
                    binomo_quote_ws_last_error = f"close {status_code}"[:220]

            app_ws = websocket.WebSocketApp(
                BINOMO_QUOTE_WS_URL,
                header=[
                    f"User-Agent: {PUBLIC_FEED_USER_AGENT}",
                    "Pragma: no-cache",
                    "Cache-Control: no-cache",
                ],
                on_open=on_open,
                on_message=on_message,
                on_error=on_error,
                on_close=on_close,
            )
            binomo_quote_ws_app = app_ws
            app_ws.run_forever(
                ping_interval=20,
                ping_timeout=10,
                origin="https://binomo.com",
            )
        except Exception as exc:
            binomo_quote_ws_last_error = str(exc)[:220]
        finally:
            binomo_quote_ws_connected = False
            binomo_quote_ws_app = None
        if not binomo_quote_ws_stop.wait(max(1.0, BINOMO_QUOTE_WS_RECONNECT_SECONDS)):
            continue

def ensure_binomo_quote_ws_started():
    global binomo_quote_ws_thread
    if not BINOMO_QUOTE_WS_ENABLED or websocket is None:
        return False
    with binomo_quote_ws_lock:
        if binomo_quote_ws_thread and binomo_quote_ws_thread.is_alive():
            return True
        binomo_quote_ws_stop.clear()
        binomo_quote_ws_thread = threading.Thread(target=_binomo_quote_ws_run, name="binomo-crypto-idx-ws", daemon=True)
        binomo_quote_ws_thread.start()
        return True


def _binomo_quote_ws_stop_now():
    binomo_quote_ws_stop.set()
    app_ws = binomo_quote_ws_app
    try:
        if app_ws:
            app_ws.close()
    except Exception:
        pass


@app.on_event("startup")
async def _start_twelve_data_websocket():
    global background_bot_task
    if ensure_td_ws_started():
        print("[TD WS] thread de streaming iniciada", flush=True)
    elif TD_WS_ENABLED:
        reason = "chave ausente" if not TD_KEY else "websocket-client indisponível"
        print(f"[TD WS] não iniciado: {reason}", flush=True)
    if ensure_binomo_quote_ws_started():
        print(f"[BINOMO IDX WS] stream iniciado • {BINOMO_CRYPTO_IDX_RIC}", flush=True)
    elif BINOMO_QUOTE_WS_ENABLED:
        print("[BINOMO IDX WS] não iniciado: websocket-client indisponível", flush=True)
    if background_bot_task is None or background_bot_task.done():
        background_bot_task = asyncio.create_task(_background_bot_loop(), name="mega-background-signals")


@app.on_event("shutdown")
async def _stop_twelve_data_websocket():
    global background_bot_task
    _td_ws_stop_now()
    _binomo_quote_ws_stop_now()
    _close_all_binomo_sessions()
    task = background_bot_task
    background_bot_task = None
    if task is not None and not task.done():
        task.cancel()
        try:
            await task
        except asyncio.CancelledError:
            pass
        except Exception:
            pass

