@app.get("/iq-auto-capability")
async def iq_auto_capability(request: Request, symbol: str = "EUR/USD", interval: str = "1min", market: str = "OPEN"):
    state = _iq_session_state(request, required=False)
    if not state or not _iq_connected(state):
        return {"connected": False, "available": False, "reason": "Conecte a IQ Option primeiro.", "methods": []}

    symbol = str(symbol or "").upper()
    interval = str(interval or "1min")
    market = str(market or "OPEN").upper()
    if interval not in INTERVALS:
        raise HTTPException(400, "Intervalo inválido.")
    if market not in VALID_MARKETS:
        raise HTTPException(400, "Mercado inválido.")
    if symbol == BINOMO_CRYPTO_IDX_SYMBOL:
        return {"connected": True, "available": False, "reason": "Crypto IDX não é um ativo de opções da IQ Option.", "methods": []}

    try:
        data = await asyncio.wait_for(
            asyncio.to_thread(_iq_auto_capability_blocking, state, symbol, interval, market),
            timeout=12,
        )
    except asyncio.TimeoutError:
        data = {"available": True, "reason": "Catálogo da IQ demorou; a ordem fará tentativa controlada.", "methods": [], "exact": False}
    return {"connected": True, "symbol": symbol, "interval": interval, "market": market, **data}


@app.post("/iq-logout")
async def iq_logout(
    request: Request,
    response: Response,
):
    header_token = request.headers.get(
        "X-IQ-Session",
        "",
    )
    cookie_token = request.cookies.get(
        IQ_SESSION_COOKIE,
        "",
    )

    token = (
        header_token
        if header_token in iq_sessions
        else cookie_token
    )

    state = iq_sessions.pop(token, None)

    if state:
        state["password"] = ""
        state["candle_cache"] = {}
        _iq_close_state(state)

    response.delete_cookie(
        IQ_SESSION_COOKIE,
        path="/",
    )

    return {
        "connected": False,
        "message": "IQ Option desconectada.",
    }




# Diagnóstico isolado TBT OTC: o executável Windows recebido NÃO é executado no Render.
# Verifica se a integração IQ já existente consegue obter candles OTC autênticos.
@app.get("/tbt-otc-test/data")
async def tbt_otc_test_data(request: Request, symbol: str = "EUR/USD"):
    if symbol not in OTC_BASE:
        raise HTTPException(400, "Selecione um par OTC válido.")
    state = _iq_session_state(request, required=False)
    if state is None:
        return {"ok": False, "source": "IQ_OPTION_EXISTENTE", "tbt_integrated": False,
                "reason": "Conecte a IQ Option na aba Corretora; o TBT.exe não roda no Render."}
    try:
        rows = await asyncio.wait_for(iq_ea_candles(state, symbol, "1min", 80, regular_market=False), timeout=IQ_CANDLE_TIMEOUT + 8)
        samples = [{k: r.get(k) for k in ("datetime", "timestamp", "open", "high", "low", "close") if k in r} for r in rows[-3:] if isinstance(r, dict)]
        return {"ok": len(rows)>=20, "source": "IQ_OPTION_EXISTENTE", "tbt_integrated": False,
                "symbol": symbol, "interval": "1min", "candles": len(rows), "samples": samples,
                "reason": "Candles OTC recebidos da sessão IQ existente; não comprova funcionamento do TBT."}
    except Exception as exc:
        return {"ok": False, "source": "IQ_OPTION_EXISTENTE", "tbt_integrated": False,
                "symbol": symbol, "reason": str(exc)[:220]}

