@app.get("/candles")
async def candles_endpoint(
    request: Request,
    symbol: str = "EUR/USD",
    interval: str = "1min",
    n: int = 80,
    market: str = "OPEN",
    mirror_iq: bool = False,
):
    market = (market or "OPEN").upper()

    if not _symbol_allowed(symbol, market) or interval not in INTERVALS or market not in VALID_MARKETS:
        raise HTTPException(400, "Ativo, intervalo ou mercado inválido.")
    if symbol == BINOMO_CRYPTO_IDX_SYMBOL and market != "OPEN":
        raise HTTPException(400, "Crypto IDX é Binomo e não pode ser usado como OTC da IQ Option.")
    if symbol == BINOMO_CRYPTO_IDX_SYMBOL and mirror_iq:
        raise HTTPException(400, "Crypto IDX não pode ser espelhado pela IQ Option; use o feed Binomo.")

    n = max(20, min(int(n), 500))

    # Crypto IDX: o stream de cotações pode começar sem histórico. Para o gráfico
    # entregamos as primeiras velas imediatamente; o motor de sinais continua
    # exigindo histórico suficiente antes de liberar qualquer entrada.
    if symbol == BINOMO_CRYPTO_IDX_SYMBOL and market == "OPEN" and not mirror_iq:
        live_rows = _binomo_quote_ws_rows(interval, n)
        if live_rows:
            return {
                "ok": True,
                "symbol": symbol,
                "interval": interval,
                "market": market,
                "candles": live_rows,
                "status": ("OK" if len(live_rows) >= 20 else "AQUECENDO HISTÓRICO"),
                "message": (
                    "Crypto IDX ao vivo. Histórico suficiente para análise."
                    if len(live_rows) >= 20 else
                    f"Crypto IDX ao vivo. Formando histórico: {len(live_rows)}/20 candles para liberar análise."
                ),
                "feed_source": "BINOMO_CRYPTO_IDX_WS",
                "feed_label": _feed_source_label("BINOMO_CRYPTO_IDX_WS"),
                "feed_fallback": False,
                "source_symbol": BINOMO_CRYPTO_IDX_RIC,
                "warming_up": len(live_rows) < 20,
            }

    # Espelho do gráfico da IQ Option: sem sessão IQ, o gráfico fica OFFLINE.
    if mirror_iq:
        iq_state = _iq_session_state(request, required=False)
        if not iq_state or not _iq_connected(iq_state):
            return {
                "ok": False,
                "symbol": symbol,
                "interval": interval,
                "market": market,
                "candles": [],
                "status": "GRÁFICO OFFLINE",
                "message": "Conecte sua conta da IQ Option para espelhar o gráfico.",
                "mirror_iq": True,
            }
        try:
            # OTC usa o fluxo OTC existente. Mercado aberto busca o ativo normal da IQ.
            if market == "IQ_OTC":
                values = await candles(symbol, interval, n, "IQ_OTC", iq_state, request=request)
            else:
                lock = iq_state.get("lock") or asyncio.Lock()
                iq_state["lock"] = lock
                async with lock:
                    values = await asyncio.wait_for(
                        asyncio.to_thread(
                            iq_candles_blocking,
                            iq_state,
                            symbol,
                            interval,
                            max(80, int(n)),
                            True,
                        ),
                        timeout=IQ_CANDLE_TIMEOUT + 5,
                    )
            return {
                "ok": True,
                "symbol": symbol,
                "interval": interval,
                "market": market,
                "candles": values[-n:],
                "status": "IQ OPTION ESPELHADA",
                "mirror_iq": True,
            }
        except Exception as exc:
            return {
                "ok": False,
                "symbol": symbol,
                "interval": interval,
                "market": market,
                "candles": [],
                "status": "GRÁFICO IQ INDISPONÍVEL",
                "message": str(exc)[:220],
                "mirror_iq": True,
            }

    state = _iq_session_state(request, required=False) if market in ("OPEN", "IQ_OTC") else None

    try:
        if market == "IQ_OTC" and not state and not OTCHARTS_API_KEY:
            return {
                "ok": False,
                "symbol": symbol,
                "interval": interval,
                "market": market,
                "candles": [],
                "status": "LOGIN NECESSÁRIO",
                "message": "Faça login na IQ Option pela aba Corretora para carregar o OTC real.",
            }

        values = await candles(symbol, interval, n, market, state, request=request)

        feed_src = (_feed_source_from_rows(values) if market == "OPEN" else (("OTCHARTS_IQ_OTC" if OTCHARTS_API_KEY else "IQ_OPTION_OTC") if market == "IQ_OTC" else market))
        feed_info = _current_open_feed_info(symbol, interval) if market == "OPEN" else {}
        return {
            "ok": True,
            "symbol": symbol,
            "interval": interval,
            "market": market,
            "candles": values,
            "status": "OK",
            "feed_source": feed_src,
            "feed_label": _feed_source_label(feed_src),
            "feed_fallback": bool(feed_info.get("fallback")) if market == "OPEN" else False,
            "source_symbol": (values[-1].get("source_symbol") if values and isinstance(values[-1], dict) else None),
        }

    except HTTPException as exc:
        stale = []

        if market == "OPEN":
            if symbol == BINOMO_CRYPTO_IDX_SYMBOL:
                stale = _binomo_quote_ws_rows(interval, n)
            item = public_feed_cache.get(f"{symbol}|{interval}")
            if item:
                stale = item[1][-n:]
            elif not stale:
                item = td_candle_cache.get(f"{symbol}|{interval}")
                if item:
                    stale = item[1][-n:]

        elif market == "IQ_OTC" and state:
            item = state.setdefault("candle_cache", {}).get(f"{symbol}|{interval}")
            if item:
                stale = item[1][-n:]

        return {
            "ok": False,
            "symbol": symbol,
            "interval": interval,
            "market": market,
            "candles": stale,
            "status": "TEMPORARIAMENTE INDISPONÍVEL",
            "message": str(exc.detail)[:220],
            "stale": bool(stale),
            "feed_source": _feed_source_from_rows(stale) if stale else "UNAVAILABLE",
            "feed_label": (
                _feed_source_label(_feed_source_from_rows(stale))
                if stale else
                ("FONTE OTC INDISPONÍVEL" if market == "IQ_OTC" else ("BINOMO • CRYPTO IDX INDISPONÍVEL" if symbol == BINOMO_CRYPTO_IDX_SYMBOL else "MULTIFONTE INDISPONÍVEL"))
            ),
        }

    except Exception as exc:
        return {
            "ok": False,
            "symbol": symbol,
            "interval": interval,
            "market": market,
            "candles": [],
            "status": "TEMPORARIAMENTE INDISPONÍVEL",
            "message": str(exc)[:220],
        }


def _tg_display_time(value: str | None) -> str:
    if not value:
        return "--:--"
    try:
        return parse_dt(value).strftime("%H:%M:%S")
    except Exception:
        return str(value)[:19]


def _tg_chat_id(value: str | None) -> str:
    chat_id = str(value or TELEGRAM_CHAT_ID or "").strip()
    if not chat_id:
        raise HTTPException(
            400,
            "Chat ID do Telegram não configurado. Use a aba Telegram para localizar o grupo ou defina TELEGRAM_CHAT_ID no Render."
        )
    if chat_id.startswith("@"):
        return chat_id
    if not re.fullmatch(r"-?\d+", chat_id):
        raise HTTPException(400, "Chat ID do Telegram inválido.")
    return chat_id


def _tg_signal_text(body: TelegramSignalBody) -> str:
    if body.test:
        return (
            "✅ MEGA IA • TESTE TELEGRAM\n"
            "Integração ativa. Os próximos sinais CALL/PUT confirmados poderão ser enviados para este grupo."
        )
    direction = str(body.direction or "NEUTRO").upper()
    market_label = "MERCADO ABERTO" if str(body.market or "OPEN").upper() == "OPEN" else "OTC • IQ OPTION"
    result_label = str(body.result or "").upper().strip()
    result_display = {
        "WIN": "WIN DIRETO",
        "WIN G1": "WIN REC 1",
        "WIN G2": "WIN REC 2",
        "LOSS G1": "LOSS GALE 1",
        "LOSS G2": "LOSS REC 2",
    }.get(result_label, result_label)
    if result_label.startswith("WIN"):
        return (
            f"🏆 MEGA IA • RESULTADO\n"
            f"✅ {result_display}\n"
            f"📊 {body.symbol} • {direction}\n"
            f"🕐 Período: {body.interval}\n"
            f"⏱ Entrada: {_tg_display_time(body.entry_time)}\n"
            f"🌐 Mercado: {market_label}"
        )
    if result_label.startswith("LOSS"):
        return (
            f"📉 MEGA IA • RESULTADO\n"
            f"❌ {result_display}\n"
            f"📊 {body.symbol} • {direction}\n"
            f"🕐 Período: {body.interval}\n"
            f"⏱ Entrada: {_tg_display_time(body.entry_time)}\n"
            f"🌐 Mercado: {market_label}"
        )
    emoji = "🟢" if direction == "CALL" else "🔴" if direction == "PUT" else "⚪"
    # 3.98.26 — linha determinística para um executor externo ler o MESMO sinal
    # publicado no grupo. Não altera gatilho, direção, horário nem estratégia.
    exec_symbol = re.sub(r"[^A-Z0-9]", "", str(body.symbol or "").upper())
    exec_market = str(body.market or "OPEN").upper()
    exec_entry = str(body.entry_time or "")
    exec_expiry = str(body.expiry_time or "")
    exec_id = f"{exec_symbol}:{direction}:{exec_entry}"
    exec_line = f"MEGA_EXEC|v1|{exec_symbol}|{direction}|{exec_entry}|{exec_expiry}|{exec_market}|{exec_id}"
    return (
        f"🚨 MEGA IA • SINAL CONFIRMADO\n"
        f"{emoji} {body.symbol} • {direction}\n"
        f"🎯 Confiança: {float(body.confidence or 0):.0f}%\n"
        f"⏱ Entrada: {_tg_display_time(body.entry_time)}\n"
        f"⌛ Expiração: {_tg_display_time(body.expiry_time)}\n"
        f"🕐 Período: {body.interval}\n"
        f"🌐 Mercado: {market_label}\n"
        f"⚠️ Risco: {str(body.risk or '--').upper()}"
    )


def _tg_session_start() -> None:
    background_bot_state["telegram_session_started_at"] = iso(now())
    background_bot_state["telegram_session_results"] = []


def _tg_session_record(body: TelegramSignalBody) -> None:
    # 3.98.50 — a sessão é definida pelo horário de início, não pelo flag transitório
    # do worker. Assim WIN/LOSS enviados pelo painel também entram no placar final.
    if body.test or not background_bot_state.get("telegram_session_started_at"):
        return
    result = str(body.result or "").upper().strip()
    # 3.98.07 — resultados finais da recuperação também entram na sessão.
    # O placar continua contabilizando apenas WIN x LOSS, mas preserva o rótulo
    # final para WIN REC 1 / WIN REC 2 / LOSS REC 2.
    if result not in ("WIN", "LOSS", "WIN G1", "WIN G2", "LOSS G1", "LOSS G2"):
        return
    rows = background_bot_state.setdefault("telegram_session_results", [])
    key = "|".join([str(body.symbol), str(body.direction).upper(), str(body.entry_time or ""), result])
    if any(str(x.get("key") or "") == key for x in rows if isinstance(x, dict)):
        return
    rows.append({
        "key": key, "symbol": str(body.symbol or "--"),
        "direction": str(body.direction or "NEUTRO").upper(),
        "interval": str(body.interval or "1min"), "entry_time": body.entry_time,
        "result": result, "recorded_at": iso(now()),
    })
    background_bot_state["telegram_session_results"] = rows[-200:]


def _tg_session_summary_text() -> str:
    rows = [x for x in (background_bot_state.get("telegram_session_results") or []) if isinstance(x, dict)]
    started = _tg_display_time(background_bot_state.get("telegram_session_started_at"))
    ended = now().astimezone(BR_TZ).strftime("%H:%M:%S")
    wins = sum(1 for x in rows if str(x.get("result") or "").upper().startswith("WIN"))
    losses = sum(1 for x in rows if str(x.get("result") or "").upper().startswith("LOSS"))
    total = wins + losses
    accuracy = (wins / total * 100.0) if total else 0.0
    lines = ["🏁 MEGA IA • RESULTADO FINAL", f"🕒 Sessão: {started} às {ended}", ""]
    if rows:
        for x in rows:
            win = str(x.get("result") or "").upper().startswith("WIN")
            mark = "✅" if win else "❌"
            color = "🟢" if win else "🔴"
            lines.append(f"{mark} {x.get('symbol') or '--'} — {x.get('result')} {color} • {_tg_display_time(x.get('entry_time'))}")
    else:
        lines.append("⚪ Nenhum resultado WIN/LOSS fechado nesta sessão.")
    lines.extend(["", "📊 PLACAR FINAL", f"🟢 {wins} WIN", f"🔴 {losses} LOSS", "", f"🏆 {wins} × {losses}", f"🎯 Aproveitamento: {accuracy:.1f}%"])
    return "\n".join(lines)


async def _tg_send_session_summary(chat_id: str | None = None) -> dict:
    cid = _tg_chat_id(chat_id or str(background_bot_state.get("chat_id") or "").strip() or None)
    return await _tg_request("sendMessage", {
        "chat_id": cid, "text": _tg_session_summary_text(), "disable_web_page_preview": True,
    })


async def _tg_request(method: str, payload: dict | None = None) -> dict:
    if not TELEGRAM_BOT_TOKEN:
        raise HTTPException(
            503,
            "Telegram não configurado. Defina TELEGRAM_BOT_TOKEN no Render."
        )
    url = f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/{method}"
    try:
        async with httpx.AsyncClient(timeout=TELEGRAM_SEND_TIMEOUT) as client:
            response = await client.post(url, json=payload or {})
        try:
            data = response.json()
        except Exception:
            data = {"ok": False, "description": response.text[:500]}
        if response.status_code >= 400 or not bool(data.get("ok")):
            detail = str(data.get("description") or "Telegram recusou a solicitação.")
            raise HTTPException(response.status_code if response.status_code >= 400 else 502, detail[:300])
        return data
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(502, f"Falha ao comunicar com Telegram: {str(exc)[:220]}")


# MEGA IA 3.98.27 — executor Telegram -> IQ embutido no mesmo Web Service.
# A ordem só é agendada DEPOIS que o Telegram confirma o envio da mensagem ao grupo.
# Usa credenciais próprias via Environment Variables e não interfere no login IQ do painel.
TG_IQ_EXEC_ENABLED = os.getenv("TG_IQ_EXEC_ENABLED", "0").strip().lower() in ("1", "true", "on", "yes")
TG_IQ_EMAIL = os.getenv("TG_IQ_EMAIL", "").strip()
TG_IQ_PASSWORD = os.getenv("TG_IQ_PASSWORD", "")
TG_IQ_ACCOUNT = os.getenv("TG_IQ_ACCOUNT", "PRACTICE").strip().upper()
TG_IQ_AMOUNT = max(1.0, float(os.getenv("TG_IQ_AMOUNT", "2")))
TG_IQ_MAX_LATE_SECONDS = max(2, int(os.getenv("TG_IQ_MAX_LATE_SECONDS", "8")))
_tg_iq_client = None
_tg_iq_lock = threading.RLock()
_tg_iq_scheduled: set[str] = set()


def _tg_iq_parse_dt(value: str | None) -> datetime:
    raw = str(value or "").strip()
    if not raw:
        raise RuntimeError("horário do sinal ausente")
    d = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    if d.tzinfo is None:
        d = d.replace(tzinfo=UTC)
    return d.astimezone(UTC)


def _tg_iq_connect_blocking():
    global _tg_iq_client
    if IQ_Option is None:
        raise RuntimeError("iqoptionapi indisponível")
    with _tg_iq_lock:
        if _tg_iq_client is not None:
            try:
                if _tg_iq_client.check_connect():
                    return _tg_iq_client
            except Exception:
                pass
            try:
                _tg_iq_client.close()
            except Exception:
                pass
            _tg_iq_client = None
        if not TG_IQ_EMAIL or not TG_IQ_PASSWORD:
            raise RuntimeError("configure TG_IQ_EMAIL e TG_IQ_PASSWORD no Render")
        client = IQ_Option(TG_IQ_EMAIL, TG_IQ_PASSWORD)
        result = client.connect()
        ok = bool(result[0]) if isinstance(result, (tuple, list)) and result else bool(result)
        reason = result[1] if isinstance(result, (tuple, list)) and len(result) > 1 else result
        if not ok:
            raise RuntimeError(f"login IQ recusado: {reason}")
        account = "REAL" if TG_IQ_ACCOUNT == "REAL" else "PRACTICE"
        client.change_balance(account)
        _tg_iq_client = client
        return client


def _tg_iq_candidates(symbol: str, market: str) -> list[str]:
    base = re.sub(r"[^A-Z0-9]", "", str(symbol or "").upper())
    if not base:
        return []
    if str(market or "OPEN").upper() == "IQ_OTC":
        return [f"{base}-OTC", f"{base}-OTC-op"]
    return [base]


def _tg_iq_place_blocking(body: TelegramSignalBody) -> tuple[str, Any]:
    entry = _tg_iq_parse_dt(body.entry_time)
    expiry = _tg_iq_parse_dt(body.expiry_time)
    now_utc = datetime.now(UTC)
    late = (now_utc - entry).total_seconds()
    if late > TG_IQ_MAX_LATE_SECONDS:
        raise RuntimeError(f"sinal atrasado {late:.1f}s; entrada bloqueada")
    if expiry <= entry:
        raise RuntimeError("expiração inválida")
    direction = str(body.direction or "").upper()
    if direction not in ("CALL", "PUT"):
        raise RuntimeError("direção inválida")
    action = "call" if direction == "CALL" else "put"
    client = _tg_iq_connect_blocking()
    errors = []
    with _tg_iq_lock:
        for active in _tg_iq_candidates(body.symbol, body.market):
            try:
                raw = getattr(client, "buy_by_raw_expirations", None)
                if callable(raw):
                    result = raw(TG_IQ_AMOUNT, active, action, int(expiry.timestamp()))
                else:
                    mins = max(1, int(round((expiry - entry).total_seconds() / 60.0)))
                    result = client.buy(TG_IQ_AMOUNT, active, action, mins)
                if isinstance(result, (tuple, list)) and len(result) >= 2:
                    ok, order_id = bool(result[0]), result[1]
                else:
                    ok, order_id = bool(result), result
                if ok:
                    return active, order_id
                errors.append(f"{active}: {result}")
            except Exception as exc:
                errors.append(f"{active}: {exc}")
    raise RuntimeError(" | ".join(errors[-3:]) or "IQ recusou a ordem")


async def _tg_iq_execute_after_group(body: TelegramSignalBody) -> None:
    key = "|".join([str(body.symbol), str(body.direction), str(body.entry_time), str(body.market)])
    if key in _tg_iq_scheduled:
        return
    _tg_iq_scheduled.add(key)
    try:
        entry = _tg_iq_parse_dt(body.entry_time)
        wait = (entry - datetime.now(UTC)).total_seconds()
        if wait > 0:
            await asyncio.sleep(wait)
        active, order_id = await asyncio.to_thread(_tg_iq_place_blocking, body)
        print(f"[TG→IQ OK] {active} {str(body.direction).upper()} valor={TG_IQ_AMOUNT:.2f} conta={TG_IQ_ACCOUNT} ordem={order_id}", flush=True)
    except Exception as exc:
        print(f"[TG→IQ BLOQUEADO] {body.symbol} {body.direction}: {exc}", flush=True)
    finally:
        # mantém dedupe por algumas horas sem crescimento ilimitado
        if len(_tg_iq_scheduled) > 1000:
            _tg_iq_scheduled.clear()


def _tg_iq_schedule_after_group(body: TelegramSignalBody) -> None:
    if not TG_IQ_EXEC_ENABLED or body.test or body.result:
        return
    if str(body.direction or "").upper() not in ("CALL", "PUT"):
        return
    asyncio.create_task(_tg_iq_execute_after_group(body), name="telegram-iq-order")


async def _tg_send(body: TelegramSignalBody) -> dict:
    chat_id = _tg_chat_id(body.chat_id)
    dedupe_key = None
    if not body.test:
        # 3.98.48 — browser e bot 24h podem representar o mesmo minuto com
        # ISO diferente (Z, +00:00, milissegundos). Normaliza a entrada para
        # impedir que a mesma operação seja publicada duas vezes no grupo.
        try:
            entry_key = str(int(_tg_iq_parse_dt(body.entry_time).timestamp())) if body.entry_time else ""
        except Exception:
            entry_key = str(body.entry_time or "")
        symbol_key = str(body.symbol or "").upper().replace("/", "").replace("-", "").replace("_", "")
        dedupe_key = "|".join([
            chat_id,
            symbol_key,
            str(body.direction).upper(),
            entry_key,
            str(body.result or "SIGNAL").upper(),
        ])
        now_ts = time.time()
        for k, ts in list(telegram_sent_cache.items()):
            if now_ts - ts > 21600:
                telegram_sent_cache.pop(k, None)
        if dedupe_key in telegram_sent_cache:
            return {"ok": True, "duplicate": True, "message_id": None, "chat_id": chat_id}

    data = await _tg_request("sendMessage", {
        "chat_id": chat_id,
        "text": _tg_signal_text(body),
        "disable_web_page_preview": True,
    })
    # Só agenda a IQ depois que o Telegram confirmou que a mensagem caiu no grupo.
    _tg_iq_schedule_after_group(body)
    result = data.get("result") or {}
    if dedupe_key:
        telegram_sent_cache[dedupe_key] = time.time()
    _tg_session_record(body)
    return {
        "ok": True,
        "duplicate": False,
        "message_id": result.get("message_id"),
        "chat_id": str((result.get("chat") or {}).get("id") or chat_id),
    }


@app.post("/rtm-ea-signal")
async def rtm_ea_signal(request: Request, body: RTMEAExternalSignalBody):
    """Recebe CALL/PUT do RTM MULTI EA rodando no MetaTrader 4."""
    global rtm_ea_last_receive_at
    if RTM_EA_SECRET:
        supplied = str(request.headers.get("X-Mega-License") or "").strip()
        if supplied != RTM_EA_SECRET:
            raise HTTPException(401, "Chave do RTM EA inválida.")
    direction = str(body.direction or "NEUTRO").upper().strip()
    if direction not in ("CALL", "PUT"):
        raise HTTPException(400, "direction deve ser CALL ou PUT.")
    symbol = _rtm_ea_symbol(body.symbol)
    interval = _rtm_ea_interval(body.timeframe)
    if interval not in INTERVALS:
        raise HTTPException(400, "Timeframe do RTM EA não suportado pelo app.")
    if not _symbol_allowed(symbol, "OPEN"):
        raise HTTPException(400, f"Ativo do RTM EA não permitido: {symbol}")
    confidence = max(0.0, min(99.0, float(body.confidence or 0.0)))
    expiry_seconds = max(60, min(86400, int(body.expiry_seconds or 60)))
    prealert_seconds = max(0, min(300, int(body.prealert_seconds or 0)))
    entry_dt = next_boundary(interval)
    expiry_dt = entry_dt + timedelta(seconds=expiry_seconds)
    received_at = now()
    payload = {
        "symbol": symbol, "interval": interval, "market": "OPEN",
        "direction": direction, "confidence": round(confidence, 1),
        "entry_time": iso(entry_dt), "announce_time": iso(received_at), "expiry_time": iso(expiry_dt),
        "expiry_seconds": expiry_seconds, "prealert_seconds": prealert_seconds,
        "strategy": "RTM MULTI EA", "mode": "RTM_EXTERNAL_MT4",
        "selected_engine": "RTM", "engine": str(body.engine or "RTM_MULTI_INDEPENDENT"),
        "status": "RTM MULTI EA • SINAL RECEBIDO • ENTRADA NA PRÓXIMA VELA",
        "risk": "MEDIUM", "reason": str(body.reasons or "RTM por gatilho individual do EA")[:800],
        "source_state": "READY", "feed_source": "MT4_EA", "external_ea": True,
        "external_source": str(body.source or "MT4_EA"),
        "buy_score": int(body.buy_score or 0), "sell_score": int(body.sell_score or 0),
        "total_votes": int(body.total_votes or 0), "signal_price": body.price,
        "direct_win_only": True, "gale_signal": False, "_received_ts": time.time(),
    }
    key = _rtm_ea_key(symbol, interval)
    with rtm_ea_signal_guard:
        rtm_ea_signals[key] = payload
    rtm_ea_last_receive_at = iso(received_at)
    public = dict(payload)
    public.pop("_received_ts", None)
    return {"ok": True, "stored": True, "signal": public}


