@app.get("/telegram-chats")
async def telegram_chats():
    """Lista grupos/supergrupos/canais vistos recentemente pelo bot.

    Para o grupo aparecer, adicione o bot ao grupo e envie /start ou /id no grupo.
    """
    data = await _tg_request("getUpdates", {"limit": 100, "timeout": 0})
    chats: dict[str, dict] = {}
    for upd in data.get("result") or []:
        if not isinstance(upd, dict):
            continue
        msg = (
            upd.get("message")
            or upd.get("edited_message")
            or upd.get("channel_post")
            or upd.get("edited_channel_post")
        )
        if not isinstance(msg, dict):
            continue
        chat = msg.get("chat") or {}
        chat_id = chat.get("id")
        if chat_id is None:
            continue
        chat_type = str(chat.get("type") or "")
        if chat_type not in ("group", "supergroup", "channel"):
            continue
        title = str(chat.get("title") or chat.get("username") or f"Grupo {chat_id}")
        chats[str(chat_id)] = {
            "chat_id": str(chat_id),
            "title": title,
            "type": chat_type,
            "username": chat.get("username"),
        }
    return {"ok": True, "chats": list(chats.values())}


@app.post("/telegram-send")
async def telegram_send(body: TelegramSignalBody):
    direction = str(body.direction or "NEUTRO").upper()
    result_label = str(body.result or "").upper().strip()
    if not body.test:
        # Trava no servidor: o botão OFF do painel precisa impedir qualquer
        # envio automático, mesmo se algum JavaScript antigo ainda tentar chamar.
        if not bool(background_bot_state.get("telegram_enabled")):
            raise HTTPException(409, "Telegram automático está OFF no painel.")
        if result_label:
            # 3.98.04 — aceita somente DESFECHOS finais da sequência.
            # LOSS intermediário não chega aqui; REC1/REC2 usam os próximos sinais reais.
            if result_label not in ("WIN", "WIN G1", "WIN G2", "LOSS G1", "LOSS G2"):
                raise HTTPException(400, "Somente resultados finais WIN DIRETO/WIN REC 1/WIN REC 2/LOSS REC 2 podem ser enviados automaticamente ao Telegram.")
        elif direction not in ("CALL", "PUT"):
            raise HTTPException(400, "Somente sinais CALL ou PUT confirmados podem ser enviados.")
    return await _tg_send(body)


