async def _background_settle_trade(trade: Dict[str, Any]) -> tuple[str | None, Dict[str, Any] | None, Dict[str, Any] | None]:
    """Fecha somente a primeira vela do sinal; retorna WIN/LOSS/DRAW ou None."""
    market = str(trade.get("market") or "OPEN").upper()
    symbol = str(trade.get("symbol") or "")
    interval = str(trade.get("interval") or "1min")
    direction = str(trade.get("direction") or "").upper()
    if interval not in INTERVALS or direction not in ("CALL", "PUT"):
        return "LOSS", None, None
    try:
        expiry_dt = parse_dt(str(trade.get("expiry_time") or ""))
        entry_dt = parse_dt(str(trade.get("entry_time") or ""))
    except Exception:
        return "LOSS", None, None
    if now() < expiry_dt + timedelta(seconds=2):
        return None, None, None

    iq_state = None
    rows = []
    try:
        if market == "IQ_OTC":
            iq_state = _background_active_iq_state()
            if not iq_state:
                return None, None, None
            rows = await iq_ea_candles(iq_state, symbol, interval, 100, regular_market=False)
        else:
            rows = await candles(symbol, interval, 100, "OPEN", None, request=None)
    except Exception:
        rows = []

    candle, _, _ = _nearest_candle_for_time(rows, entry_dt, INTERVALS[interval])
    if candle is None and market == "OPEN":
        try:
            exact = await _fetch_open_result_window(symbol, interval, entry_dt)
            candle, _, _ = _nearest_candle_for_time(exact, entry_dt, INTERVALS[interval])
        except Exception:
            candle = None
    if candle is None:
        return None, None, iq_state

    try:
        op = float(candle.get("open"))
        cl = float(candle.get("close"))
    except Exception:
        return None, None, iq_state
    if cl == op:
        result_label = "DRAW"
    else:
        won = (direction == "CALL" and cl > op) or (direction == "PUT" and cl < op)
        result_label = "WIN" if won else "LOSS"
    return result_label, candle, iq_state


async def _background_settle_pending() -> None:
    pending = list(background_bot_state.get("pending_trades") or [])
    if not pending:
        return
    keep = []
    changed = False
    for trade in pending[:80]:
        try:
            result_label, candle, iq_state = await _background_settle_trade(trade)
            if not result_label:
                keep.append(trade)
                continue
            # 3.98.15 — contabiliza PRIMEIRO. Uma falha temporária do Telegram
            # nunca pode impedir WIN/LOSS de entrar no placar/histórico.
            _background_accounting_finish(trade, result_label, candle, iq_state)

            # Telegram atual só aceita WIN/LOSS. Empate é contabilizado, mas não
            # dispara mensagem de perda falsa.
            if (
                result_label in ("WIN", "LOSS")
                and bool(background_bot_state.get("telegram_enabled"))
                and bool(trade.get("telegram_notify", True))
            ):
                try:
                    await _background_send_result(trade, result_label)
                except Exception as exc:
                    # Resultado já ficou salvo; registra somente a falha de notificação.
                    background_bot_state["last_error"] = f"resultado Telegram: {str(exc)[:160]}"
            _release_ai_asset_cycle_lock(
                str(trade.get("market") or "OPEN").upper(),
                str(trade.get("symbol") or ""),
                str(trade.get("interval") or "1min"),
                str(trade.get("direction") or "").upper(),
                str(trade.get("expiry_time") or ""),
                str(trade.get("engine") or ""),
            )
            background_bot_state["last_result"] = {
                "symbol": trade.get("symbol"),
                "direction": trade.get("direction"),
                "result": result_label,
                "entry_time": trade.get("entry_time"),
                "finished_at": iso(now()),
            }
            print(
                f"[BG RESULT] {trade.get('symbol')} {trade.get('interval')} "
                f"{trade.get('direction')} -> {result_label}",
                flush=True,
            )
            changed = True
        except HTTPException as exc:
            # Telegram/fonte temporariamente indisponível: mantém a operação para retry.
            trade["last_error"] = str(exc.detail)[:180]
            keep.append(trade)
        except Exception as exc:
            trade["last_error"] = str(exc)[:180]
            keep.append(trade)
    if len(pending) > 80:
        keep.extend(pending[80:])
    background_bot_state["pending_trades"] = keep
    if changed:
        _background_save_state()


async def _background_bot_loop() -> None:
    """Fila contínua de sinais. Não depende de JavaScript nem da tela aberta."""
    print(
        f"[BG BOT] iniciado • ciclo={BACKGROUND_SCAN_SECONDS:.0f}s • "
        f"engine={background_bot_state.get('engine')} • enabled={background_bot_state.get('enabled')}",
        flush=True,
    )
    while True:
        try:
            await _background_settle_pending()
            if not bool(background_bot_state.get("enabled")):
                background_bot_state["status"] = "OFFLINE • SERVIDOR AGUARDANDO"
                await asyncio.sleep(max(5.0, BACKGROUND_SCAN_SECONDS))
                continue

            # 3.96.95 — a análise 24h não depende mais da tela nem do Telegram.
            # Com Telegram OFF o servidor continua analisando/contabilizando; apenas
            # o envio das mensagens fica bloqueado em _background_send_signal/result.
            if not bool(background_bot_state.get("telegram_enabled")):
                current_engine = str(background_bot_state.get("engine") or "SCALPINGM1").upper()
                background_bot_state["status"] = f"ONLINE • {current_engine} • SERVIDOR 24H • TELEGRAM OFF"

            engine = "SCALPINGM1"
            background_bot_state["engine"] = engine
            market = str(background_bot_state.get("market") or "OPEN").upper()
            interval = str(background_bot_state.get("interval") or "1min")
            if engine not in _BACKGROUND_ENGINES or market not in VALID_MARKETS or interval not in INTERVALS:
                background_bot_state["status"] = "CONFIGURAÇÃO INVÁLIDA"
                await asyncio.sleep(10)
                continue
            # Telegram só é pré-requisito quando o envio de mensagens estiver ON.
            # A análise/contabilização 24h continua funcionando com Telegram OFF.
            if bool(background_bot_state.get("telegram_enabled")):
                if not TELEGRAM_BOT_TOKEN:
                    background_bot_state["status"] = "AGUARDANDO TELEGRAM_BOT_TOKEN"
                    await asyncio.sleep(15)
                    continue
                if not (str(background_bot_state.get("chat_id") or "").strip() or TELEGRAM_CHAT_ID):
                    background_bot_state["status"] = "AGUARDANDO CHAT ID DO TELEGRAM"
                    await asyncio.sleep(15)
                    continue

            iq_state = None
            if market == "IQ_OTC":
                iq_state = _background_active_iq_state()
                if not iq_state:
                    background_bot_state["status"] = "IQ OPTION OFFLINE • AGUARDANDO LOGIN"
                    await asyncio.sleep(10)
                    continue

            scan_symbols = _background_symbols_for_state()
            if not scan_symbols:
                background_bot_state["status"] = "SEM ATIVOS PARA ANALISAR"
                await asyncio.sleep(10)
                continue

            idx = int(background_bot_state.get("scan_index") or 0) % len(scan_symbols)
            symbol = scan_symbols[idx]
            background_bot_state["scan_index"] = (idx + 1) % len(scan_symbols)
            background_bot_state["last_symbol"] = symbol
            background_bot_state["last_scan_at"] = iso(now())
            background_bot_state["status"] = f"ONLINE • {engine} • {market} • FILA ATIVA"

            payload = await signal(
                symbol,
                interval,
                market,
                iq_state=iq_state,
                request=None,
                ai_only=True,
                engine=engine,
                entry_mode="BIRTH",
                robofibo_poc=bool(background_bot_state.get("robofibo_poc")),
            )
            if isinstance(payload, dict):
                payload["market"] = market
                payload["selected_engine"] = engine
                direction = str(payload.get("direction") or "NEUTRO").upper()
                if direction in ("CALL", "PUT") and payload.get("entry_time") and payload.get("expiry_time"):
                    sig_key = _background_signal_key(payload)
                    sent = list(background_bot_state.get("sent_signal_keys") or [])
                    if sig_key and sig_key not in sent:
                        await _background_send_signal(payload)
                        trade = {
                            "key": sig_key,
                            "engine": engine,
                            "market": market,
                            "symbol": symbol,
                            "interval": interval,
                            "direction": direction,
                            "confidence": float(payload.get("confidence") or 0.0),
                            "risk": str(payload.get("risk") or "--"),
                            "strategy": str(payload.get("strategy") or engine),
                            "direct_only": True,  # 3.96.7: fila 24h também fecha na primeira vela.
                            "trigger_indicator": payload.get("trigger_indicator") or ((payload.get("rtm_individual") or {}).get("trigger_indicator") if isinstance(payload.get("rtm_individual"), dict) else None),
                            "trigger_score": payload.get("trigger_score") if payload.get("trigger_score") is not None else (((payload.get("rtm_individual") or {}).get("trigger_score")) if isinstance(payload.get("rtm_individual"), dict) else None),
                            "telegram_notify": True,
                            "entry_time": payload.get("entry_time"),
                            "expiry_time": payload.get("expiry_time"),
                            "sent_at": iso(now()),
                        }
                        background_bot_state.setdefault("pending_trades", []).append(trade)
                        background_bot_state["pending_trades"] = background_bot_state["pending_trades"][-80:]
                        sent.append(sig_key)
                        background_bot_state["sent_signal_keys"] = sent[-240:]
                        background_bot_state["last_signal"] = dict(trade)
                        _background_accounting_remember(payload, iq_state)
                        _background_save_state()
                        print(
                            f"[BG SIGNAL] {engine} {symbol} {interval} {direction} "
                            f"entrada={payload.get('entry_time')}",
                            flush=True,
                        )
            background_bot_state["last_error"] = ""
        except asyncio.CancelledError:
            raise
        except HTTPException as exc:
            background_bot_state["last_error"] = str(exc.detail)[:220]
            background_bot_state["status"] = "ONLINE • AGUARDANDO FONTE"
        except Exception as exc:
            background_bot_state["last_error"] = str(exc)[:220]
            background_bot_state["status"] = "ONLINE • RECONECTANDO"
        await asyncio.sleep(BACKGROUND_SCAN_SECONDS)


@app.get("/background-bot/state")
async def background_bot_get_state():
    return {"ok": True, **_background_state_snapshot()}


@app.post("/background-bot/state")
async def background_bot_set_state(body: BackgroundBotStateBody):
    """Atualiza o bot 24h sem deixar a navegação do painel trocar o motor.

    Regras:
    - PASSIVE: só pode atualizar chat_id; não troca engine e não liga/desliga.
    - ACTIVATE_ENGINE: clique explícito ONLINE; trava engine + mercado + intervalo.
    - DEACTIVATE_ENGINE: clique explícito OFFLINE; só desliga se for o mesmo engine.
    - TELEGRAM_TOGGLE: liga/desliga a execução mantendo o engine já travado.
    """
    action = str(body.action or "PASSIVE").strip().upper()
    requested_engine = str(body.engine or "ALPHAX").upper()
    market = str(body.market or "OPEN").upper()
    interval = str(body.interval or "1min")

    if requested_engine not in _BACKGROUND_ENGINES:
        requested_engine = "SCALPINGM1"
    if market not in VALID_MARKETS:
        raise HTTPException(400, "Mercado de segundo plano inválido.")
    if interval not in INTERVALS:
        raise HTTPException(400, "Intervalo de segundo plano inválido.")

    symbols = []
    if requested_engine == "RTM":
        symbols = _rtm_scan_symbols(market, [str(x or "").upper().strip() for x in (body.symbols or [])]) if body.symbols else []
    else:
        allowed = SYMBOLS if market == "OPEN" else OTC_SYMBOLS
        for raw in body.symbols or []:
            sym = str(raw or "").upper().strip()
            if sym in allowed and sym not in symbols:
                symbols.append(sym)

    async with background_bot_lock:
        chat = str(body.chat_id or "").strip()
        if chat:
            background_bot_state["chat_id"] = chat
        if body.robofibo_poc is not None:
            background_bot_state["robofibo_poc"] = bool(body.robofibo_poc)

        if action == "ACTIVATE_ENGINE":
            tg_on = bool(background_bot_state.get("telegram_enabled"))
            old_engine = str(background_bot_state.get("engine") or "").upper()
            old_market = str(background_bot_state.get("market") or "").upper()
            old_symbols = [str(x).upper() for x in (background_bot_state.get("symbols") or [])]
            scope_changed = (old_engine != requested_engine or old_market != market or old_symbols != symbols)
            if scope_changed:
                # Não carregar operações/sinais de motores ou pares antigos para o novo motor.
                background_bot_state["pending_trades"] = []
                background_bot_state["sent_signal_keys"] = []
                background_bot_state["last_signal"] = None
                background_bot_state["last_result"] = None
            background_bot_state.update({
                "enabled": True,
                "engine": requested_engine,
                "market": market,
                "interval": interval,
                "symbols": symbols,
                "status": (
                    f"ONLINE • {requested_engine} • {market} • FILA ATIVA"
                    if tg_on else f"ONLINE • {requested_engine} • TELEGRAM OFF"
                ),
                "last_error": "",
            })
            print(
                f"[BG CONTROL] motor ativado explicitamente: "
                f"{requested_engine} • {market} • {interval}",
                flush=True,
            )

        elif action == "DEACTIVATE_ENGINE":
            current_engine = str(background_bot_state.get("engine") or "").upper()
            if current_engine == requested_engine:
                background_bot_state["enabled"] = False
                background_bot_state["status"] = "OFFLINE • SERVIDOR AGUARDANDO"
                background_bot_state["last_error"] = ""
                print(
                    f"[BG CONTROL] motor desativado explicitamente: {requested_engine}",
                    flush=True,
                )

        elif action == "TELEGRAM_TOGGLE":
            if body.telegram_enabled is None:
                raise HTTPException(400, "Informe telegram_enabled no botão Telegram.")

            tg_on = bool(body.telegram_enabled)
            was_on = bool(background_bot_state.get("telegram_enabled"))
            # 3.98.15 — ao apertar OFF, primeiro tenta fechar todas as operações
            # cuja expiração já passou. Só depois monta o placar final da sessão.
            # Antes o resumo podia sair 0x0 mesmo havendo sinais já expirados.
            if was_on and not tg_on:
                try:
                    await _background_settle_pending()
                except Exception as exc:
                    background_bot_state["last_error"] = f"fechamento antes do placar: {str(exc)[:160]}"
                try:
                    await _tg_send_session_summary(str(background_bot_state.get("chat_id") or "").strip() or None)
                except Exception as exc:
                    # O OFF continua funcionando mesmo se o Telegram estiver temporariamente indisponível.
                    background_bot_state["last_error"] = f"placar Telegram: {str(exc)[:160]}"
                finally:
                    # Fecha formalmente a sessão somente DEPOIS de montar/enviar o placar.
                    background_bot_state["telegram_session_started_at"] = None
            background_bot_state["telegram_enabled"] = tg_on
            if tg_on and not was_on:
                _tg_session_start()
            current_engine = str(background_bot_state.get("engine") or BACKGROUND_DEFAULT_ENGINE).upper()
            if current_engine not in _BACKGROUND_ENGINES:
                current_engine = "SCALPINGM1"
                background_bot_state["engine"] = current_engine

            if not tg_on:
                # Operações já abertas podem continuar sendo contabilizadas, mas
                # nunca devem mandar WIN/LOSS depois que o usuário apertou OFF.
                for trade in background_bot_state.get("pending_trades") or []:
                    if isinstance(trade, dict):
                        trade["telegram_notify"] = False
                if bool(background_bot_state.get("enabled")):
                    background_bot_state["status"] = f"ONLINE • {current_engine} • TELEGRAM OFF"
                else:
                    background_bot_state["status"] = "OFFLINE • TELEGRAM OFF"
            else:
                if bool(background_bot_state.get("enabled")):
                    background_bot_state["status"] = (
                        f"ONLINE • {current_engine} • "
                        f"{background_bot_state.get('market') or 'OPEN'} • FILA ATIVA"
                    )
                else:
                    background_bot_state["status"] = "OFFLINE • MOTOR DESLIGADO"
            background_bot_state["last_error"] = ""

        elif action == "PASSIVE":
            # 3.98.37 — mantém o motor travado, mas o ESCOPO acompanha o ativo
            # atualmente selecionado no painel. Assim o bot 24h nunca continua
            # varrendo ETH/DOGE/Forex quando o usuário está em BTC/USD (ou vice-versa).
            old_symbols = [str(x).upper() for x in (background_bot_state.get("symbols") or [])]
            if symbols and old_symbols != symbols:
                background_bot_state["symbols"] = symbols
                background_bot_state["scan_index"] = 0
                # Descarta somente pendências de outros ativos para que não apareçam
                # depois como resultados novos no painel/Telegram.
                background_bot_state["pending_trades"] = [
                    t for t in (background_bot_state.get("pending_trades") or [])
                    if str((t or {}).get("symbol") or "").upper() in symbols
                ]
                background_bot_state["last_signal"] = None
                background_bot_state["last_result"] = None
                background_bot_state["sent_signal_keys"] = [
                    k for k in (background_bot_state.get("sent_signal_keys") or [])
                    if any(f"|{sym}|" in str(k) for sym in symbols)
                ]
            background_bot_state["interval"] = interval

        else:
            raise HTTPException(400, "Ação de segundo plano inválida.")

        _background_save_state()

    return {"ok": True, **_background_state_snapshot()}


_background_load_state()



def _engine_moment_features(rows):
    """Extrai somente características do preço para estudar qual motor combina melhor AGORA.

    Este estudo NÃO usa resultados anteriores, não abre operação e não representa
    probabilidade garantida de WIN. Ele mede compatibilidade entre o regime atual
    do mercado e o tipo de leitura de cada motor.
    """
    rows = list(rows or [])
    if len(rows) < 30:
        return None

    def f(v, default=0.0):
        try:
            return float(v)
        except Exception:
            return default

    recent = rows[-30:]
    closes = [f(x.get("close")) for x in recent]
    opens = [f(x.get("open")) for x in recent]
    highs = [f(x.get("high")) for x in recent]
    lows = [f(x.get("low")) for x in recent]
    volumes = [max(0.0, f(x.get("volume"))) for x in recent]

    ranges = [max(h-l, 1e-12) for h,l in zip(highs,lows)]
    bodies = [abs(c-o) for o,c in zip(opens,closes)]
    body_ratios = [min(1.0, b/r) for b,r in zip(bodies,ranges)]

    short = closes[-9:]
    moves = [short[i]-short[i-1] for i in range(1,len(short))]
    travel = sum(abs(x) for x in moves)
    efficiency = abs(short[-1]-short[0]) / max(travel, 1e-12)
    signs = [1 if x>0 else (-1 if x<0 else 0) for x in moves]
    nz = [x for x in signs if x]
    flips = sum(1 for a,b in zip(nz,nz[1:]) if a!=b)
    flip_ratio = flips / max(len(nz)-1, 1)
    directional_consistency = abs(sum(nz[-6:])) / max(len(nz[-6:]), 1)

    avg_range = sum(ranges[-21:-1]) / max(len(ranges[-21:-1]),1)
    range_ratio = ranges[-1] / max(avg_range,1e-12)
    avg_body_ratio = sum(body_ratios[-6:]) / max(len(body_ratios[-6:]),1)
    last_body_ratio = body_ratios[-1]

    last_o,last_h,last_l,last_c = opens[-1],highs[-1],lows[-1],closes[-1]
    last_rng=max(last_h-last_l,1e-12)
    upper_wick=(last_h-max(last_o,last_c))/last_rng
    lower_wick=(min(last_o,last_c)-last_l)/last_rng
    rejection=min(1.0,max(upper_wick,lower_wick)*2.2)

    short_move=closes[-1]-closes[-6]
    medium_move=closes[-1]-closes[-20]
    short_dir=1 if short_move>0 else (-1 if short_move<0 else 0)
    medium_dir=1 if medium_move>0 else (-1 if medium_move<0 else 0)
    alignment = 1.0 if short_dir and short_dir==medium_dir else (0.45 if short_dir==0 or medium_dir==0 else 0.0)

    hi20=max(highs[-20:]); lo20=min(lows[-20:])
    pos20=(closes[-1]-lo20)/max(hi20-lo20,1e-12)
    near_edge=min(1.0,abs(pos20-0.5)*2.0)

    nonzero_vol=[v for v in volumes[-21:-1] if v>0]
    if nonzero_vol and volumes[-1]>0:
        avg_vol=sum(nonzero_vol)/len(nonzero_vol)
        volume_expansion=min(1.0,volumes[-1]/max(avg_vol,1e-12)/1.5)
    else:
        volume_expansion=0.5

    choppy = flip_ratio >= 0.62 and efficiency <= 0.38
    impulse = last_body_ratio >= 0.58 and range_ratio >= 1.12
    trending = efficiency >= 0.52 and directional_consistency >= 0.55 and alignment >= 0.75

    if choppy:
        regime="LATERAL / RUIDOSO"
    elif impulse and trending:
        regime="IMPULSO COM TENDÊNCIA"
    elif impulse:
        regime="IMPULSO / EXPANSÃO"
    elif trending:
        regime="TENDÊNCIA ORGANIZADA"
    else:
        regime="TRANSIÇÃO / MISTO"

    return {
        "efficiency":clamp(efficiency,0,1),
        "flip_ratio":clamp(flip_ratio,0,1),
        "directional_consistency":clamp(directional_consistency,0,1),
        "range_ratio":max(0.0,range_ratio),
        "avg_body_ratio":clamp(avg_body_ratio,0,1),
        "last_body_ratio":clamp(last_body_ratio,0,1),
        "rejection":clamp(rejection,0,1),
        "alignment":clamp(alignment,0,1),
        "near_edge":clamp(near_edge,0,1),
        "volume_expansion":clamp(volume_expansion,0,1),
        "choppy":bool(choppy),
        "impulse":bool(impulse),
        "trending":bool(trending),
        "regime":regime,
    }


def _engine_moment_scores(features, market="OPEN", iq_ready=False):
    if not features:
        return []
    f=features
    clean=1.0-f["flip_ratio"]
    rr_quality=clamp(f["range_ratio"]/1.35,0,1)
    not_choppy=0.0 if f["choppy"] else 1.0

    local = clamp(
        32 + 18*not_choppy + 14*clean + 14*f["efficiency"] +
        9*f["alignment"] + 8*f["directional_consistency"] + 5*rr_quality, 0, 100
    )
    master = clamp(
        30 + 16*not_choppy + 13*clean + 13*f["efficiency"] +
        10*f["alignment"] + 9*f["directional_consistency"] + 5*f["rejection"] +
        4*f["near_edge"] + 4*f["volume_expansion"] + 4*rr_quality, 0, 100
    )
    smart = clamp(
        36 + 16*not_choppy + 14*clean + 12*f["efficiency"] +
        10*f["avg_body_ratio"] + 7*f["alignment"] + 5*rr_quality, 0, 100
    )
    autonomous = clamp(
        24 + 24*f["alignment"] + 20*f["efficiency"] +
        17*f["directional_consistency"] + 9*f["avg_body_ratio"] +
        8*rr_quality - (14 if f["choppy"] else 0), 0, 100
    )
    force = clamp(
        17 + 30*f["last_body_ratio"] + 24*rr_quality +
        16*f["directional_consistency"] + 9*f["alignment"] +
        7*f["volume_expansion"] - 14*f["flip_ratio"], 0, 100
    )
    rsi5 = clamp(
        24 + 22*f["rejection"] + 16*f["near_edge"] +
        14*f["avg_body_ratio"] + 10*f["volume_expansion"] +
        8*f["directional_consistency"] + 6*(1.0-f["flip_ratio"]), 0, 100
    )

    ai_ready=bool(OAI_KEY)
    defs=[
        {
            "key":"LOCALANALYST","name":"MEGA BOT","score":local,
            "supported":market in VALID_MARKETS,"operational":market in VALID_MARKETS,
            "reason": "Leitura local multi-camada equilibrada: price action, estrutura, tendência, momentum, rejeição, rompimento, S/R, volatilidade e confirmações técnicas."
        },
        {
            "key":"LOCALANALYSTFLEX","name":"MEGA BOT FLEX","score":local,
            "supported":market in VALID_MARKETS,"operational":market in VALID_MARKETS,
            "reason": "Mesma leitura multi-camada do Mega Bot, com limiares de liberação levemente mais soltos e as travas principais preservadas."
        },
        {
            "key":"MEGAMASTER","name":"MEGA MASTER","score":master,
            "supported":market in VALID_MARKETS,"operational":market in VALID_MARKETS,
            "reason": "Leitura local ampliada: tendência curta e macro, estrutura, price action, S/R, rompimento/falso rompimento, pullback, momentum, divergência, Fibonacci, Stochastic, ATR, Bollinger, volume e pressão de candles."
        },
        {
            "key":"SMART","name":"MOTOR REMOVIDO","score":smart,
            "supported":market in VALID_MARKETS,"operational":market in VALID_MARKETS and ai_ready,
            "reason": "ChatGPT analisa os candles diretamente e decide CALL/PUT/NEUTRO com decisão nativa do modelo."
        },
    ]
    if not ai_ready:
        for x in defs:
            if x["key"]=="SMART":
                x["operational"]=False
                x["reason"]="A IA externa não está configurada/disponível no servidor neste momento."
    for x in defs:
        x["score"]=round(float(x["score"]),1)
        if not x["supported"]:
            x["status"]="NÃO DISPONÍVEL NESTE MERCADO"
        elif not x["operational"]:
            x["status"]="INDISPONÍVEL PARA OPERAR AGORA"
        elif x["score"]>=78:
            x["status"]="COMPATIBILIDADE ALTA"
        elif x["score"]>=62:
            x["status"]="COMPATIBILIDADE BOA"
        elif x["score"]>=48:
            x["status"]="COMPATIBILIDADE MODERADA"
        else:
            x["status"]="COMPATIBILIDADE BAIXA"
    return defs


@app.get("/engine-study")
async def engine_study(request: Request, symbol: str="EUR/USD", interval: str="1min", market: str="OPEN"):
    market=(market or "OPEN").upper()
    if not _symbol_allowed(symbol, market) or interval not in INTERVALS or market not in VALID_MARKETS:
        raise HTTPException(400,"Ativo, intervalo ou mercado inválido.")

    iq_state=_iq_session_state(request, required=False)
    iq_ready=bool(iq_state and _iq_connected(iq_state))

    if market=="IQ_OTC":
        if not iq_state:
            raise HTTPException(401,"Conecte a IQ Option para estudar o mercado OTC.")
        raw=await iq_ea_candles(iq_state,symbol,interval,150,regular_market=False)
        source="IQ_OPTION_OTC"
    else:
        raw=await candles(symbol,interval,150,"OPEN",None,request=request)
        source=_feed_source_from_rows(raw)

    closed=list(raw[:-1] if len(raw)>1 else raw)
    features=_engine_moment_features(closed)
    if not features:
        raise HTTPException(503,"Ainda não há candles fechados suficientes para o estudo de momento.")

    engines=_engine_moment_scores(features,market=market,iq_ready=iq_ready)
    engines=[x for x in engines if str(x.get("key") or "").upper() not in RETIRED_ENGINES]
    candidates=[x for x in engines if x.get("supported") and x.get("operational")]
    candidates.sort(key=lambda x:float(x.get("score",0)),reverse=True)
    leader=candidates[0] if candidates else None
    threshold=58.0

    if leader and float(leader.get("score",0))>=threshold:
        decision="MOTOR MAIS COMPATÍVEL AGORA"
        recommendation=leader.get("key")
        summary=f"{leader.get('name')} apresenta o maior encaixe com o regime atual ({leader.get('score'):.1f}% de compatibilidade)."
    elif leader:
        decision="MOMENTO SEM ENCAIXE FORTE"
        recommendation=None
        summary=f"Nenhum motor operacional passou do nível mínimo de compatibilidade agora. Maior leitura: {leader.get('name')} {leader.get('score'):.1f}%."
    else:
        decision="SEM MOTOR OPERACIONAL"
        recommendation=None
        summary="Nenhum motor compatível está operacional neste mercado agora."

    return {
        "ok":True,
        "study_type":"CURRENT_MARKET_COMPATIBILITY",
        "symbol":symbol,"interval":interval,"market":market,
        "source":source,"candles_used":len(closed),
        "market_regime":features.get("regime"),
        "decision":decision,
        "recommended_engine":recommendation,
        "summary":summary,
        "engines":engines,
        "updated_at":iso(now()),
        "notice":"Compatibilidade com o momento atual; não é taxa de acerto nem garantia de WIN. Nenhuma operação é aberta por este estudo.",
    }


