def paul_macd_strategy(cs, symbol="EUR/USD", timeframe="1min", market="OPEN"):
    """Paul MACD adaptado: MACD 10/20/7 no M1 e confirmação de direção no M5.
    Remove grade/reentrada/lote do EA. Usa apenas candles fechados e entra na próxima M1.
    """
    rows=list(cs or [])[-320:]
    base={"available":True,"direction":"NEUTRO","confidence":0.0,"confirmed":False,"risk":"MEDIUM",
          "strategy":"📈 PAUL MACD M1 + M5","engine":"PAULMACD","provider":"PAUL_MACD_10_20_7_M1_M5",
          "next_candle_entry":True,"expiry_candles":1,"direct_win_only":True,"gale_signal":False,
          "grid":False,"martingale":False,"closed_candles_only":True,"non_repaint_after_release":True}
    if len(rows)<80: return {**base,"reason":f"PAUL MACD coletando candles ({len(rows)}/80)."}
    try:
        closes=[float(x.get("close",0) or 0) for x in rows]
        def es(vals,n):
            a=2.0/(n+1.0); out=[vals[0]]
            for v in vals[1:]: out.append(a*v+(1-a)*out[-1])
            return out
        def macd(vals):
            f=es(vals,10); q=es(vals,20); m=[a-b for a,b in zip(f,q)]; sig=es(m,7); return m,sig
        m1,s1=macd(closes)
        cross_up=m1[-2]<=s1[-2] and m1[-1]>s1[-1]
        cross_dn=m1[-2]>=s1[-2] and m1[-1]<s1[-1]
        # M5 causal a partir de blocos fechados de 5 candles M1; suficiente para confirmar direção sem D1.
        m5c=[]
        for i in range(4,len(closes),5): m5c.append(closes[i])
        if len(m5c)<25: return {**base,"reason":"PAUL MACD aguardando histórico suficiente para confirmação M5."}
        m5,s5=macd(m5c)
        m5_up=m5[-1]>s5[-1] and m5[-1]>=m5[-2]
        m5_dn=m5[-1]<s5[-1] and m5[-1]<=m5[-2]
        call=cross_up and m5_up; put=cross_dn and m5_dn
        direction="CALL" if call and not put else ("PUT" if put and not call else "NEUTRO")
        diag={"macd_m1":round(m1[-1],10),"signal_m1":round(s1[-1],10),"cross_up":cross_up,"cross_down":cross_dn,
              "macd_m5":round(m5[-1],10),"signal_m5":round(s5[-1],10),"m5_up":m5_up,"m5_down":m5_dn}
        if direction=="NEUTRO": return {**base,"reason":"PAUL MACD monitorando cruzamento 10/20/7 no M1 com confirmação M5.","diagnostics":diag}
        strength=abs(m1[-1]-s1[-1])/max(abs(closes[-1]),1e-12)
        confidence=round(min(90.0,78.0+strength*120000),1)
        stamp=str(rows[-1].get("datetime") or rows[-1].get("timestamp") or "")
        return {**base,"direction":direction,"confidence":confidence,"confirmed":True,"risk":"LOW" if confidence>=84 else "MEDIUM",
                "reason":f"{direction} PAUL MACD • cruzamento M1 confirmado pelo M5 • próxima M1 • sem Gale.",
                "event_key":f"PAULMACD:{direction}:{stamp}","diagnostics":diag}
    except Exception as exc:
        return {**base,"reason":f"PAUL MACD aguardando leitura válida: {str(exc)[:100]}"}

def paul_macd_m1_strategy(cs, symbol="EUR/USD", timeframe="1min", market="OPEN"):
    """Paul MACD 10/20/7 totalmente M1: cruzamento + confirmação de direção no M1 fechado."""
    rows=list(cs or [])[-320:]
