def mega_premium_protected_strategy(cs, symbol="EUR/USD", timeframe="1min", market="OPEN", current_candle_closed=True, allow_prealert=False):
    """MEGA PREMIUM PROTEGIDO — mantém o gatilho MY 911 original e apenas bloqueia cenários frágeis."""
    original=mega_premium_strategy(cs,symbol=symbol,timeframe=timeframe,market=market,current_candle_closed=current_candle_closed,allow_prealert=allow_prealert)
    base={**original,"strategy":"🛡️ MEGA PREMIUM PROTEGIDO","engine":"MEGAPREMIUMPRO","provider":"MY_911_MTF_PROTECTED_V1"}
    if not original.get("confirmed") or original.get("direction") not in ("CALL","PUT"):
        return {**base,"reason":str(original.get("reason") or "MEGA PREMIUM PROTEGIDO monitorando gatilho original.").replace("MEGA PREMIUM","MEGA PREMIUM PROTEGIDO",1)}
    rows=list(cs or [])[-180:]
    try:
        o=[float(x.get("open",0) or 0) for x in rows]; h=[float(x.get("high",0) or 0) for x in rows]
        l=[float(x.get("low",0) or 0) for x in rows]; c=[float(x.get("close",0) or 0) for x in rows]
        if len(c)<60: return {**base,"direction":"NEUTRO","confirmed":False,"confidence":0.0,"reason":"MEGA PREMIUM PROTEGIDO coletando dados para os filtros de proteção."}
        # Horário de Brasília: evita madrugada/virada, onde spread/liquidez e ruído tendem a piorar.
        try:
            _stamp=str(rows[-1].get("datetime") or "")
            br=parse_dt(_stamp).astimezone(BR_TZ) if _stamp else now().astimezone(BR_TZ)
        except Exception:
            br=now().astimezone(BR_TZ)
        hour=br.hour
        hour_ok=(7 <= hour < 18) if market=="OPEN" else True
        # ATR relativo: bloqueia compressão/lateralização extrema e explosão anormal.
        trs=[]
        for i in range(1,len(c)): trs.append(max(h[i]-l[i],abs(h[i]-c[i-1]),abs(l[i]-c[i-1])))
        atr=sum(trs[-14:])/14.0 if len(trs)>=14 else 0.0
        avg_atr=sum(trs[-50:-14])/max(1,len(trs[-50:-14])) if len(trs)>20 else atr
        vol_ratio=atr/max(avg_atr,1e-12)
        volatility_ok=0.72 <= vol_ratio <= 1.85
        # Tendência de contexto M1 (proxy causal para M5): EMA 21/50 + inclinação.
        def _ema(vals,n):
            a=2.0/(n+1.0); e=vals[0]
            for v in vals[1:]: e=a*v+(1-a)*e
            return e
        e21=_ema(c[-80:],21); e50=_ema(c[-100:],50)
        e21_prev=_ema(c[-81:-1],21); e50_prev=_ema(c[-101:-1],50)
        d=original.get("direction")
        trend_ok=(d=="CALL" and e21>=e50 and e21>=e21_prev) or (d=="PUT" and e21<=e50 and e21<=e21_prev)
        rng=max(1e-12,h[-1]-l[-1]); body=abs(c[-1]-o[-1])/rng
        force_ok=body>=0.28
        diag=dict(original.get("diagnostics") or {})
        diag.update({"pro_hour_br":hour,"pro_hour_ok":hour_ok,"pro_vol_ratio":round(vol_ratio,3),"pro_volatility_ok":volatility_ok,"pro_trend_ok":trend_ok,"pro_body_ratio":round(body,3),"pro_force_ok":force_ok})
        # 5ª confluência: Volume POC estrutural já existente no app.
        # Ele não cria sinal no Premium Protegido; apenas vota quando confirma o MESMO lado do gatilho MY 911.
        poc_snap=_volume_poc_snapshot(rows, early_signal=bool(allow_prealert and not current_candle_closed), use_ai=False, mtf=None)
        poc_dir=str((poc_snap or {}).get("direction") or "NEUTRO").upper()
        poc_ok=bool(poc_snap and (poc_snap.get("coverage_ok") is True) and poc_dir==d)
        poc_opposite=bool(poc_snap and poc_dir in ("CALL","PUT") and poc_dir!=d)
        diag.update({
            "pro_poc_ok":poc_ok,"pro_poc_direction":poc_dir,"pro_poc_opposite":poc_opposite,
            "pro_poc":round(float((poc_snap or {}).get("poc") or 0.0),10),
            "pro_poc_volume_coverage":round(float((poc_snap or {}).get("volume_coverage") or 0.0),3),
            "pro_poc_call_score":int((poc_snap or {}).get("call_score") or 0),
            "pro_poc_put_score":int((poc_snap or {}).get("put_score") or 0),
        })
        checks={"horário":hour_ok,"volatilidade/lateralização":volatility_ok,"tendência de contexto":trend_ok,"força da vela":force_ok,"Volume POC":poc_ok}
        approved=[name for name,ok in checks.items() if ok]
        blocked=[name for name,ok in checks.items() if not ok]
        votes=len(approved)
        diag.update({"pro_votes":votes,"pro_required_votes":3,"pro_total_votes":5,"pro_approved":approved,"pro_blocked":blocked})
        if votes < 3:
            return {**base,"direction":"NEUTRO","confirmed":False,"confidence":0.0,"risk":"MEDIUM","reason":f"MEGA PREMIUM PROTEGIDO bloqueou o sinal original: {votes}/5 confluências aprovadas; mínimo 3/5. Falhou: "+", ".join(blocked)+".","diagnostics":diag}
        stamp=str(rows[-1].get("datetime") or rows[-1].get("timestamp") or "")
        conf=87.0 if votes==3 else (91.0 if votes==4 else 94.0)
        risk="LOW" if votes>=4 and not poc_opposite else "MEDIUM"
        return {**base,"confidence":conf,"risk":risk,"reason":f"{d} MEGA PREMIUM PROTEGIDO • gatilho original + {votes}/5 confluências aprovadas • POC {poc_dir} • próxima M1.","event_key":f"MEGAPREMIUMPRO:{d}:{stamp}","diagnostics":diag}
    except Exception as exc:
        return {**base,"direction":"NEUTRO","confirmed":False,"confidence":0.0,"reason":f"MEGA PREMIUM PROTEGIDO aguardando filtros: {str(exc)[:90]}"}


def sidus_v320_strategy(cs, symbol="EUR/USD", timeframe="1min", market="OPEN"):
    """SIDUS EA V3.20 FLEX — adaptação causal mais solta para opções binárias.
    Mantém EMA18/28 + WMA5/8, mas aceita um crossover ocorrido em até 3 candles fechados.
    Isso evita perder a oportunidade por polling sem transformar mero alinhamento em sinal contínuo.
    """
    rows=list(cs or [])
    base={"available":True,"direction":"NEUTRO","confidence":0.0,"confirmed":False,"risk":"MEDIUM",
          "strategy":"🎯 SIDUS EA V3.20","engine":"SIDUS320","provider":"SIDUS_V320_CAUSAL_FLEX_V2",
          "next_candle_entry":True,"expiry_candles":1,"direct_win_only":True,"gale_signal":False,
          "grid":False,"martingale":False,"closed_candles_only":True,"non_repaint_after_release":True}
    if len(rows)<40:
        return {**base,"reason":f"SIDUS coletando candles ({len(rows)}/40)."}
    try:
        closes=[float(x.get("close",0) or 0) for x in rows]
        def _ema_series(vals, period):
            a=2.0/(period+1.0); out=[vals[0]]
            for v in vals[1:]: out.append(a*v+(1-a)*out[-1])
            return out
        def _wma_at(vals, period, end_idx):
            q=vals[end_idx-period+1:end_idx+1]; den=period*(period+1)/2.0
            return sum(v*(i+1) for i,v in enumerate(q))/den
        e18=_ema_series(closes,18); e28=_ema_series(closes,28)
        w5=_wma_at(closes,5,len(closes)-1); w8=_wma_at(closes,8,len(closes)-1)
        tunnel_up=e18[-1]>e28[-1]; tunnel_dn=e18[-1]<e28[-1]

        # FLEX: o cruzamento pode ter acontecido no último, penúltimo ou antepenúltimo candle.
        # A chave do evento usa o candle real do cruzamento, evitando repetir o mesmo sinal.
        cross_up_idx=None; cross_dn_idx=None
        first=max(8,len(closes)-3)
        for i in range(first,len(closes)):
            c5=_wma_at(closes,5,i); c8=_wma_at(closes,8,i)
            p5=_wma_at(closes,5,i-1); p8=_wma_at(closes,8,i-1)
            if p5<=p8 and c5>c8: cross_up_idx=i
            if p5>=p8 and c5<c8: cross_dn_idx=i

        aligned_up=w5>w8
        aligned_dn=w5<w8
        # O preço não precisa mais superar estritamente a EMA18: basta continuar do lado correto
        # do túnel pela média rápida/lenta e preservar o alinhamento WMA.
        call=cross_up_idx is not None and aligned_up and tunnel_up
        put=cross_dn_idx is not None and aligned_dn and tunnel_dn
        direction="CALL" if call and not put else ("PUT" if put and not call else "NEUTRO")
        diag={"ema18":round(e18[-1],10),"ema28":round(e28[-1],10),"wma5":round(w5,10),"wma8":round(w8,10),
              "cross_up_recent":cross_up_idx is not None,"cross_down_recent":cross_dn_idx is not None,
              "cross_memory_bars":3}
        if direction=="NEUTRO":
            return {**base,"reason":"SIDUS FLEX monitorando crossover WMA 5/8 (memória 3 candles) alinhado ao túnel EMA 18/28.","diagnostics":diag}
        cross_idx=cross_up_idx if direction=="CALL" else cross_dn_idx
        spread=abs(w5-w8)/max(abs(closes[-1]),1e-12)
        age=(len(closes)-1)-int(cross_idx)
        confidence=round(min(89.0,76.0+spread*100000-max(0,age)*1.5),1)
        cross_row=rows[int(cross_idx)]
        stamp=str(cross_row.get("datetime") or cross_row.get("timestamp") or cross_idx)
        return {**base,"direction":direction,"confidence":confidence,"confirmed":True,"risk":"LOW" if confidence>=84 else "MEDIUM",
                "reason":f"{direction} SIDUS FLEX • crossover recente + túnel confirmado • próxima M1 • sem Gale.",
                "event_key":f"SIDUS320:{direction}:{stamp}","diagnostics":diag}
    except Exception as exc:
        return {**base,"reason":f"SIDUS aguardando leitura válida: {str(exc)[:100]}"}

def predator_pips_strategy(cs, symbol="EUR/USD", timeframe="1min", market="OPEN"):
    """PREDATOR PIPS — MA100 +/-60 points, corrigido para não exigir um evento impossível no mesmo candle.
    Aceita cruzamento real da borda OU rejeição da zona; candle fechado, próxima M1, sem Gale.
    """
    rows=list(cs or [])
    base={"available":True,"direction":"NEUTRO","confidence":0.0,"confirmed":False,"risk":"MEDIUM",
          "strategy":"🐆 PREDATOR PIPS","engine":"PREDATORPIPS","provider":"EA_PREDATOR_PIPS_MA100_ZONE_CROSS_V2",
          "next_candle_entry":True,"expiry_candles":1,"direct_win_only":True,"gale_signal":False,
          "grid":False,"martingale":False,"closed_candles_only":True,"non_repaint_after_release":True}
    if len(rows)<110:
        return {**base,"reason":f"PREDATOR PIPS coletando candles ({len(rows)}/110)."}
    try:
        closes=[float(x.get("close",0) or 0) for x in rows]
        opens=[float(x.get("open",0) or 0) for x in rows]
        highs=[float(x.get("high",0) or 0) for x in rows]
        lows=[float(x.get("low",0) or 0) for x in rows]
        ma100=sum(closes[-101:-1])/100.0
        sym=str(symbol or "").upper().replace("/","").replace("-","")
        price=max(abs(closes[-1]),1e-12)
        if "JPY" in sym:
            point=0.001
        elif any(k in sym for k in ("BTC","ETH","LTC","CRYPTO")):
            point=0.01
        else:
            point=0.00001
        zone=60.0*point
        lower=ma100-zone; upper=ma100+zone
        c=closes[-1]; o=opens[-1]; h=highs[-1]; l=lows[-1]; pc=closes[-2]
        rng=max(1e-12,h-l); body=abs(c-o)/rng
        # Cruzamento da borda entre dois fechamentos OU rejeição intrabar da própria zona.
        cross_call=(pc < lower and c >= lower and c > o)
        cross_put=(pc > upper and c <= upper and c < o)
        reject_call=(l <= lower and c >= lower and c > o and body >= 0.18)
        reject_put=(h >= upper and c <= upper and c < o and body >= 0.18)
        call=(cross_call or reject_call) and c>pc
        put=(cross_put or reject_put) and c<pc
        direction="CALL" if call and not put else ("PUT" if put and not call else "NEUTRO")
        diag={"ma100":round(ma100,10),"zone_points":60,"point":point,"lower":round(lower,10),"upper":round(upper,10),
              "body_ratio":round(body,3),"cross_call":cross_call,"cross_put":cross_put,"reject_call":reject_call,"reject_put":reject_put}
        if direction=="NEUTRO":
            return {**base,"reason":"PREDATOR PIPS monitorando • aguardando cruzamento ou rejeição da zona MA100 ±60 pontos.","diagnostics":diag}
        confidence=round(min(90.0,76.0+min(10.0,max(0.0,body-0.18)*18.0)),1)
        stamp=str(rows[-1].get("datetime") or rows[-1].get("timestamp") or "")
        return {**base,"direction":direction,"confidence":confidence,"confirmed":True,"risk":"LOW" if confidence>=84 else "MEDIUM",
                "reason":f"{direction} PREDATOR PIPS • cruzamento/rejeição MA100 ±60 pontos confirmado • próxima M1 • sem Gale.",
                "event_key":f"PREDATORPIPS:{direction}:{stamp}","diagnostics":diag}
    except Exception as exc:
        return {**base,"reason":f"PREDATOR PIPS aguardando leitura válida: {str(exc)[:100]}"}

def mega_hft_strategy(cs, symbol="EUR/USD", timeframe="1min", market="OPEN"):
    """MEGA HFT — adaptação causal do hft ea.mq4 para opções binárias.
    Núcleo original: extremo de 2 desvios em 20 períodos + preço ponderado por volume
    contra média de extremos + OBV + A/D. Usa candle fechado e entra na próxima M1.
    Gestão Forex (lote, spread, comissão, TP/SL e OrderSend) não participa do sinal binário.
    """
    rows=list(cs or [])[-120:]
    base={"available":True,"direction":"NEUTRO","confidence":0.0,"confirmed":False,
          "strategy":"⚡ MEGA HFT","engine":"MEGAHFT","provider":"HFT_EA_FINANCEWAVE_CAUSAL_V1",
          "risk":"HIGH","closed_candles_only":True,"non_repaint":True,
          "next_candle_entry":True,"expiry_candles":1,"gale_signal":False,"martingale":False}
    if len(rows)<21:
        return {**base,"reason":f"MEGA HFT coletando candles ({len(rows)}/21)."}
    try:
        r=rows[-21:]
        closes=[float(x.get("close",0)) for x in r]
        highs=[float(x.get("high",0)) for x in r]
        lows=[float(x.get("low",0)) for x in r]
        vols=[max(0.0,float(x.get("volume") or x.get("tick_volume") or 0)) for x in r]
        # Alguns feeds não entregam volume; volume unitário preserva a leitura de preço sem inventar fluxo.
        if sum(vols[-20:])<=0: vols=[1.0]*len(r)
        c=closes[-20:]; h=highs[-20:]; l=lows[-20:]; v=vols[-20:]
        mean=sum(c)/20.0
        dev=(sum((x-mean)**2 for x in c)/20.0)**0.5
        volsum=max(1e-12,sum(v)); meanv=sum(c[i]*v[i] for i in range(20))/volsum
        meanh=sum(h)/20.0; meanl=sum(l)/20.0
        obv=[0.0]*20; prev=closes[-21]
        running=0.0
        for i in range(20):
            running += v[i] if c[i]>prev else -v[i]
            obv[i]=running; prev=c[i]
        mean_obv=sum(obv)/20.0
        ad=[0.0]*20; running_ad=0.0; prev=closes[-21]
        for i in range(20):
            running_ad += v[i]*(c[i]-prev)
            ad[i]=running_ad; prev=c[i]
        mean_ad=sum(ad)/20.0
        last=c[-1]
        # 3.98.20 — o filtro anterior comparava o preço ponderado por volume com
        # a MÉDIA das máximas/mínimas de 20 candles. Na prática isso tornava a
        # confluência quase impossível e o MEGA HFT permanecia ONLINE sem sinal.
        # Mantemos o gatilho nativo de extremo 2σ e as confirmações de fluxo OBV/A-D.
        avg_vol=sum(v)/20.0
        vol_ok=(v[-1] >= avg_vol*0.60) if avg_vol>0 else True
        sell=(last>mean+2.0*dev and obv[-1]<mean_obv and ad[-1]<mean_ad and vol_ok)
        buy=(last<mean-2.0*dev and obv[-1]>mean_obv and ad[-1]>mean_ad and vol_ok)
        direction="PUT" if sell and not buy else ("CALL" if buy and not sell else "NEUTRO")
        z=abs(last-mean)/max(dev,1e-12)
        diag={"mean20":round(mean,8),"std20":round(dev,8),"zscore":round(z,2),
              "volume_weighted_price":round(meanv,8),"mean_high20":round(meanh,8),
              "mean_low20":round(meanl,8),"obv":round(obv[-1],2),"obv_mean":round(mean_obv,2),
              "ad":round(ad[-1],4),"ad_mean":round(mean_ad,4),"volume_ok":bool(vol_ok)}
        if direction=="NEUTRO":
            return {**base,"reason":"MEGA HFT monitorando extremo 2σ + volume + OBV + A/D.","diagnostics":diag}
        conf=round(min(94.0,78.0+min(10.0,max(0.0,z-2.0)*8.0)+6.0),1)
        stamp=str(r[-1].get("datetime") or r[-1].get("timestamp") or "")
        return {**base,"direction":direction,"confidence":conf,"confirmed":True,"risk":"LOW",
                "reason":f"{direction} MEGA HFT • extremo 2σ confirmado por Volume + OBV + A/D • próxima M1.",
                "event_key":f"MEGAHFT:{direction}:{stamp}","diagnostics":diag}
    except Exception as exc:
        return {**base,"reason":f"MEGA HFT aguardando leitura válida: {str(exc)[:100]}"}

def pyramid7_strategy(cs, symbol="EUR/USD", timeframe="1min", market="OPEN"):
    """PYRAMID 7 PRO — adaptação binária causal do EA Pyramid 7.
    Núcleo original preservado: breakout das Bollinger Bands 20/2.
    Para reduzir rompimentos fracos no M1, usa ATR14 + EMA62/200 como confirmação.
    Removidos: Pyramid, Average, multiplicador de lote, grid, TP/SL/trailing e múltiplas ordens.
    """
    rows=list(cs or [])
    base={"available":True,"direction":"NEUTRO","confidence":0.0,"confirmed":False,"risk":"MEDIUM",
          "strategy":"🔺 PYRAMID 7 PRO","engine":"PYRAMID7","provider":"EA_PYRAMID7_BB20_ATR14_TREND",
          "next_candle_entry":True,"expiry_candles":1,"direct_win_only":True,"gale_signal":False,
          "grid":False,"pyramid":False,"average":False,"martingale":False,
          "closed_candles_only":True,"non_repaint_after_release":True}
    if len(rows)<220:
        return {**base,"reason":f"PYRAMID 7 PRO coletando candles ({len(rows)}/220)."}
    try:
        closes=[float(x.get("close",0) or 0) for x in rows]
        opens=[float(x.get("open",0) or 0) for x in rows]
        highs=[float(x.get("high",0) or 0) for x in rows]
        lows=[float(x.get("low",0) or 0) for x in rows]
        prev=closes[-21:-1]
        mid=sum(prev)/20.0
        var=sum((x-mid)**2 for x in prev)/20.0
        sd=var**0.5
        upper=mid+2.0*sd; lower=mid-2.0*sd
        # Previous bands ensure the signal candle cannot move its own breakout threshold.
        prev2=closes[-22:-2]
        mid_prev=sum(prev2)/20.0
        sd_prev=(sum((x-mid_prev)**2 for x in prev2)/20.0)**0.5
        upper_prev=mid_prev+2.0*sd_prev; lower_prev=mid_prev-2.0*sd_prev
        trs=[]
        for i in range(max(1,len(rows)-15),len(rows)):
            pc=closes[i-1]
            trs.append(max(highs[i]-lows[i],abs(highs[i]-pc),abs(lows[i]-pc)))
        atr14=sum(trs[-14:])/max(1,len(trs[-14:]))
        e62=ema(closes,62); e200=ema(closes,200)
        rng=max(1e-12,highs[-1]-lows[-1]); body=abs(closes[-1]-opens[-1])
        body_ratio=body/rng
        range_atr=rng/max(atr14,1e-12)
        bull=closes[-1]>opens[-1]; bear=closes[-1]<opens[-1]
        # 3.97.78 — gatilho nativo do EA: fechamento rompe a Bollinger 20/2 anterior.
        # ATR14 e EMA62/200 continuam calculados para diagnóstico/placar, mas NÃO bloqueiam
        # um breakout válido. Isso evita o estado ONLINE sem sinais causado por confluências extras.
        call=(closes[-1] > upper_prev and bull)
        put=(closes[-1] < lower_prev and bear)
        direction="CALL" if call and not put else ("PUT" if put and not call else "NEUTRO")
        diag={"bb20_upper":round(upper_prev,10),"bb20_lower":round(lower_prev,10),
              "bb20_mid":round(mid_prev,10),"atr14":round(atr14,10),
              "ema62":round(float(e62),10),"ema200":round(float(e200),10),
              "body_ratio":round(body_ratio,3),"range_atr":round(range_atr,3)}
        if direction=="NEUTRO":
            return {**base,"reason":"PYRAMID 7 PRO monitorando • aguardando rompimento nativo da Bollinger 20/2.","diagnostics":diag}
        strength=max(0.0,min(8.0,(body_ratio-0.45)*12.0))+max(0.0,min(6.0,(range_atr-0.70)*4.0))
        confidence=round(min(92.0,76.0+strength),1)
        stamp=str(rows[-1].get("datetime") or rows[-1].get("timestamp") or "")
        return {**base,"direction":direction,"confidence":confidence,"confirmed":True,"risk":"LOW" if confidence>=84 else "MEDIUM",
                "reason":f"{direction} PYRAMID 7 PRO • breakout Bollinger 20/2 confirmado • próxima M1 • sem Grid/Pyramid/Martingale/Gale.",
                "event_key":f"PYRAMID7:{direction}:{stamp}","diagnostics":diag}
    except Exception as exc:
        return {**base,"reason":f"PYRAMID 7 PRO aguardando leitura válida: {str(exc)[:100]}"}


