def _canonical_time_key(value: Any) -> str:
    """Normaliza timestamps equivalentes para impedir contagem duplicada.

    O painel pode enviar o mesmo instante como UTC (Z) ou com offset de
    Brasília. A string muda, mas o instante é o mesmo. A contabilidade usa
    epoch em segundos para que a mesma operação tenha sempre uma única chave.
    """
    if value in (None, ""):
        return ""
    try:
        return str(int(parse_dt(str(value)).timestamp()))
    except Exception:
        return str(value).strip()


def _accounting_key(payload: Dict[str, Any]) -> str:
    # 3.98.34 — uma operação física é identificada pela ENTRADA.
    # expiry_time pode chegar com pequenas diferenças por rotas/pollings distintos;
    # não pode transformar o mesmo sinal em duas operações.
    return _result_operation_key(payload, str(payload.get("market") or "OPEN").upper())


def _result_operation_key(payload: Dict[str, Any], market: str = "OPEN") -> str:
    """Chave única da operação física, independente do caminho que a registrou.

    O mesmo sinal pode chegar ao servidor pelo painel e pela rotina de
    resultado com pequenas diferenças no campo de expiração. A entrada
    (mercado + ativo + timeframe + direção + instante de entrada) é a
    identidade estável da operação e impede WIN/LOSS em dobro.
    """
    return "|".join([
        str(market or payload.get("market") or "OPEN").upper(),
        str(payload.get("symbol") or ""),
        str(payload.get("interval") or ""),
        str(payload.get("direction") or "").upper(),
        _canonical_time_key(payload.get("entry_time")),
    ])


def _accounting_buckets(request: Request, market: str):
    market = (market or "OPEN").upper()
    if market == "IQ_OTC":
        state = _iq_session_state(request, required=False)
        if state is None:
            return None, None
        return (
            state.setdefault("accounting_pending", {}),
            state.setdefault("accounting_results", {}),
        )
    return (
        accounting_pending.setdefault(market, {}),
        accounting_results.setdefault(market, {}),
    )


def _remember_accounting_signal(request: Request, payload: Dict[str, Any]):
    """Registra uma entrada confirmada no servidor, independente do navegador."""
    if not isinstance(payload, dict):
        return
    direction = str(payload.get("direction") or "").upper()
    if direction not in ("CALL", "PUT"):
        return
    if not payload.get("entry_time") or not payload.get("expiry_time"):
        return
    market = str(payload.get("market") or "OPEN").upper()
    pending, done = _accounting_buckets(request, market)
    if pending is None or done is None:
        return
    rtm_meta = payload.get("rtm_individual") if isinstance(payload.get("rtm_individual"), dict) else {}
    engine_name = str(payload.get("selected_engine") or payload.get("engine") or payload.get("mode") or "").upper()
    item = {
        "market": market,
        "symbol": payload.get("symbol"),
        "interval": payload.get("interval"),
        "direction": direction,
        "entry_time": payload.get("entry_time"),
        "expiry_time": payload.get("expiry_time"),
        "source": payload.get("source") or payload.get("strategy") or "SIGNAL",
        "strategy": payload.get("strategy") or payload.get("source") or "SIGNAL",
        "engine": payload.get("selected_engine") or payload.get("engine") or payload.get("mode") or "",
        "confidence": float(payload.get("confidence") or 0.0),
        "risk": str(payload.get("risk") or ""),
        "direct_only": True,  # 3.96.7: todos os motores sem Gale; LOSS encerra esta entrada.
        "external_ai": bool(payload.get("external_ai", False)),
        "feed_source": str(payload.get("feed_source") or ""),
        "source_symbol": str(payload.get("source_symbol") or ""),
        "trigger_indicator": payload.get("trigger_indicator") or rtm_meta.get("trigger_indicator"),
        "trigger_score": payload.get("trigger_score") if payload.get("trigger_score") is not None else rtm_meta.get("trigger_score"),
    }
    key = _accounting_key(item)
    if key and key not in done and key not in pending:
        pending[key] = item


async def _settle_accounting_pending(request: Request, market: str):
    """Fecha sinais expirados pelo candle da entrada original e grava WIN/LOSS uma vez."""
    market = (market or "OPEN").upper()
    pending, done = _accounting_buckets(request, market)
    if pending is None or done is None or not pending:
        return

    iq_state = _iq_session_state(request, required=False) if market == "IQ_OTC" else None
    for key, t in list(pending.items())[:30]:
        try:
            expiry_dt = parse_dt(t["expiry_time"])
            # Pequena folga para não ler o candle ainda em formação/cache antigo.
            if now() < expiry_dt + timedelta(seconds=2):
                continue
            symbol = t["symbol"]
            interval = t["interval"]
            direction = str(t["direction"]).upper()
            entry_dt = parse_dt(t["entry_time"])
            if market == "OPEN":
                _invalidate_preexpiry_open_result_cache(symbol, interval, expiry_dt)
            cs = await candles(symbol, interval, 50, market, iq_state, request=request)
            expected_feed = str(t.get("feed_source") or "").upper()
            # Não inventa WIN/LOSS com outra corretora ou cotação pública.
            if market == "OPEN" and expected_feed and expected_feed != "UNKNOWN":
                if not _result_feed_compatible(expected_feed, _feed_source_from_rows(cs)):
                    continue

            target, best_delta, matched_dt = _nearest_candle_for_time(
                cs, entry_dt, INTERVALS[interval]
            )

            if not target or not _verified_closed_candles([target], interval):
                continue

            op = float(target["open"])
            cl = float(target["close"])
            if cl == op:
                # Empate não vira WIN nem LOSS; marca como DRAW para não duplicar.
                result_value = "DRAW"
            else:
                won = ((direction == "CALL" and cl > op) or (direction == "PUT" and cl < op))
                result_value = "WIN" if won else "LOSS"

            done[key] = {
                **t,
                "result": result_value,
                "candle_time": target.get("datetime"),
                "open": op,
                "close": cl,
                "settled_at": iso(now()),
            }
            pending.pop(key, None)
            if str(t.get("engine") or "").upper() == "RTM" and result_value in ("WIN", "LOSS"):
                _rtm_indicator_apply_result(
                    market, str(t.get("symbol") or ""), t.get("trigger_indicator"), result_value, key
                )
        except Exception:
            # Mantém pendente para tentar novamente no próximo ciclo.
            continue


@app.get("/performance")
async def performance(request: Request, interval="1min", market="OPEN"):
    market=(market or "OPEN").upper()

    if market not in VALID_MARKETS:
        raise HTTPException(400, "Mercado inválido.")

    await _settle_accounting_pending(request, market)
    pending, done = _accounting_buckets(request, market)
    done = done or {}

    # 33.77.1 — uma operação física só pode produzir UM resultado final.
    # A entrada é identificada por mercado+ativo+timeframe+direção+horário.
    # Isso evita que o mesmo WIN chegue pelo painel e pela contabilidade
    # automática e seja somado duas vezes.
    merged_direct = {}
    for x in done.values():
        if x.get("result") in ("WIN", "LOSS", "DRAW"):
            merged_direct[_result_operation_key(x, market)] = x

    if market == "IQ_OTC":
        state_direct = _iq_session_state(request, required=False)
        direct_store = state_direct.setdefault("results", {}) if state_direct else {}
    else:
        direct_store = results.setdefault(market, {})

    # Diagnóstico da vela da entrada (LOSS direto; não existe Gale).
    for x in direct_store.values():
        entry_result = str(x.get("entry_result") or "").upper()
        if entry_result in ("WIN", "LOSS", "DRAW"):
            k = _result_operation_key(x, market)
            merged_direct[k] = {**x, "result": entry_result}
        elif x.get("result") in ("WIN", "LOSS", "DRAW"):
            merged_direct[_result_operation_key(x, market)] = x

    loss_direct = sum(1 for x in merged_direct.values() if x.get("result") == "LOSS")
    draws = sum(1 for x in merged_direct.values() if x.get("result") == "DRAW")

    # Resultado FINAL por operação. Novas operações são sempre diretas, sem G1/G2.
    # Entradas antigas com G1/G2 podem permanecer no histórico legado.
    final_ops = {}
    for x in done.values():
        r_done = str(x.get("result") or "").upper()
        if r_done == "WIN":
            final_ops[_result_operation_key(x, market)] = "WIN"
        elif r_done == "LOSS" and bool(x.get("direct_only")):
            # Motores configurados como direct_only encerram a operação na primeira vela.
            final_ops[_result_operation_key(x, market)] = "LOSS"

    for x in direct_store.values():
        r = str(x.get("result") or "").upper()
        k = _result_operation_key(x, market)
        if r in ("WIN G1", "WIN G2", "LOSS G2"):
            final_ops[k] = r
        elif r == "LOSS" and bool(x.get("direct_only")):
            final_ops[k] = "LOSS"
        elif r == "WIN" and k not in final_ops:
            final_ops[k] = "WIN"

    win_direct = sum(1 for r in final_ops.values() if r == "WIN")
    win_g1 = sum(1 for r in final_ops.values() if r == "WIN G1")
    win_g2 = sum(1 for r in final_ops.values() if r == "WIN G2")
    loss_g2 = sum(1 for r in final_ops.values() if r == "LOSS G2")
    loss_direct_final = sum(1 for r in final_ops.values() if r == "LOSS")

    wins = win_direct + win_g1 + win_g2
    losses = loss_g2 + loss_direct_final
    total = wins + losses

    recent_results = []
    for x in done.values():
        r = str(x.get("result") or "").upper()
        if r not in ("WIN", "LOSS", "DRAW"):
            continue
        row = dict(x)
        row["operation_key"] = _result_operation_key(row, market)
        recent_results.append(row)
    recent_results.sort(key=lambda x: str(x.get("settled_at") or x.get("entry_time") or ""), reverse=True)

    return {
        "wins": wins,
        "losses": losses,
        "total": total,
        "accuracy": round(wins / total * 100, 2) if total else 0,
        "win_direct": win_direct,
        "loss_direct": loss_direct,
        "draws": draws,
        "pending": len(pending or {}),
        "win_g1": win_g1,
        "loss_g1": None,  # Etapa intermediária não contabilizada de modo confiável
        "win_g2": win_g2,
        "loss_g2": loss_g2,
        "loss_direct_final": loss_direct_final,
        "recent_results": recent_results[:120],
    }


@app.post("/performance/reset")
async def reset_performance(request: Request, market="OPEN"):
    """Zera resultados e entradas pendentes do mercado selecionado."""
    market = (market or "OPEN").upper()
    if market not in VALID_MARKETS:
        raise HTTPException(400, "Mercado inválido.")

    if market == "IQ_OTC":
        state = _iq_session_state(request, required=False)
        if state is not None:
            state.setdefault("accounting_pending", {}).clear()
            state.setdefault("accounting_results", {}).clear()
            state.setdefault("results", {}).clear()
    else:
        accounting_pending.setdefault(market, {}).clear()
        accounting_results.setdefault(market, {}).clear()
        results.setdefault(market, {}).clear()

    return {"ok": True, "market": market, "message": "Resultados zerados com sucesso."}



def _result_feed_compatible(expected: str, observed: str) -> bool:
    # 3.97.99 — o frontend pode guardar o rótulo humano da fonte (ex.:
    # "BINANCE PÚBLICA"), enquanto os candles carregam a chave técnica
    # "BINANCE_PUBLIC". Antes essa diferença fazia candle_near() rejeitar a
    # vela correta para sempre e o card RESULTADO ficava em --.
    def canonical(value: str) -> str:
        import unicodedata
        raw = unicodedata.normalize("NFKD", str(value or "")).encode("ascii", "ignore").decode("ascii")
        raw = re.sub(r"[^A-Z0-9]+", "_", raw.upper()).strip("_")
        if raw in ("BINANCE", "BINANCE_PUBLIC", "BINANCE_PUBLICA", "BINANCE_SPOT"):
            return "BINANCE_PUBLIC"
        if raw.startswith("TWELVE_DATA") or raw in ("TWELVEDATA", "TD"):
            return "TWELVE_DATA"
        if raw.startswith("CTRADER"):
            return "CTRADER"
        if raw in ("MULTIFEED", "MULTIFONTE", "AUTOMATICA", "AUTOMATICO"):
            return "MULTIFEED"
        return raw

    expected_key = canonical(expected)
    observed_key = canonical(observed)
    if not expected_key or expected_key == "UNKNOWN" or expected_key == "MULTIFEED":
        return True
    if expected_key == "TWELVE_DATA" and observed_key == "TWELVE_DATA":
        return True  # WS e REST do mesmo provedor/preço.
    return expected_key == observed_key


def _cached_open_candles_for_result(symbol: str, interval: str, n: int = 100, *, request=None, completed_after=None):
    """Não mistura cTrader com TD e não apura usando snapshot anterior à expiração."""
    key = f"{symbol}|{interval}"
    sess_id, sess = (None, None)
    if request is not None:
        try:
            sess_id, sess = _ctrader_session_from_request(request)
        except Exception:
            pass
    use_ctrader = bool(sess and _ctrader_symbol_supported(sess, symbol))
    scoped_key = f"{key}|CTRADER:{sess_id}" if use_ctrader else key
    # Não cair no cache genérico da TD se este usuário está lendo cTrader.
    item = public_feed_cache.get(scoped_key) if use_ctrader else (public_feed_cache.get(key) or td_candle_cache.get(key))
    if not item:
        return []
    try:
        if completed_after is not None and float(item[0]) < completed_after.timestamp() + 2.0:
            return []
        values = list(item[1] or [])
        if use_ctrader and _feed_source_from_rows(values) != "CTRADER_OPEN":
            return []
        return values[-max(20, min(int(n), 150)):]
    except Exception:
        return []


async def _fetch_open_result_window(symbol: str, interval: str, target_dt: datetime):
    """Busca uma janela pequena exatamente ao redor da entrada na Twelve Data.

    É usada somente quando o cache/histórico recente não contém a vela necessária
    para fechar WIN/LOSS. Isso evita deixar uma operação presa em
    "AGUARDANDO CANDLE" por causa de cache curto ou sessão de mercado.
    """
    global td_last_call_at, td_backoff_until, td_backoff_reason
    if not TD_KEY:
        return []
    try:
        seconds = int(INTERVALS.get(interval, 60))
        start_dt = (target_dt - timedelta(seconds=seconds * 2)).astimezone(BR_TZ)
        end_dt = (target_dt + timedelta(seconds=seconds * 3)).astimezone(BR_TZ)
        params = {
            "symbol": symbol,
            "interval": interval,
            "start_date": start_dt.strftime("%Y-%m-%d %H:%M:%S"),
            "end_date": end_dt.strftime("%Y-%m-%d %H:%M:%S"),
            "timezone": "America/Sao_Paulo",
            "outputsize": 12,
            "apikey": TD_KEY,
            "format": "JSON",
        }

        # Respeita o mesmo limitador global usado pelo restante da Twelve Data.
        async with td_rate_lock:
            delay = TD_MIN_CALL_INTERVAL - (time.time() - td_last_call_at)
            if delay > 0:
                await asyncio.sleep(delay)
            async with td_sem:
                async with httpx.AsyncClient(timeout=15) as client:
                    response = await client.get(TD_URL, params=params)
                td_last_call_at = time.time()

        if response.status_code == 429:
            td_backoff_until = time.time() + 60.0
            td_backoff_reason = "HTTP 429 em resultado"
            return []
        response.raise_for_status()
        data = response.json()
        if data.get("status") == "error":
            return []

        out = []
        for x in reversed(data.get("values", [])):
            try:
                out.append({
                    "datetime": x["datetime"],
                    "open": float(x["open"]),
                    "high": float(x["high"]),
                    "low": float(x["low"]),
                    "close": float(x["close"]),
                    "volume": float(x.get("volume", 0) or 0),
                })
            except Exception:
                pass
        if out:
            print(
                f"[RESULTADO] janela exata Twelve Data recuperada {symbol} {interval} "
                f"entrada={iso(target_dt)} candles={len(out)}",
                flush=True,
            )
        return out
    except Exception as exc:
        print(
            f"[RESULTADO] falha janela exata Twelve Data {symbol} {interval}: {str(exc)[:180]}",
            flush=True,
        )
        return []


@app.get("/result")
async def result(
    request: Request,
    symbol="EUR/USD",
    interval="1min",
    direction="CALL",
    expiry_time="",
    market="OPEN",
    direct_only: bool = False,
    gale_levels: int = 0,
    engine: str = "",
    feed_source: str = "",
):
    """Apura somente a vela da entrada.

    MEGA IA 3.96.7: todos os motores trabalham sem Gale. WIN/LOSS/DRAW encerra
    a operação atual; qualquer recuperação financeira acontece somente no
    próximo sinal confirmado, nunca em G1/G2 da mesma operação.
    """
    if not expiry_time:
        raise HTTPException(400, "expiry_time é obrigatório.")

    market = (market or "OPEN").upper()
    direction = (direction or "CALL").upper()
    engine = str(engine or "").upper()
    expected_result_feed = str(feed_source or "").upper()

    # MEGA IA 3.96.7 — regra global: SEM GALE para todos os motores.
    # Um LOSS encerra a entrada atual. A recuperação de valor, quando usada,
    # é preparada exclusivamente para o próximo sinal confirmado.
    gale_levels = max(0, min(2, int(gale_levels or 0)))
    if engine == 'SCALPINGM1' and not direct_only:
        # Somente apuração virtual das duas velas seguintes; não gera ordens.
        gale_levels = 2
    if gale_levels <= 0:
        direct_only = True

    # EA Tripla usa multifuente no OPEN e IQ somente no OTC.
    # Não exigir sessão IQ para apurar resultado da EA em mercado aberto.
    ea_iq_result = market == "IQ_OTC" and engine in ("EA", "FORCE", "RUBIK", "LARRY", "RANGE", "VELOCITY", "RSI5", "SNIPER", "TAURUSSENEGAL", "BOBSENEGAL", "TAURUSEA", "TAURUSRSIDIV", "COMBINER", "RSIDIVBB", "TMARSI", "TLBRSI", "FIBORSI", "TRIPRSI", "ALPHAX", "PRESIDEN", "RAPID", "VOLUME", "VOLUME_AI", "SUNTZU", "BLACKBOOK", "INDICEMENT", "GOLDINV", "TTMSCALPER", "FOREXMISSION", "MONEYARROW", "LIQUIDEX", "EUROFX2", "EUROFX2TAURUS", "ATE", "FOREXSTAY", "FOREXSTAYTAURUS", "FOREXSTAYPRO", "FOREXFLEX", "SENEGALPRO", "VALUEMACD", "HOLYGRAIL", "TRENDLINES", "BBSTOCH", "KAMIKAZE", "FOREXMEGA", "BROOKYVERTEX", "MEGABOT", "BROOKYC3", "UTBOT", "ONEMINRSI", "WPRADAPT", "TINGATINGA", "SUPERNOVA", "ELCODEX", "SHKHA", "TSI", "MOMENTUM", "FIGURES", "VASILY", "PLATINUM", "STREAKREV", "ISMAELTRADER", "ISMAEL98", "RSICHANNEL", "RSICHANNEL2", "MINSCALPER", "RSI4PERIOD", "RSICROSS", "NINJAHFT", "SESSIONBREAKOUT", "MONSTERSMC")

    if market not in VALID_MARKETS:
        raise HTTPException(400, "Mercado inválido.")

    if direction not in ("CALL", "PUT"):
        raise HTTPException(400, "Direção inválida.")

    if interval not in INTERVALS:
        raise HTTPException(400, "Intervalo inválido.")

    state = _iq_session_state(request, required=True) if (market == "IQ_OTC" or ea_iq_result) else None
    store = state.setdefault("results", {}) if market == "IQ_OTC" else results.setdefault(market, {})
    mode_key = "DIRECT" if direct_only else f"GALE{gale_levels}"
    # Usa o instante normalizado, não a representação textual do horário.
    # Assim 03:16:00Z e 00:16:00-03:00 apontam para a mesma operação.
    canonical_expiry = _canonical_time_key(expiry_time)
    key = f"{market}|{symbol}|{interval}|{direction}|{canonical_expiry}|{mode_key}"

    if key in store and store[key].get("status") == "FINALIZADA":
        return store[key]

    expiry_dt = parse_dt(expiry_time)
    step = timedelta(seconds=INTERVALS[interval])
    entry_dt = expiry_dt - step

    if now() < expiry_dt:
        return {
            "status": "PENDENTE",
            "stage": "ENTRADA",
            "result": None,
            "entry_result": None,
            "next_check": iso(expiry_dt),
        }

    # Apura na mesma família de fonte do sinal:
    # EA Tripla OPEN -> cache/roteador multifuente; EA/FORCE OTC -> IQ Option.
    # Os outros motores preservam a apuração existente.
    cs = (
        []
        if ea_iq_result
        else (_cached_open_candles_for_result(symbol, interval, 140, request=request, completed_after=expiry_dt) if market == "OPEN" else [])
    )
    if not cs:
        try:
            if market == "OPEN":
                _invalidate_preexpiry_open_result_cache(symbol, interval, expiry_dt)
            if ea_iq_result:
                cs = await iq_ea_candles(
                    state, symbol, interval, 120,
                    regular_market=(market == "OPEN"),
                )
            else:
                cs = await candles(symbol, interval, 80, market, state, request=request)
        except HTTPException as exc:
            return {
                "status": "AGUARDANDO_FONTE",
                "stage": "ENTRADA",
                "result": None,
                "entry_result": None,
                "retry_after": 3,
                "message": str(exc.detail)[:220],
            }
        except Exception as exc:
            return {
                "status": "AGUARDANDO_FONTE",
                "stage": "ENTRADA",
                "result": None,
                "entry_result": None,
                "retry_after": 3,
                "message": str(exc)[:220],
            }

    def candle_near(target_dt):
        # 3.98.45 — apuração robusta pelo candle da ENTRADA.
        # As fontes do app não usam todas a mesma convenção no campo datetime
        # (algumas marcam abertura, outras fechamento). Primeiro aceitamos a vela
        # cujo timestamp cai no intervalo [entrada, expiração); depois usamos o
        # localizador legado. A vela ainda precisa estar fechada.
        step_seconds = float(INTERVALS[interval])
        target_ts = float(target_dt.timestamp())
        for row in reversed(list(cs or [])):
            try:
                raw_dt = row.get("datetime") or row.get("time") or row.get("timestamp")
                row_dt = parse_dt(str(raw_dt))
                row_ts = float(row_dt.timestamp())
                # timestamp de abertura
                if abs(row_ts - target_ts) <= max(2.0, step_seconds * 0.12):
                    if _verified_closed_candles([row], interval):
                        return row
                # timestamp de fechamento: target + 1 candle
                if abs(row_ts - (target_ts + step_seconds)) <= max(2.0, step_seconds * 0.12):
                    if _verified_closed_candles([row], interval):
                        return row
            except Exception:
                continue

        target, _, distance = _nearest_candle_for_time(cs, target_dt, INTERVALS[interval])
        if not target or not _verified_closed_candles([target], interval):
            return None
        if distance is not None and float(distance) > max(8.0, step_seconds * 1.10):
            return None
        return target

    def candle_result(candle):
        if candle is None:
            return None
        op = float(candle["open"])
        cl = float(candle["close"])
        if cl == op:
            return "EMPATE"
        won = (
            (direction == "CALL" and cl > op)
            or (direction == "PUT" and cl < op)
        )
        return "WIN" if won else "LOSS"

    async def ensure_candle(target_dt):
        """Localiza uma vela já fechada, atualizando o histórico só se necessário."""
        nonlocal cs
        found = candle_near(target_dt)
        if found:
            return found

        if ea_iq_result and state is not None:
            market_key = "OPEN" if market == "OPEN" else "IQ_OTC"
            cache_key = f"{market_key}|{symbol}|{interval}"
            ea_cache = state.setdefault("ea_autonomous_candle_cache", {})
            old_cache = ea_cache.pop(cache_key, None)
            fresh_ok = False
            try:
                fresh = await iq_ea_candles(
                    state, symbol, interval, 140,
                    regular_market=(market == "OPEN"),
                )
                if fresh:
                    cs = fresh
                    fresh_ok = True
            except Exception:
                fresh_ok = False
            finally:
                if not fresh_ok and cache_key not in ea_cache and old_cache is not None:
                    ea_cache[cache_key] = old_cache

            found = candle_near(target_dt)
            if found:
                return found

        elif market == "OPEN":
            # 3.97.98 — se o sinal nasceu na Binance (ex.: BTC/USD do radar),
            # apura o resultado diretamente na mesma fonte. Antes o roteador podia
            # devolver cTrader; a checagem de compatibilidade rejeitava a vela e o
            # resultado ficava aguardando por muitos minutos.
            if "BINANCE" in expected_result_feed:
                try:
                    fresh_binance = await _binance_public_candles(symbol, interval, 140)
                except Exception:
                    fresh_binance = []
                if fresh_binance:
                    cs = fresh_binance
                    found = candle_near(target_dt)
                    if found:
                        return found

            cache_key = f"{symbol}|{interval}"
            _invalidate_preexpiry_open_result_cache(symbol, interval, expiry_dt)
            old_public_cache = public_feed_cache.pop(cache_key, None)
            old_td_cache = td_candle_cache.pop(cache_key, None)
            fresh_ok = False
            try:
                fresh = await candles(symbol, interval, 140, market, state, request=request)
                if fresh:
                    cs = fresh
                    fresh_ok = True
            except Exception:
                fresh_ok = False
            finally:
                if not fresh_ok:
                    if cache_key not in public_feed_cache and old_public_cache is not None:
                        public_feed_cache[cache_key] = old_public_cache
                    if cache_key not in td_candle_cache and old_td_cache is not None:
                        td_candle_cache[cache_key] = old_td_cache

            found = candle_near(target_dt)
            if found:
                return found

            try:
                exact = await _fetch_open_result_window(symbol, interval, target_dt)
            except Exception:
                exact = []
            if exact:
                # 3.98.44 — fallback de apuração: se a fonte original estiver
                # atrasada, Twelve Data pode fechar o resultado pela mesma vela.
                cs = exact
                found = candle_near(target_dt)
                if found:
                    return found

        elif market == "IQ_OTC" and state is not None:
            cache_key = f"{symbol}|{interval}"
            iq_cache = state.setdefault("candle_cache", {})
            old_cache = iq_cache.pop(cache_key, None)
            fresh_ok = False
            try:
                fresh = await candles(symbol, interval, 160, "IQ_OTC", state, request=request)
                if fresh:
                    cs = fresh
                    fresh_ok = True
            except Exception:
                fresh_ok = False
            finally:
                if not fresh_ok and cache_key not in iq_cache and old_cache is not None:
                    iq_cache[cache_key] = old_cache

            found = candle_near(target_dt)
            if found:
                return found

        return None

    def pending_payload(stage, next_dt, entry_result="LOSS", g1_result=None):
        out = {
            "status": "PENDENTE",
            "stage": stage,
            "result": None,
            "entry_result": entry_result,
            "next_check": iso(next_dt),
            "retry_after": 5,
            "asset_cycle_locked": bool(_ai_asset_cycle_snapshot(market, symbol)),
            "asset_cycle_waiting_until": "FINAL_RESULT_UP_TO_G2",
        }
        if g1_result is not None:
            out["g1_result"] = g1_result
        return out

    def waiting_candle(stage, entry_result="LOSS", g1_result=None):
        out = {
            "status": "AGUARDANDO CANDLE",
            "stage": stage,
            "result": None,
            "entry_result": entry_result,
            "retry_after": 3,
        }
        if g1_result is not None:
            out["g1_result"] = g1_result
        return out

    def finalize(final_result, stage, final_candle, entry_result, g1_result=None, g2_result=None, final_expiry_dt=None):
        out = {
            "status": "FINALIZADA",
            "stage": stage,
            "result": final_result,
            "entry_result": entry_result,
            # Metadados fazem /performance reconhecer que o resultado salvo em
            # `results` e o resultado da contabilidade automática são a MESMA
            # operação. Sem estes campos um WIN podia entrar duas vezes.
            "market": market,
            "symbol": symbol,
            "interval": interval,
            "direction": direction,
            "candle_time": final_candle.get("datetime") if final_candle else None,
            "entry_time": iso(entry_dt),
            "expiry_time": expiry_time,
            "final_expiry_time": iso(final_expiry_dt) if final_expiry_dt else expiry_time,
            "simulated": True,
            "direct_only": bool(direct_only),
        }
        if g1_result is not None:
            out["g1_result"] = g1_result
        if g2_result is not None:
            out["g2_result"] = g2_result
        store[key] = out

        # MEGA IA 3.14: o ativo só volta a aceitar novo CALL/PUT das IAs depois
        # que esta operação tiver um resultado FINAL. A função valida ativo,
        # direção e expiry_time para não liberar por engano um ciclo mais novo.
        cycle_released = _release_ai_asset_cycle_lock(
            market, symbol, interval, direction, expiry_time, engine
        )
        if cycle_released:
            out["asset_cycle_released"] = True
            out["asset_cycle_release_reason"] = "FINAL_RESULT"

        # A contabilidade automática guarda o resultado DIRETO separadamente.
        # O resultado final com Gale permanece em `results`, evitando misturar
        # LOSS da primeira vela com LOSS final da operação.
        pending_acc, done_acc = _accounting_buckets(request, market)
        if done_acc is not None:
            acc_item = {
                "market": market,
                "symbol": symbol,
                "interval": interval,
                "direction": direction,
                "entry_time": iso(entry_dt),
                "expiry_time": expiry_time,
            }
            acc_key = _accounting_key(acc_item)
            pending_meta = dict((pending_acc or {}).get(acc_key) or {})
            direct_value = "DRAW" if entry_result == "DRAW" else ("WIN" if entry_result == "WIN" else "LOSS")
            done_acc[acc_key] = {
                **pending_meta,
                **acc_item,
                "result": direct_value,
                "final_result": final_result,
                "candle_time": final_candle.get("datetime") if final_candle else None,
            }
            if pending_acc is not None:
                pending_acc.pop(acc_key, None)
            if engine == "RTM" and direct_value in ("WIN", "LOSS"):
                _rtm_indicator_apply_result(
                    market, symbol, pending_meta.get("trigger_indicator"), direct_value, acc_key
                )

        print(
            f"[RESULTADO] {symbol} {interval} {direction} -> {final_result} "
            f"entrada={iso(entry_dt)} etapa={stage}",
            flush=True,
        )
        return out

    # Entrada original.
    base = await ensure_candle(entry_dt)
    if not base:
        print(
            f"[RESULTADO] aguardando candle {symbol} {interval} {direction} entrada={iso(entry_dt)}",
            flush=True,
        )
        return waiting_candle("ENTRADA", entry_result=None)

    base_result = candle_result(base)
    if base_result == "EMPATE":
        return finalize("DRAW", "ENTRADA", base, "DRAW", final_expiry_dt=expiry_dt)

    if base_result == "WIN":
        return finalize("WIN", "ENTRADA", base, "WIN", final_expiry_dt=expiry_dt)

    # Compatibilidade: quem pedir apenas a primeira vela recebe LOSS direto.
    if direct_only:
        return finalize("LOSS", "ENTRADA", base, "LOSS", final_expiry_dt=expiry_dt)

    # 3.98.05 — Gale opcional: mesma direção nas velas consecutivas.
    g1_expiry = expiry_dt + step
    if now() < g1_expiry:
        return pending_payload("G1", g1_expiry, entry_result="LOSS")
    g1 = await ensure_candle(expiry_dt)
    if not g1:
        return waiting_candle("G1", entry_result="LOSS")
    g1_result = candle_result(g1)
    if g1_result == "EMPATE": g1_result = "DRAW"
    if g1_result == "WIN":
        return finalize("WIN G1", "G1", g1, "LOSS", g1_result="WIN", final_expiry_dt=g1_expiry)
    if gale_levels == 1:
        if g1_result == "DRAW": return finalize("DRAW", "G1", g1, "LOSS", g1_result="DRAW", final_expiry_dt=g1_expiry)
        return finalize("LOSS G1", "G1", g1, "LOSS", g1_result="LOSS", final_expiry_dt=g1_expiry)

    g2_expiry = expiry_dt + step * 2
    if now() < g2_expiry:
        return pending_payload("G2", g2_expiry, entry_result="LOSS", g1_result=g1_result)
    g2 = await ensure_candle(expiry_dt + step)
    if not g2:
        return waiting_candle("G2", entry_result="LOSS", g1_result=g1_result)
    g2_result = candle_result(g2)
    if g2_result == "EMPATE": g2_result = "DRAW"
    if g2_result == "WIN":
        return finalize("WIN G2", "G2", g2, "LOSS", g1_result=g1_result, g2_result="WIN", final_expiry_dt=g2_expiry)
    if g2_result == "DRAW":
        return finalize("DRAW", "G2", g2, "LOSS", g1_result=g1_result, g2_result="DRAW", final_expiry_dt=g2_expiry)
    return finalize("LOSS G2", "G2", g2, "LOSS", g1_result=g1_result, g2_result="LOSS", final_expiry_dt=g2_expiry)






def _admin_ok(request: Request):
    token=(request.headers.get("X-Mega-Admin") or request.query_params.get("token") or "").strip()
    return bool(MASTER_ADMIN_TOKEN and secrets.compare_digest(token, MASTER_ADMIN_TOKEN))

@app.get("/license/validate")
async def license_validate(key: str = "", device: str = ""):
    if APP_ROLE != "PROFESSOR":
        raise HTTPException(status_code=404, detail="Disponível no Professor.")
    return _license_device_status(key,device,False)

@app.post("/license/claim")
async def license_claim(body: dict):
    if APP_ROLE != "PROFESSOR":
        raise HTTPException(status_code=404, detail="Disponível no Professor.")
    return _license_device_status(str(body.get("key", "")), str(body.get("device", "")), True)

@app.get("/professor/licenses")
async def professor_licenses(request: Request):
    if APP_ROLE != "PROFESSOR" or not _admin_ok(request):
        raise HTTPException(status_code=403, detail="Acesso negado.")
    rows=[]
    for key,row in _license_db_load().items():
        st=_license_status(key)
        rows.append({"key":key,**row,"valid":bool(st.get("valid")),"reason":st.get("reason"),"days_left":st.get("days_left")})
    rows.sort(key=lambda x:(str(x.get("name",""))).lower())
    return {"licenses":rows}

@app.post("/professor/licenses")
async def professor_license_save(body: LicenseAdminBody, request: Request):
    if APP_ROLE != "PROFESSOR" or not _admin_ok(request):
        raise HTTPException(status_code=403, detail="Acesso negado.")
    try:
        datetime.fromisoformat(body.expires_at[:10])
    except Exception:
        raise HTTPException(status_code=400, detail="Use a data AAAA-MM-DD.")
    key=(body.key or "").strip().upper()
    if not key:
        key="MEGA-"+secrets.token_hex(3).upper()+"-"+secrets.token_hex(3).upper()
    db=_license_db_load()
    created=(db.get(key) or {}).get("created_at") or datetime.now(BR_TZ).isoformat()
    engine=(body.engine or (db.get(key) or {}).get("engine") or "SCALPINGM1").strip().upper()
    allowed={"SCALPINGM1"}
    engine="SCALPINGM1"
    db[key]={"name":body.name.strip() or "Cliente","expires_at":body.expires_at[:10],"enabled":bool(body.enabled),"engine":engine,"created_at":created,"updated_at":datetime.now(BR_TZ).isoformat(),**({"device_hash":db[key]["device_hash"],"activated_at":db[key].get("activated_at")} if key in db and db[key].get("device_hash") else {})}
    _license_db_save(db)
    return {"ok":True,"key":key,"license":_license_status(key)}

@app.post("/professor/licenses/engine")
async def professor_license_engine(body: LicenseEngineBody, request: Request):
    if APP_ROLE != "PROFESSOR" or not _admin_ok(request):
        raise HTTPException(status_code=403, detail="Acesso negado.")
    allowed={"SCALPINGM1"}
    key=body.key.strip().upper(); engine=body.engine.strip().upper()
    db=_license_db_load()
    if key not in db: raise HTTPException(status_code=404, detail="Licença não encontrada.")
    if engine not in allowed: raise HTTPException(status_code=400, detail="Somente Mega Bot está disponível.")
    db[key]["engine"]=engine
    db[key]["updated_at"]=datetime.now(BR_TZ).isoformat()
    _license_db_save(db)
    _license_cache.pop(key,None)
    return {"ok":True,"license":_license_status(key)}

@app.post("/professor/licenses/toggle")
async def professor_license_toggle(body: LicenseToggleBody, request: Request):
    if APP_ROLE != "PROFESSOR" or not _admin_ok(request):
        raise HTTPException(status_code=403, detail="Acesso negado.")
    db=_license_db_load(); key=body.key.strip().upper()
    if key not in db: raise HTTPException(status_code=404, detail="Licença não encontrada.")
    db[key]["enabled"]=bool(body.enabled); db[key]["updated_at"]=datetime.now(BR_TZ).isoformat(); _license_db_save(db)
    return {"ok":True,"license":_license_status(key)}

@app.post("/professor/licenses/transfer")
async def professor_license_transfer(body: LicenseTransferBody, request: Request):
    if APP_ROLE != "PROFESSOR" or not _admin_ok(request):
        raise HTTPException(status_code=403, detail="Acesso negado.")
    with _license_lock:
        db=_license_db_load(); key=body.key.strip().upper()
        if key not in db: raise HTTPException(status_code=404,detail="Licença não encontrada.")
        db[key].pop("device_hash",None); db[key].pop("activated_at",None)
        _license_db_save(db)
    _license_cache.clear()
    return {"ok":True}

async def _client_remote_status(key: str, device: str = "", claim: bool = False):
    key=(key or "").strip().upper()
    if not key: return {"valid":False,"reason":"Informe sua licença."}
    # No próprio serviço PROFESSOR, valida diretamente no banco local.
    # Isso permite usar um único Render: /professor administra e / exige licença.
    if APP_ROLE == "PROFESSOR":
        return _license_device_status(key,device,claim)
    cached=_license_cache.get(key+":"+device)
    if not claim and cached and time.time()-float(cached.get("_ts",0)) < LICENSE_CACHE_SECONDS:
        return {k:v for k,v in cached.items() if k!="_ts"}
    if not MASTER_SERVER_URL:
        return {"valid":False,"reason":"Servidor Professor não configurado."}
    try:
        async with httpx.AsyncClient(timeout=8.0) as client:
            r=(await client.post(MASTER_SERVER_URL+"/license/claim",json={"key":key,"device":device})) if claim else (await client.get(MASTER_SERVER_URL+"/license/validate",params={"key":key,"device":device}))
            data=r.json() if r.status_code==200 else {"valid":False,"reason":f"Professor recusou a validação (HTTP {r.status_code})."}
    except Exception as exc:
        print(f"[LICENCA] Falha de comunicação com Professor: {type(exc).__name__}", flush=True)
        return {"valid":False,"reason":"Não foi possível validar com o Professor."}
    data["_ts"]=time.time(); _license_cache[key+":"+device]=data
    return {k:v for k,v in data.items() if k!="_ts"}

